local config = {
  ui_story_5084_50840100_1_dialog_content = "This is... a tomb?",
  ui_story_5084_50840100_2_dialog_content = "\"Varaki, your destiny has been revealed, and yet your heart still harbors doubts.\"",
  ui_story_5084_50840100_3_dialog_content = "It's because I understand the price to be paid. To obtain power is to become its prisoner, and forego any sense of peace for the rest of one's life.",
  ui_story_5084_50840100_4_dialog_content = "I don't wish to be like my parents and suffer because of my strength. They only found rest once every last drop of Varaki blood was gone from their veins.",
  ui_story_5084_50840100_5_dialog_content = "\"You are not a disciple of the Varaki. Like me, you worship only the Lord of Truth.\"",
  ui_story_5084_50840100_6_dialog_content = "\"As a disciple of Truth, you have traveled this world and discovered great power.\"",
  ui_story_5084_50840100_7_dialog_content = "\"If your heart truly yearns for the Lord of Truth's arrival, then you have no reason to fear any sacrifice.\"",
  ui_story_5084_50840100_8_dialog_content = "What would you have me do?",
  ui_story_5084_50840100_9_dialog_content = "\"Help me regain my power and my physical form. In exchange, I will extract the power from your body and grant you eternal rest.\"",
  ui_story_5084_50840100_10_dialog_content = "\"I find the taste of danger most exhilarating.\"",
  ui_story_5084_50840100_11_dialog_content = "\"For it allows me to savor The Truth for myself.\"",
  ui_story_5084_50840100_12_dialog_content = "What did you see, Lady Victoria?",
  ui_story_5084_50840100_13_dialog_content = "The moment in which I formed a pact with the Bloody Bible. At the time, it didn't reveal the future of this ring to me.",
  ui_story_5084_50840100_14_dialog_content = "But now it's in my hands once more... Even before laying eyes on it, I felt an ancient power calling to me.",
  ui_story_5084_50840100_15_dialog_content = "A familiar tingling sensation haunts me whenever I hold it....",
  ui_story_5084_50840100_16_dialog_content = "You share a connection with this ring?",
  ui_story_5084_50840100_17_dialog_content = "Yes. It is a relic of the ancient Varaki, passed down through the generations by the True Order's leaders.",
  ui_story_5084_50840100_18_dialog_content = "For it to return to its original owner is cause for celebration.",
  ui_story_5084_50840100_19_dialog_content = "What matters most is not the ring itself, but the timing behind its appearance.",
  ui_story_5084_50840100_20_dialog_content = "As the Advent of Truth draws near, I find this hitherto missing ring in my possession once again.",
  ui_story_5084_50840100_21_dialog_content = "...!",
  ui_story_5084_50840100_22_dialog_content = "Lady Victoria!",
  ui_story_5084_50840100_23_dialog_content = "Hahahaha... Varaki...",
  ui_story_5084_50840100_24_dialog_content = "You! Agh... Argh!",
  ui_story_5084_50840100_25_dialog_content = "Ahhhhhhhhh—!!!",
  ui_story_5084_50840100_26_dialog_content = "Lady Victoria!",
  ui_story_5084_50840100_27_dialog_content = "What I saw just now...",
  ui_story_5084_50840100_28_dialog_content = "It felt like a prophecy... And yet it seemed to have happened in the past...",
  ui_story_5084_50840100_29_dialog_content = "<color=#e8d9bb>Fwoosh—!</color>",
  ui_story_5084_50840100_30_dialog_content = "\"The catalyst has been summoned.\"",
  ui_story_5084_50840100_31_dialog_content = "\"The tomb awaits his arrival.\"",
  ui_story_5084_50840100_32_dialog_content = "\"Knowledge of The Truth must be tested and verified.\"",
  ui_story_5084_50840100_33_dialog_content = "\"A grand ceremony held beneath the old moon.\"",
  ui_story_5084_50840100_34_dialog_content = "\"The time has come.\"",
  ui_story_5084_50840100_35_dialog_content = "...",
  ui_story_5084_50840100_36_dialog_content = "This revelation seems somewhat obscure, Lady Victoria.",
  ui_story_5084_50840100_37_dialog_content = "When combined with its past predictions, the ring's revelation is actually quite clear.",
  ui_story_5084_50840100_38_dialog_content = "\"The time has finally come. An unexpected encounter will occur during the Advent of Truth.\"",
  ui_story_5084_50840100_39_dialog_content = "\"To ascertain our understanding of The Truth, we must seek the guardian of the Starry Crypt.\"",
  ui_story_5084_50840100_40_dialog_content = "\"For this endeavor, we require the aid of the Caelestite.\"",
  ui_story_5084_50840100_41_dialog_content = "This is the first time the Bloody Bible has tried to obfuscate one of its prophecies.",
  ui_story_5084_50840100_42_dialog_content = "It appears the revelations offered by this long-lost ring will connect days and events that were never witnessed.",
  ui_story_5084_50840100_43_dialog_content = "I believe I understand now.",
  ui_story_5084_50840100_44_dialog_content = "I leave you with the task of recruiting our fresh-blooded friend.",
  ui_story_5084_50840100_45_dialog_content = "Yes, Lady Victoria.",
  ui_story_5084_50840100_46_dialog_content = "I know you explained everything already, but it still makes no sense to me. Why do I have to take part in the True Order's celebration?",
  ui_story_5084_50840100_47_dialog_content = "Forgive me, but I am simply heeding the wishes of Lady Victoria and the Lord of Truth.",
  ui_story_5084_50840100_48_dialog_content = "Sigh, you guys are as vague as ever, I see...",
  ui_story_5084_50840100_49_dialog_content = "We're pretty far from Umbraton now. Where exactly are you taking me?",
  ui_story_5084_50840100_50_dialog_content = "Whoa—",
  ui_story_5084_50840100_51_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5084_50840100_52_dialog_content = "What is this dark-looking thing... And why's it moving?!",
  ui_story_5084_50840100_53_dialog_content = "Oh, so you're the one who disturbed my sleep, Snowball.",
  ui_story_5084_50840100_54_dialog_content = "... Sikare?",
  ui_story_5084_50840100_55_dialog_content = "Did I trip on your vines just now?",
  ui_story_5084_50840100_56_dialog_content = "It's not polite to keep asking questions after stepping on someone. You really should apologize, you know?",
  ui_story_5084_50840100_57_dialog_content = "S-Sorry about that... So what are you doing here, anyway?",
  ui_story_5084_50840100_58_dialog_content = "I could ask you the very same thing. What brings you here today?",
  ui_story_5084_50840100_59_dialog_content = "It's all my fault. I knew I was going to make an unforgivable mistake today.",
  ui_story_5084_50840100_60_dialog_content = "If you don't mind, Miss Sikare, I would like to repent for my sins right here and now...",
  ui_story_5084_50840100_61_dialog_content = "It appears everyone is now present, Lady Victoria.",
  ui_story_5084_50840100_62_dialog_content = "Miss Victoria...",
  ui_story_5084_50840100_63_dialog_content = "You once told me that it was not yet time, and that the secrets within the Starry Crypt were still beyond my understanding.",
  ui_story_5084_50840100_64_dialog_content = "The Bloody Bible has guided me here today.",
  ui_story_5084_50840100_65_dialog_content = "May I ask what kind of artifact you've found this time?",
  ui_story_5084_50840100_66_dialog_content = "This one.",
  ui_story_5084_50840100_67_dialog_content = "If what you say is true, then you now have the privilege of entering the Starry Crypt.",
  ui_story_5084_50840100_68_dialog_content = "What kind of place is it anyway?",
  ui_story_5084_50840100_69_dialog_content = "In layman's terms, it's a place where the dead are buried.",
  ui_story_5084_50840100_70_dialog_content = "What?! But... But Faust said that this was for the True Order's upcoming celebration!",
  ui_story_5084_50840100_71_dialog_content = "In a sense, yes. For the sake of what's to come, we must first come to this place.",
  ui_story_5084_50840100_72_dialog_content = "Don't be scared. What lies within the Starry Crypt is more valuable than all the wealth in Lumopolis combined.",
  ui_story_5084_50840100_73_dialog_content = "Countless people have come in search of the crypt's secrets, only to find themselves buried here. Consider yourselves fortunate.",
  ui_story_5084_50840100_74_dialog_content = "E-Even if it's a treasure, I... I deserve some time to think about this! Right...?",
  ui_story_5084_50840100_75_dialog_content = "Before entering the Starry Crypt, I have only three warnings to share.",
  ui_story_5084_50840100_76_dialog_content = "First, blood is the only way that Faria recognizes those who wish to enter the crypt, and only those who have formed a blood pact with it may do so.",
  ui_story_5084_50840100_77_dialog_content = "The other door opened by Faria will heed the will of the bound.",
  ui_story_5084_50840100_78_dialog_content = "This is Faria.",
  ui_story_5084_50840100_79_dialog_content = "Second, the objects you carry on your person possess a guiding presence. As they belong to time, they will naturally follow time to the places where they belong.",
  ui_story_5084_50840100_80_dialog_content = "Third, destiny has long since been determined. There is no questioning it, resenting it, or changing it.",
  ui_story_5084_50840100_81_dialog_content = "Though it looks like you still have plenty of questions, Snowball.",
  ui_story_5084_50840100_82_option_content = "A \"blood pact\"?",
  ui_story_5084_50840100_83_dialog_content = "Does this mean we have to bleed?",
  ui_story_5084_50840100_84_dialog_content = "O almighty Lord of Truth, take every last drop of my tainted blood if it is your wish...",
  ui_story_5084_50840100_85_option_content = "An \"unquestionable\" destiny?",
  ui_story_5084_50840100_86_dialog_content = "Sounds like one of those stories about getting sent to a different world.",
  ui_story_5084_50840100_87_dialog_content = "You look much more excited all of a sudden.",
  ui_story_5084_50840100_88_dialog_content = "Begin preparations, Faria.",
  ui_story_5084_50840100_89_dialog_content = "W-Wait! My blood... Will Caelestite blood even work for this sort of thing?",
  ui_story_5084_50840100_90_dialog_content = "Poke—!",
  ui_story_5084_50840100_91_dialog_content = "<size=45>Yeowch!!!</size>",
  ui_story_5084_50840100_92_dialog_content = "Didn't you hear? Sikare told Faria to get ready, so let's get moving!",
  ui_story_5084_50840100_93_dialog_content = "You have to take Mr. Beau and me with you, Lady Victoria! I promise we'll be on our best behavior!",
  ui_story_5084_50840100_94_dialog_content = "Is Lenore aware of you being here, May?",
  ui_story_5084_50840100_95_dialog_content = "She is, and she told me to have lots of fun too!",
  ui_story_5084_50840100_96_dialog_content = "Mr. Beau saved up lots of thread, which means I can stitch up as many wounds as you need!",
  ui_story_5084_50840100_97_dialog_content = "I'll take good care of you PlayerName, so don't stray too far away from me!",
  ui_story_5084_50840100_98_dialog_content = "Meow!",
  ui_story_5084_50840100_99_dialog_content = "I think it's best if I keep my distance for now...",
  ui_story_5084_50840100_100_dialog_content = "If everyone is ready now, Faria can begin.",
  ui_story_5084_50840100_101_dialog_content = "Lord of Truth, guide me to the answer I seek.",
  ui_story_5084_50840100_102_dialog_content = "Lord of Truth, bless our journey with safety and expedience.",
  ui_story_5084_50840100_103_dialog_content = "Lord of Truth, punish me for my sins.",
  ui_story_5084_50840100_104_dialog_content = "Lord of Truth, lead me to someplace fun!",
  ui_story_5084_50840100_105_dialog_content = "You can yank on my clothes all you want... I still won't...",
  ui_story_5084_50840100_106_dialog_content = "Urk...!",
  ui_story_5084_50840100_107_dialog_content = "S... Sikare...",
  ui_story_5084_50840100_108_dialog_content = "Save me...",
  ui_story_5084_50840100_109_dialog_content = "You like you're in so much pain with your eyes closed like that, Snowball.",
  ui_story_5084_50840100_110_dialog_content = "Open them and take a look around. There's no danger here.",
  ui_story_5084_50840100_111_dialog_content = "B-But those thick vines just now... They were so itchy and scary...",
  ui_story_5084_50840100_112_dialog_content = "Don't you want to know more about The Truth? Oh wait, I just remembered that you haven't joined the True Order yet.",
  ui_story_5084_50840100_113_dialog_content = "... You really don't pay attention to a lot of things, do you, Sikare?",
  ui_story_5084_50840100_114_dialog_content = "Anyway, I can't believe they disappeared just like that!",
  ui_story_5084_50840100_115_dialog_content = "The real problem is that you didn't disappear either.",
  ui_story_5084_50840100_116_dialog_content = "I need to hear you say something along the lines of \"I wish to get closer to The Truth,\" or \"I wish to surrender my thoughts and let my senses explore the world around me.\"",
  ui_story_5084_50840100_117_dialog_content = "You're a Caelestite, so you should be pretty good at something like this.",
  ui_story_5084_50840100_118_dialog_content = "You can tell me who you are, or why you're here, or where you want to go...",
  ui_story_5084_50840100_119_dialog_content = "So obscure... I just came because Faust invited me to some \"once-in-a-lifetime\" celebration.",
  ui_story_5084_50840100_120_dialog_content = "Then just think about a celebration. If you're still afraid, just feel your way around the vines and look for a candlestick.",
  ui_story_5084_50840100_121_dialog_content = "A candlestick...",
  ui_story_5084_50840100_122_dialog_content = "O-Oh, look, I actually found one...",
  ui_story_5084_50840100_123_dialog_content = "It will serve as your guide, but don't get carried away; remember to come back before the candle burns out.",
  ui_story_5084_50840100_124_dialog_content = "But... How do I do that? And where am I supposed to return to?",
  ui_story_5084_50840100_125_dialog_content = "... Sikare?",
  ui_story_5084_50840100_126_dialog_content = "Sikare!",
  ui_story_5084_50840201_1_dialog_content = "(Thank goodness I got this candlestick from Sikare, or else it'd be way too dark in here...)",
  ui_story_5084_50840201_2_dialog_content = "(Even though I still have no idea where to find the others...)",
  ui_story_5084_50840201_3_dialog_content = "Wait, is this...?",
  ui_story_5084_50840201_4_dialog_content = "<color=#e8d9bb>As ancient bells ring, countless clocktowers suddenly rise and stretch towards the blood-red moon in the night sky.</color>",
  ui_story_5084_50840201_5_dialog_content = "<color=#e8d9bb>It's crimson light shines down upon the paths of the faithful and the intricately carved walls and doorways of the town.</color>",
  ui_story_5084_50840201_6_dialog_content = "<color=#e8d9bb>It hears the confessions within the Temple of Truth, and speaks of the glory and secrets of the family of vampire...</color>",
  ui_story_5084_50840201_7_dialog_content = "<color=#e8d9bb>Hop, hop—!</color>",
  ui_story_5084_50840201_8_dialog_content = "The ground here is real... And so are these walls!",
  ui_story_5084_50840201_9_dialog_content = "It's not like the Manor of Truth, is it? A place where no one's aware of what's happening unless they're actually here...",
  ui_story_5084_50840201_10_dialog_content = "Ah yes, the blood moon has appeared. Now, the Advent of Truth, which only happens once every three years, can finally begin.",
  ui_story_5084_50840201_11_dialog_content = "My prayers are ready, and I will recite them to the Lord of Truth with all my heart during the procession.",
  ui_story_5084_50840201_12_dialog_content = "Your prayers will go unheard unless you are chosen as an \"Initiate.\" Only by sacrificing yourself will the Lord of Truth respond to your supplications.",
  ui_story_5084_50840201_13_dialog_content = "Varaki Town... Is this where the True Order is holding their \"celebration\"? The Advent of Truth... parade...",
  ui_story_5084_50840201_14_dialog_content = "How did I even get here? And where did everyone else go...?",
  ui_story_5084_50840201_15_dialog_content = "First, you have to read, learn, and interact with others. The brothers and sisters of the True Order can teach you lots of things that you'll never learn on your own.",
  ui_story_5084_50840201_16_dialog_content = "Second, you have to eat, congregate, and praise the Lord of Truth.",
  ui_story_5084_50840201_17_dialog_content = "By eating in the company of the faithful every single day, The Truth will eventually reveal itself to you.",
  ui_story_5084_50840201_18_dialog_content = "Third, you have to dig and explore. If you have any talent, you'll find treasures for everyone to admire and enjoy.",
  ui_story_5084_50840201_19_dialog_content = "If you love exploring like I used to, then there's no better family for you than the True Order.",
  ui_story_5084_50840201_20_dialog_content = "Even Mr. Beau stopped shedding so much hair after we joined!",
  ui_story_5084_50840201_21_dialog_content = "I also managed to earn Lady Victoria's respect pretty quickly, which is why she often trusts me to handle her important work on my own.",
  ui_story_5084_50840201_22_dialog_content = "Well? Doesn't that make you want to join the True Order?",
  ui_story_5084_50840201_23_dialog_content = "Meow!",
  ui_story_5084_50840201_24_dialog_content = "She seems quite confident in herself...",
  ui_story_5084_50840201_25_dialog_content = "Before preaching to us, perhaps you should dress more agreeably.",
  ui_story_5084_50840201_26_dialog_content = "Lady Victoria is a noblewoman of the Varaki Family. How could she possibly trust a little girl such as yourself to handle her affairs...?",
  ui_story_5084_50840201_27_dialog_content = "What's more, am I right to assume that this is your first time in Varaki Town?",
  ui_story_5084_50840201_28_dialog_content = "If so, allow me to enlighten you on the origins and teachings of the True Order, as well as the secrets hidden within the crypt...",
  ui_story_5084_50840201_29_dialog_content = "W-Wait, are you the seniors of the True Order...? But you're both so different from the people I know...",
  ui_story_5084_50840201_30_dialog_content = "May...!",
  ui_story_5084_50840201_31_dialog_content = "PlayerName? Why'd you drag me away?! Those two were just about to join us!",
  ui_story_5084_50840201_32_dialog_content = "Setting aside the fact that they clearly had no intention of \"joining\" you...",
  ui_story_5084_50840201_33_dialog_content = "Haven't you been listening to the people on the street? They've been talking about the Advent of Truth and some kind of procession... I'm not sure how, but we ended up in Varaki Town! Lady Victoria's hometown!",
  ui_story_5084_50840201_34_dialog_content = "Lady Victoria's hometown... Yeah, I think I've heard about it before. So what's the problem?",
  ui_story_5084_50840201_35_dialog_content = "You mean you're not surprised by any of this? Aren't you curious about where the rest of our group went?",
  ui_story_5084_50840201_36_dialog_content = "Hahaha, I get it now! Everyone's getting dressed for the celebration right now!",
  ui_story_5084_50840201_37_dialog_content = "Let's go ask where they bought their outfits and buy some for ourselves!",
  ui_story_5084_50840201_38_dialog_content = "Huh? Why are you so excited? This place looks more like a haunted tailor than any kind of store...",
  ui_story_5084_50840201_39_dialog_content = "Uh... May?",
  ui_story_5084_50840201_40_dialog_content = "Listen! The procession's coming this way! Hold my hand and don't let go!",
  ui_story_5084_50840201_41_dialog_content = "I hear the person inside that coffin is a Varaki ancestor, and that they were chosen by the Lord of Truth!",
  ui_story_5084_50840201_42_dialog_content = "<color=#e8d9bb>With the blood moon as their witness, a group of people in elegant robes march slowly through the street, bearing the palls of an ornate and ancient-looking coffin on their shoulders.</color>",
  ui_story_5084_50840201_43_dialog_content = "<color=#e8d9bb>Within the coffin lies the so-called \"ancestor\" of the Varaki, holding a sacred text and exuding The Truth along with the blood moon's light.</color>",
  ui_story_5084_50840201_44_dialog_content = "<color=#e8d9bb>The Truth's disciples follow along in reverence, not daring to take their eyes off of the coffin.</color>",
  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>Slowly and solemnly, they pass through every street in the town before arriving at the gates of the Temple of Truth.</color>",
  ui_story_5084_50840201_46_dialog_content = "<color=#e8d9bb>Creak... Thud—</color>",
  ui_story_5084_50840201_47_dialog_content = "The procession has ended, and The Truth has arrived.",
  ui_story_5084_50840201_48_dialog_content = "The faithful have approached our lord and made their offerings to him.",
  ui_story_5084_50840201_49_dialog_content = "Praise the Lord of Truth!",
  ui_story_5084_50840201_50_dialog_content = "I devote my life to the Lord of Truth!",
  ui_story_5084_50840201_51_dialog_content = "Now...",
  ui_story_5084_50840201_52_dialog_content = "One of you shall be chosen by the divine and permitted to enter this coffin of infinite revelations, to hear and receive The Truth.",
  ui_story_5084_50840201_53_dialog_content = "With its profound insight, you shall see through even the darkest secrets of history. ",
  ui_story_5084_50840201_54_dialog_content = "In this way, you shall transcend your individuality and become the embodiment of the True Order and its collective wisdom. ",
  ui_story_5084_50840201_55_dialog_content = "All that you experience shall guide our sacred order into an ever-greater future. ",
  ui_story_5084_50840201_56_dialog_content = "Once immersed in the limitless flow of nothingness, the boundaries of time and space shall dissolve around you.",
  ui_story_5084_50840201_57_dialog_content = "Only when the Lord of Truth appears and cleanses you of your ego will you attain your purest form.",
  ui_story_5084_50840201_58_dialog_content = "Listen for The Truth, awaken your mind, and ascend to a higher plane.",
  ui_story_5084_50840201_59_dialog_content = "When the time comes, you shall achieve unity with the divine.",
  ui_story_5084_50840201_60_dialog_content = "Choose me, Lord Wilhelm!",
  ui_story_5084_50840201_61_dialog_content = "I wish to hear The Truth...!",
  ui_story_5084_50840201_62_dialog_content = "I wanna hear The Truth too!",
  ui_story_5084_50840201_63_dialog_content = "Shhh! Quiet down, May!",
  ui_story_5084_50840201_64_dialog_content = "It was hard enough for us to blend in with the crowd...",
  ui_story_5084_50840201_65_dialog_content = "But if I want to be an important member of the True Order, I have to learn more about The Truth! This is a perfect opportunity for that, now go, Mr. Beau!",
  ui_story_5084_50840201_66_dialog_content = "\"Destiny has long since been determined. There is no questioning it, resenting it, or changing it.\"",
  ui_story_5084_50840201_67_dialog_content = "Meow...?",
  ui_story_5084_50840201_68_dialog_content = "Have you already forgotten the warning that Sikare gave us, May?",
  ui_story_5084_50840201_69_dialog_content = "L... Lady Victoria?!",
  ui_story_5084_50840201_70_dialog_content = "Huh? What's with that outfit?",
  ui_story_5084_50840201_71_dialog_content = "I could ask the very same. Did you get them in order to enter this place?",
  ui_story_5084_50840201_72_dialog_content = "It was May's idea. After that, we just followed the crowd all the way here.",
  ui_story_5084_50840201_73_dialog_content = "So you know where we are right now?",
  ui_story_5084_50840201_74_dialog_content = "I think so. According to those worshippers, we're in Varaki Town... Your home. It really does feel like we went to another world, you know...",
  ui_story_5084_50840201_75_dialog_content = "This is all in the past.",
  ui_story_5084_50840201_76_dialog_content = "The past?",
  ui_story_5084_50840201_77_dialog_content = "At the time, I still hadn't joined the True Order. I was traveling the world in search of The Truth for myself.",
  ui_story_5084_50840201_78_dialog_content = "We're in the year 1915. Following this Advent of Truth, the leader of the True Order disappears.",
  ui_story_5084_50840201_79_dialog_content = "... Where does he go?",
  ui_story_5084_50840201_80_dialog_content = "The Lord of Truth guided me here through that ring. It's just as Sikare said: as an object belonging to time, it guided me to its rightful place in history.",
  ui_story_5084_50840201_81_dialog_content = "The Bloody Bible is in my ancestor's possession, but the ring is still in the hands of the True Order's leader.",
  ui_story_5084_50840201_82_dialog_content = "No matter how many years pass, the curse of the Varaki bloodline can never be undone.",
  ui_story_5084_50840201_83_dialog_content = "In the endless flow of time, true enlightenment is required to answer the questions you harbor.",
  ui_story_5084_50840201_84_dialog_content = "The Truth must permeate your being in order to gain a greater understanding of the world.",
  ui_story_5084_50840201_85_dialog_content = "I, Wilhelm Varaki, leader of the True Order, under the guidance of the Lord of Truth, hereby announce the Initiate of this Advent of Truth—",
  ui_story_5084_50840201_86_dialog_content = "Victoria Varaki.",
  ui_story_5084_50840201_87_dialog_content = "What...?",
  ui_story_5084_50840201_88_dialog_content = "Victoria Varaki? Why is she here...?",
  ui_story_5084_50840201_89_dialog_content = "Heheh. Interesting.",
  ui_story_5084_50840201_90_dialog_content = "...",
  ui_story_5084_50840201_91_dialog_content = "Lady Victoria? It's her! She's really here!",
  ui_story_5084_50840201_92_dialog_content = "But she's the only daughter of the Varaki...",
  ui_story_5084_50840201_93_dialog_content = "Yes, but I hear the head of the family does not claim her as their own...",
  ui_story_5084_50840201_94_dialog_content = "...",
  ui_story_5084_50840301_1_dialog_content = "<size=30>... It's Lady Victoria!</size>",
  ui_story_5084_50840301_2_dialog_content = "Why do you look so happy?! She's been spotted by the people of the past!",
  ui_story_5084_50840301_3_dialog_content = "Doesn't that go against the rules of us being here?!",
  ui_story_5084_50840301_4_dialog_content = "Follow the guidance of your heart, and The Truth's revelations will not lead you astray.",
  ui_story_5084_50840301_5_dialog_content = "Until the next blood moon, faithful disciples. The Lord of Truth watches over us all, patiently waiting for us to draw nearer to him.",
  ui_story_5084_50840301_6_dialog_content = "May The Truth bless you.",
  ui_story_5084_50840301_7_dialog_content = "May The Truth bless you.",
  ui_story_5084_50840301_8_dialog_content = "Should we leave with them?",
  ui_story_5084_50840301_9_dialog_content = "If I may, my heart tells me to stand aside and observe in silence.",
  ui_story_5084_50840301_10_dialog_content = "Speak your mind, Victoria.",
  ui_story_5084_50840301_11_dialog_content = "I am no member of the True Order. The honor of hearing The Truth is wasted on me.",
  ui_story_5084_50840301_12_dialog_content = "And yet I heard no objections when I chose you in the Temple of Truth.",
  ui_story_5084_50840301_13_dialog_content = "Seeking The Truth and forming alliances; is this not simply your way of preparing to join the True Order in the future?",
  ui_story_5084_50840301_14_dialog_content = "My business is none of your concern.",
  ui_story_5084_50840301_15_dialog_content = "You still have yet to answer me. Tell me, what exactly is The Truth?",
  ui_story_5084_50840301_16_dialog_content = "...",
  ui_story_5084_50840301_17_dialog_content = "<color=#e8d9bb>Crrrrack—!</color>",
  ui_story_5084_50840301_18_dialog_content = "The honor of hearing The Truth... I dearly wish to hear the thoughts of one as precocious as you, Victoria Varaki. What, in your definition, is The Truth?",
  ui_story_5084_50840301_19_dialog_content = "The Truth... is knowledge.",
  ui_story_5084_50840301_20_dialog_content = "Humph, Victoria Varaki... Though we share the same bloodline, in terms of strength, wisdom, capability, and even beauty... I stand far above you.",
  ui_story_5084_50840301_21_dialog_content = "So what makes you think this ring is rightfully yours?",
  ui_story_5084_50840301_22_dialog_content = "I am a true Varaki, and the leader of the True Order!",
  ui_story_5084_50840301_23_dialog_content = "As for you... You must first demonstrate that you are worthy of our family name. Do not disappoint me.",
  ui_story_5084_50840301_24_dialog_content = "...",
  ui_story_5084_50840301_25_dialog_content = "<color=#e8d9bb>Crrrrack—!</color>",
  ui_story_5084_50840301_26_dialog_content = "Pick out words and phrases from books you cannot comprehend, and seek enlightenment from the images they conjure in your mind...",
  ui_story_5084_50840301_27_dialog_content = "Is this not your way of searching for answers?",
  ui_story_5084_50840301_28_dialog_content = "What did you see just now? What came to mind?",
  ui_story_5084_50840301_29_dialog_content = "Doubt? Fear? Denial? The power of the Varaki cannot be chosen, for the power itself chooses those who are worthy of it.",
  ui_story_5084_50840301_30_dialog_content = "...",
  ui_story_5084_50840301_31_dialog_content = "(He's wearing Victoria's family ring...)",
  ui_story_5084_50840301_32_dialog_content = "Wilhelm... I thought you said Victoria had departed from Varaki Town?",
  ui_story_5084_50840301_33_dialog_content = "Heheh, that she had.",
  ui_story_5084_50840301_34_dialog_content = "How can you be so harsh towards such a bright and promising young lady, Varaki?",
  ui_story_5084_50840301_35_dialog_content = "It has been quite some time, Lady Victoria.",
  ui_story_5084_50840301_36_dialog_content = "It has.",
  ui_story_5084_50840301_37_dialog_content = "The Lord of Truth guided me to choose her, Porfirio. The Varaki and I are powerless to change his will.",
  ui_story_5084_50840301_38_dialog_content = "Heheheh, I do not fault you for this, Wilhelm. I simply lament the stark inequality between the branches of our vampire family.",
  ui_story_5084_50840301_39_dialog_content = "Will the Lord of Truth still appear before us? Is his chosen lacking in faith or worthiness?",
  ui_story_5084_50840301_40_dialog_content = "This decision falls to the heads of the twelve branch families, not just the Varaki leader.",
  ui_story_5084_50840301_41_dialog_content = "Hahaha, yet another elegant and scathing rebuttal, Porfirio.",
  ui_story_5084_50840301_42_dialog_content = "In any case, The Truth's will is not to be ignored. Let us see... What knowledge will the Lord of Truth impart to her...",
  ui_story_5084_50840301_43_dialog_content = "Heads of families!",
  ui_story_5084_50840301_44_dialog_content = "Are there any objections to the Initiate chosen for this Advent of Truth?",
  ui_story_5084_50840301_45_dialog_content = "...",
  ui_story_5084_50840301_46_dialog_content = "No objections...",
  ui_story_5084_50840301_47_dialog_content = "Would an objection change anything at this point?",
  ui_story_5084_50840301_48_dialog_content = "Hmph.",
  ui_story_5084_50840301_49_dialog_content = "Get on with it. The Lord of Truth can wait no longer.",
  ui_story_5084_50840301_50_dialog_content = "Do not be afraid, Victoria Varaki.",
  ui_story_5084_50840301_51_dialog_content = "I will personally escort you to the temple and place you in that sacred coffin.",
  ui_story_5084_50840301_52_dialog_content = "Steady yourself in heart and mind, and prepare to share your knowledge of The Truth with our lord.",
  ui_story_5084_50840301_53_dialog_content = "...",
  ui_story_5084_50840301_54_dialog_content = "(I heard someone on the street saying that the Initiate had to \"sacrifice\" themselves... What exactly is this ceremony about...?)",
  ui_story_5084_50840301_55_dialog_content = "(I sense some serious danger coming from these heads of families...)",
  ui_story_5084_50840301_56_dialog_content = "(What will happen if Victoria actually gets sacrificed?!)",
  ui_story_5084_50840301_57_dialog_content = "(No way, I have to do something before Victoria goes into that coffin...)",
  ui_story_5084_50840301_58_option_content = "Telepathic Link",
  ui_story_5084_50840301_59_dialog_content = "You finally caught up.",
  ui_story_5084_50840301_60_dialog_content = "Something doesn't seem right here, Victoria... Are you really gonna let this guy put you in the coffin and sacrifice you?!",
  ui_story_5084_50840301_61_dialog_content = "Yes.",
  ui_story_5084_50840301_62_dialog_content = "Th-Then... What should May and I do?!",
  ui_story_5084_50840301_63_dialog_content = "Do you remember Sikare's words?",
  ui_story_5084_50840301_64_dialog_content = "Of course I do! \"Destiny has long since been determined. There is no questioning it, resenting it, or changing it.\"",
  ui_story_5084_50840301_65_dialog_content = "No questioning it...",
  ui_story_5084_50840301_66_dialog_content = "It seems you understand now.",
  ui_story_5084_50840301_67_dialog_content = "It seems you've been separated from everyone else, Caelestite.",
  ui_story_5084_50840301_68_dialog_content = "And in spite of Sikare's warning, your mind is full of questions and doubts.",
  ui_story_5084_50840301_69_dialog_content = "I think it's pretty normal to question the current situation...",
  ui_story_5084_50840301_70_dialog_content = "Just follow your intuition and witness the past unfold with me.",
  ui_story_5084_50840301_71_dialog_content = "Victoria!",
  ui_story_5084_50840301_72_dialog_content = "Now...",
  ui_story_5084_50840301_73_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_74_dialog_content = "Get in the coffin!",
  ui_story_5084_50840301_75_dialog_content = "...",
  ui_story_5084_50840301_76_dialog_content = "Wind...? Is Lady Victoria really going to lay down in there?",
  ui_story_5084_50840301_77_option_content = "Telepathic Link",
  ui_story_5084_50840301_78_dialog_content = "(It feels like something is blocking me...)",
  ui_story_5084_50840301_79_dialog_content = "Haha...",
  ui_story_5084_50840301_80_dialog_content = "Haha... Hahahaha...",
  ui_story_5084_50840301_81_dialog_content = "Hahahaha... Hahahahaha...",
  ui_story_5084_50840301_82_dialog_content = "(Those are some creepy laughs... What the heck are they up to?)",
  ui_story_5084_50840301_83_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840301_84_dialog_content = "(Even that Wilhelm guy is joining in...)",
  ui_story_5084_50840301_85_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_86_dialog_content = "PlayerName?",
  ui_story_5084_50840301_87_dialog_content = "Don't worry, May! I'm right here!",
  ui_story_5084_50840301_88_dialog_content = "What the...?!",
  ui_story_5084_50840301_89_dialog_content = "It looks like that black wind just now blew out my candle... I can't see anything in here!",
  ui_story_5084_50840301_90_dialog_content = "The way those people were laughing was so disturbing... Were they all in league with each other?",
  ui_story_5084_50840301_91_dialog_content = "Not to mention all the things that Wilhelm guy said about Victoria...",
  ui_story_5084_50840301_92_dialog_content = "She's not in danger, is she? No... I have to know what they were laughing about!",
  ui_story_5084_50840301_93_option_content = "Force Boost—",
  ui_story_5084_50840301_94_dialog_content = "(I... I can barely make anything out... What's happening here...?)",
  ui_story_5084_50840301_95_dialog_content = "Has the leadership of the True Order taken its toll after all these years, Wilhelm Varaki?",
  ui_story_5084_50840301_96_dialog_content = "You know exactly what it means for a person to enter that coffin. Surely you have an ulterior motive for choosing the daughter of <color=#FFB400>Osten Varaki</color>?",
  ui_story_5084_50840301_97_dialog_content = "He was the previous leader of the True Order and my older brother. Naturally, watching over his precious daughter is my responsibility.",
  ui_story_5084_50840301_98_dialog_content = "(Wait, so Wilhelm... Is Victoria's uncle?)",
  ui_story_5084_50840301_99_dialog_content = "I grow tired of your vainglorious words, Varaki.",
  ui_story_5084_50840301_100_dialog_content = "I'm well aware that you have not found a solution yet.",
  ui_story_5084_50840301_101_dialog_content = "If you truly have her best interests at heart, why not join her there...?",
  ui_story_5084_50840301_102_dialog_content = "Wait—",
  ui_story_5084_50840301_103_dialog_content = "What do you think you're doing, Wilhelm? This is nothing like what you said it would be.",
  ui_story_5084_50840301_104_dialog_content = "Indeed it isn't, Clavis. However, you have already made your decision.",
  ui_story_5084_50840301_105_dialog_content = "...",
  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_107_dialog_content = "(Oh no... It looks like this black wind was meant to hide everything from the very beginning...)",
  ui_story_5084_50840301_108_dialog_content = "(Clavis, Wilhelm, and Victoria... What are they planning?)",
  ui_story_5084_50840301_109_dialog_content = "Urgh, quit gripping me so tightly, PlayerName! You're gonna snap my arm in half...",
  ui_story_5084_50840301_110_dialog_content = "O-Oh, sorry...",
  ui_story_5084_50840301_111_dialog_content = "There, that's much better!",
  ui_story_5084_50840301_112_dialog_content = "I have to think of something... But what can I actually do...?",
  ui_story_5084_50840301_113_dialog_content = "And what's going on between Victoria and her uncle? Why would he sacrifice his own niece...?",
  ui_story_5084_50840301_114_dialog_content = "Are you trying to come up with a plan, PlayerName? The candle's flame is flickering... Look, the scene is starting to change.",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat...</color>",
  ui_story_5084_50840401_2_dialog_content = "That sound...!",
  ui_story_5084_50840401_3_dialog_content = "Meow?",
  ui_story_5084_50840401_4_dialog_content = "Don't be scared, Mr. Beau! I'm right here!",
  ui_story_5084_50840401_5_dialog_content = "Thank goodness you two are still there. For a second I thought I was alone again.",
  ui_story_5084_50840401_6_dialog_content = "It looks like we ended up in a new place. Something smells nice, too. Is it the smell of clean clothes...?",
  ui_story_5084_50840401_7_dialog_content = "Huh?",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5084_50840401_9_dialog_content = "S-Someone's here!",
  ui_story_5084_50840401_10_dialog_content = "Mmph... Hey, don't cover my... Mmph!",
  ui_story_5084_50840401_11_dialog_content = "... Hmph. I wore these clothes yesterday, which makes them ancient history now.",
  ui_story_5084_50840401_12_dialog_content = "And this fabric feels like sandpaper on my skin! I'm an artist, not a lowly carpenter...",
  ui_story_5084_50840401_13_dialog_content = "As for this one... The color is so woefully unimaginative... A true artist could never resign himself to wearing such lackluster colors.",
  ui_story_5084_50840401_14_dialog_content = "Bah! Were these made in a children's clothing store?! I'm more than old enough to wear adult attire!",
  ui_story_5084_50840401_15_dialog_content = "Curse it all—! I never should have taken Father's words to heart!",
  ui_story_5084_50840401_16_dialog_content = "That dull-witted duo could never fashion formal attire for the great Charon!",
  ui_story_5084_50840401_17_dialog_content = "<color=#e8d9bb>Slam!</color>",
  ui_story_5084_50840401_18_dialog_content = "...?",
  ui_story_5084_50840401_19_dialog_content = "Ch-Charon?!?",
  ui_story_5084_50840401_20_dialog_content = "Wait... can he not see us?",
  ui_story_5084_50840401_21_dialog_content = "Huff, huff... F-Finally, you let go of me! Do you know this kid, PlayerName?",
  ui_story_5084_50840401_22_dialog_content = "Yeah... That hair and those expressions... There's no mistaking \"the great Charon\" for anyone else!",
  ui_story_5084_50840401_23_dialog_content = "He was standing right in front of us just now, wasn't he?",
  ui_story_5084_50840401_24_dialog_content = "Yep, and it looks like he was picking out an outfit. Hmm... These nice-smelling clothes really are something else! I could never put together anything as good as this...",
  ui_story_5084_50840401_25_dialog_content = "So we're in Charon's closet... But from the look of things, he's hardly more than ten years old...",
  ui_story_5084_50840401_26_dialog_content = "Then again... I've never been able to guess that guy's age. Guess it doesn't really matter, since we're in the past right now.",
  ui_story_5084_50840401_27_dialog_content = "Wait... Back at the Advent of Truth, Victoria said we're in the year 1915, which means...",
  ui_story_5084_50840401_28_dialog_content = "And what's with this candle anyway? It sends me to a different place whenever it starts to flicker, and this time it brought you along too, May!",
  ui_story_5084_50840401_29_dialog_content = "You're so silly, PlayerName! Obviously, it only happened because you're holding that candle in one hand and Mr. Beau in the other!",
  ui_story_5084_50840401_30_dialog_content = "Sikare has all sorts of powerful, magical objects at her disposal. But if you don't believe in magic, then there's not much else to say.",
  ui_story_5084_50840401_31_dialog_content = "...? Aren't you worried or even curious about all the stuff we just saw?",
  ui_story_5084_50840401_32_dialog_content = "Do you mean the happy kind of curious, or the scared kind?",
  ui_story_5084_50840401_33_dialog_content = "Ah, what does it matter? I like both! Hahaha!",
  ui_story_5084_50840401_34_dialog_content = "Then is this candle the reason that Charon wasn't able to see or hear us...?",
  ui_story_5084_50840401_35_dialog_content = "The same thing happened back at the Temple of Truth... Only the Victoria from the present was able to see us.",
  ui_story_5084_50840401_36_dialog_content = "It's just like an item from one of those stories! The kind that can grant invisibility!",
  ui_story_5084_50840401_37_dialog_content = "Hahaha, no kidding!",
  ui_story_5084_50840401_38_dialog_content = "We don't know what happened to Victoria after she went into that coffin, or where Nails and Faust are right now...",
  ui_story_5084_50840401_39_dialog_content = "Did we really come here by following the guidance of our hearts...?",
  ui_story_5084_50840401_40_dialog_content = "What are you thinking about earlier?",
  ui_story_5084_50840401_41_dialog_content = "You mean when the candlelight started to flicker? It was something like...",
  ui_story_5084_50840401_42_dialog_content = "\"Clavis, Wilhelm, and Victoria... What are they planning?\"",
  ui_story_5084_50840401_43_dialog_content = "If Charon's father and that \"dull-witted duo\" are the three of them...",
  ui_story_5084_50840401_44_dialog_content = "Maybe this is what Sikare meant when she said the candle would be my guide!",
  ui_story_5084_50840401_45_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5084_50840401_46_dialog_content = "I do this only to preserve the unbiased nature of my art. These socks are my greatest treasures, but I will begrudgingly change them for their sake.",
  ui_story_5084_50840401_47_dialog_content = "(Charon's so serious when it comes to changing his clothes...)",
  ui_story_5084_50840401_48_dialog_content = "\"Oh Lord Charon, where do you find to purchase such mesmerizingly magnificent socks?\"",
  ui_story_5084_50840401_49_dialog_content = "\"No one's tastes could ever match your own, Lord Charon...\"",
  ui_story_5084_50840401_50_dialog_content = "Hmph, so this is what it is to be famous? Such a troublesome existence...",
  ui_story_5084_50840401_51_dialog_content = "<color=#e8d9bb>Slam!</color>",
  ui_story_5084_50840401_52_dialog_content = "...",
  ui_story_5084_50840401_53_dialog_content = "He's been different from everyone since he was a kid, huh...",
  ui_story_5084_50840401_54_dialog_content = "Let's go take a look around, May. Don't stray too far from me though!",
  ui_story_5084_50840401_55_dialog_content = "I know, I know!",
  ui_story_5084_50840401_56_dialog_content = "Long time no see, Clavis.",
  ui_story_5084_50840401_57_dialog_content = "Hello, Uncle Clavis.",
  ui_story_5084_50840401_58_dialog_content = "It's Lady Victoria! Hey—",
  ui_story_5084_50840401_59_dialog_content = "Calm down, May! Even though she isn't responding, I'm sure she already noticed us from this distance. This must be another version of her past self, right?",
  ui_story_5084_50840401_60_dialog_content = "Although she doesn't look much different from the Victoria we know in the present...",
  ui_story_5084_50840401_61_dialog_content = "That's because she's a noble member of the family of vampire! Once she awakened her power, the aging process stopped for her.",
  ui_story_5084_50840401_62_dialog_content = "And why are you still hiding if the people in the past can't see us, PlayerName?",
  ui_story_5084_50840401_63_dialog_content = "Huh?! Oh yeah... Maybe it's because everything and everyone around here looks a little scary?",
  ui_story_5084_50840401_64_dialog_content = "Haha... Seeing you both here at the same time is quite a rare sight.",
  ui_story_5084_50840401_65_dialog_content = "Hmph...",
  ui_story_5084_50840401_66_dialog_content = "Where is young Charon?!?",
  ui_story_5084_50840401_67_dialog_content = "Oh, you know that boy. As soon as he knows we're expecting company, he spends hours making himself presentable...",
  ui_story_5084_50840401_68_dialog_content = "...",
  ui_story_5084_50840401_69_dialog_content = "Hey, Lord Charon. Nice socks you have there.",
  ui_story_5084_50840401_70_dialog_content = "S-Say whatever you want, I still won't...",
  ui_story_5084_50840401_71_dialog_content = "Mind your manners, Charon.",
  ui_story_5084_50840401_72_dialog_content = "... Hello, Uncle Wilhelm.",
  ui_story_5084_50840401_73_dialog_content = "Aren't you forgetting someone? This is Victoria, your Uncle Wilhelm's niece.",
  ui_story_5084_50840401_74_dialog_content = "Hello, cousin.",
  ui_story_5084_50840401_75_dialog_content = "... Hello, cousin.",
  ui_story_5084_50840401_76_dialog_content = "Charon, why don't you take Victoria to the other room and have some tea and desserts?",
  ui_story_5084_50840401_77_dialog_content = "... Yes, Father.",
  ui_story_5084_50840401_78_dialog_content = "I'm surprised you have time to visit us here in Old Town. Are matters back in Varaki Town more or less resolved?",
  ui_story_5084_50840401_79_dialog_content = "Coming here was anything but easy, but you know I would travel any distance to see you, Clavis.",
  ui_story_5084_50840401_80_dialog_content = "...",
  ui_story_5084_50840401_81_dialog_content = "...",
  ui_story_5084_50840401_82_dialog_content = "How long are you going to keep staring at me?",
  ui_story_5084_50840401_83_dialog_content = "Are you in league with the rest of those wretched people?",
  ui_story_5084_50840401_84_dialog_content = "Which wretched people, exactly?",
  ui_story_5084_50840401_85_dialog_content = "You know, those cultists who are just like Wilhelm Varaki.",
  ui_story_5084_50840401_86_dialog_content = "If you mean the True Order, then no, I'm not one of them. It's also rather improper to refer to their leader by his full name, don't you think?",
  ui_story_5084_50840401_87_dialog_content = "Call it an artist's intuition, but no one who associates with him is up to anything good. It was only at my father's behest that I appeared before you today.",
  ui_story_5084_50840401_88_dialog_content = "You say you can't stand your father's associate, and yet you went to such great lengths to make yourself presentable.",
  ui_story_5084_50840401_89_dialog_content = "...! I-It's all for the sake of art!",
  ui_story_5084_50840401_90_dialog_content = "Oh? Then what exactly is art?",
  ui_story_5084_50840401_91_dialog_content = "You're aware that we must all die someday, yes? However, there is one thing in this world that can never die; do you know what that is?",
  ui_story_5084_50840401_92_dialog_content = "It's art!",
  ui_story_5084_50840401_93_dialog_content = "Art is a forbidden flower that can bloom in the depths of hell! An unstoppable train that arises from the waters of the river Styx.",
  ui_story_5084_50840401_94_dialog_content = "And I will become its conductor, a ferryman of souls, and an eternal work of art.",
  ui_story_5084_50840401_95_dialog_content = "An eternal work of art, you say... Heheh, it seems I'm destined to become your passenger someday.",
  ui_story_5084_50840401_96_dialog_content = "But of course! No, wait... Ever since those wretched fools mocked my artistry...",
  ui_story_5084_50840401_97_dialog_content = "A child of this age should not be so obsessed with urinals...",
  ui_story_5084_50840401_98_dialog_content = "... Like a man who is too deep in his cups, his careless frivolity is almost amusing.",
  ui_story_5084_50840401_99_dialog_content = "Ever since that day, I decided that only those who appreciate my art can board my train...",
  ui_story_5084_50840401_100_dialog_content = "I refuse to accept anyone who has lived too long, behaves too rudely, or has no taste in art.",
  ui_story_5084_50840401_101_dialog_content = "You're quite confident in yourself, Charon.",
  ui_story_5084_50840401_102_dialog_content = "That's only natural, since no one else in Old Town has tastes that rival my own.",
  ui_story_5084_50840401_103_dialog_content = "And someday, I'll establish my very own theater troupe, as well as groups for appreciating things like music, art, and model trains...",
  ui_story_5084_50840401_104_dialog_content = "I don't mind telling you, since I've long since discovered the so-called \"truth\" that those fools are always prattling about. It's art, plain and simple.",
  ui_story_5084_50840401_105_dialog_content = "Well? Since you haven't found an organization to join, are you courageous enough to brave my admission process?",
  ui_story_5084_50840401_106_dialog_content = "Heheh, interesting. And what exactly is this \"admission process\" of yours?",
  ui_story_5084_50840401_107_dialog_content = "It's simple really. When you see my train pass by, mobilize all of your senses and enter my world of art! Afterward, you'll have to demonstrate your understanding of art as well.",
  ui_story_5084_50840401_108_dialog_content = "Very well, I accept.",
  ui_story_5084_50840401_109_dialog_content = "Then just wait right there. Father doesn't approve of me showing these things to other people.",
  ui_story_5084_50840401_110_dialog_content = "Now feast your eyes on a conductor's performance and witness the true meaning of art!",
  ui_story_5084_50840401_111_dialog_content = "<color=#e8d9bb>Moments later...</color>",
  ui_story_5084_50840401_112_dialog_content = "Listen closely! The train tracks echo with the cries of the apocalypse!",
  ui_story_5084_50840401_113_dialog_content = "Witness the final train departing from a dying world and into eternity! ",
  ui_story_5084_50840401_114_dialog_content = "Only artists who aspire to immortality may board it and travel beyond the glorious heavens! ",
  ui_story_5084_50840401_115_dialog_content = "Freed from the chains which imprisoned its body, its unbound wheels turn endlessly as it presses on forevermore!",
  ui_story_5084_50840401_116_dialog_content = "The engine points towards the sky and I, the great Charon, am its conductor! Together, we will escape this accursed abyss!",
  ui_story_5084_50840401_117_dialog_content = "I will command hell itself to throw open its gates and let in the light of a new world!",
  ui_story_5084_50840401_118_dialog_content = "Wow... I think I actually see a train in the darkness...",
  ui_story_5084_50840401_119_dialog_content = "That's Charon for you... No matter where he goes, the world is his stage...",
  ui_story_5084_50840401_120_dialog_content = "Ka-chunk, ka-chunk, ka-chunk—! Listen to the symphony of old and new worlds as it escapes my mouth! Do not fear the sound!",
  ui_story_5084_50840401_121_dialog_content = "Now drive! Drive until we burst through the doors of the new world! An immortal paradise awaits us!",
  ui_story_5084_50840401_122_dialog_content = "...",
  ui_story_5084_50840401_123_dialog_content = "It's your turn now, cousin!",
  ui_story_5084_50840401_124_dialog_content = "Heheh, you certainly have a flair for the dramatic, but this \"door to a new world\" is nothing but an illusion!",
  ui_story_5084_50840401_125_dialog_content = "The \"door\" you so desperately seek is more like a shapeless wall that will violently slam itself into your face!",
  ui_story_5084_50840401_126_dialog_content = "The train tracks will ignite, and this red-and-gold behemoth will burn your dreams to ashes.",
  ui_story_5084_50840401_127_dialog_content = "Death is the absolute Truth! A prelude to the end must be offered in tribute! Immortality is but endless fear and panic!",
  ui_story_5084_50840401_128_dialog_content = "Fear will crush you into an insignificant insect and trap you in the cage of eternity with no hope of escape.",
  ui_story_5084_50840401_129_dialog_content = "A helpless plaything to be watched and tormented by even higher beings!",
  ui_story_5084_50840401_130_dialog_content = "Look up!",
  ui_story_5084_50840401_131_dialog_content = "This is the reality of the new world—An endless cycle of manipulation!",
  ui_story_5084_50840401_132_dialog_content = "...!",
  ui_story_5084_50840401_133_dialog_content = "In the eyes of our hidden overlords, your madness only serves as their amusement.",
  ui_story_5084_50840401_134_dialog_content = "The power to inspire fear is true art!",
  ui_story_5084_50840401_135_dialog_content = "... Waaaahhhh!",
  ui_story_5084_50840401_136_dialog_content = "... Cousin, you—!",
  ui_story_5084_50840401_137_dialog_content = "This is much more exciting than eternal art, isn't it?",
  ui_story_5084_50840401_138_dialog_content = "Hahahahahahaha...!",
  ui_story_5084_50840401_139_dialog_content = "... Waaaahhhh!!!",
  ui_story_5084_50840401_140_dialog_content = "M-My train... Stop it! Stop it right now!",
  ui_story_5084_50840401_141_dialog_content = "Hahahahahahaha...",
  ui_story_5084_50840401_142_dialog_content = "I had no idea Lady Victoria had such a funny little cousin.",
  ui_story_5084_50840401_143_dialog_content = "Huh? I think you're missing the real issue here... How could Victoria be so mean to Charon?!",
  ui_story_5084_50840401_144_dialog_content = "No wonder he's always reluctant to talk about Victoria as his relative... What kind of art is this?!",
  ui_story_5084_50840401_145_dialog_content = "I cannot agree with that, Wilhelm...",
  ui_story_5084_50840401_146_dialog_content = "What are you so afraid of, Clavis? Or do you truly fail to see the worsening of our situation?",
  ui_story_5084_50840401_147_dialog_content = "Porfirio and the heads of families have stopped following the rules after branching off the Varaki bloodline.",
  ui_story_5084_50840401_148_dialog_content = "You won't save anyone like this.",
  ui_story_5084_50840401_149_dialog_content = "But in its current state, the True Order is nothing but a scourge to us and to the people of this town! The precepts of the blood families imprison us all!",
  ui_story_5084_50840401_150_dialog_content = "Bloodthirst is in our nature, Wilhelm... In our very blood. And though you and I are slightly more fortunate than the rest, we are no different in this respect.",
  ui_story_5084_50840401_151_dialog_content = "Our nature, you say...? When did you start concerning yourself with this sort of talk, Clavis?",
  ui_story_5084_50840401_152_dialog_content = "Do not fault me for this, Wilhelm. I simply cannot deny what I know to be true...",
  ui_story_5084_50840401_153_dialog_content = "That <color=#FFB400>key</color> will only bring you harm.",
  ui_story_5084_50840401_154_dialog_content = "Just before he died, my brother took it back from the <color=#FFB400>Vinekeepers</color> and gave it to you... Clearly, it was to ensure that the key would make it into my hands someday.",
  ui_story_5084_50840401_155_dialog_content = "... Or perhaps it was to prevent you from forcibly taking it from the <color=#FFB400>Vinekeepers</color> yourself.",
  ui_story_5084_50840401_156_dialog_content = "Despite your unorthodox ways, you have already led the True Order as your brother's successor for many years now.",
  ui_story_5084_50840401_157_dialog_content = "All that has come to pass was predicted in an ancient prophecy.",
  ui_story_5084_50840401_158_dialog_content = "The course of destiny cannot be altered. You know this better than I.",
  ui_story_5084_50840401_159_dialog_content = "No! I refuse to accept it!",
  ui_story_5084_50840401_160_dialog_content = "I place my faith in the Lord of Truth; the fate of the Varaki is of no concern to me! At the very least, I refuse to accept this so-called \"course of destiny...\"",
  ui_story_5084_50840401_161_dialog_content = "No matter what befalls me, I will endure it. I must.",
  ui_story_5084_50840401_162_dialog_content = "From the very beginning, I've only ever followed my heart's guidance. To me, that is The Truth.",
  ui_story_5084_50840401_163_dialog_content = "And what of Victoria? Your brother entrusted you with her—",
  ui_story_5084_50840401_164_dialog_content = "There is no need to mention him, Clavis.",
  ui_story_5084_50840401_165_dialog_content = "Victoria's disdain for our power and her indifference towards Varaki Town's affairs are even greater than mine. She can take care of herself.",
  ui_story_5084_50840401_166_dialog_content = "Heheh... Perhaps this is also punishment for my brother's actions.",
  ui_story_5084_50840401_167_dialog_content = "Wilhelm...",
  ui_story_5084_50840401_168_dialog_content = "In any case... Please take good care of your family, Clavis.",
  ui_story_5084_50840401_169_dialog_content = "... Waaaahhhh!!!",
  ui_story_5084_50840401_170_dialog_content = "...",
  ui_story_5084_50840401_171_dialog_content = "It's time for us to leave, Victoria Varaki.",
  ui_story_5084_50840401_172_dialog_content = "...",
  ui_story_5084_50840401_173_dialog_content = "Already? But I still haven't learned anything... I have to find a way to catch up to them... Wait, that's it! I just have to focus, and...",
  ui_story_5084_50840401_174_dialog_content = "It's working! The candle's starting to flicker! Hurry—",
  ui_story_5084_50840401_175_dialog_content = "Dry your tears, Charon...",
  ui_story_5084_50840401_176_dialog_content = "Curse her... Curse that madwoman...!",
  ui_story_5084_50840401_177_dialog_content = "Enough! Now, pick up all of those broken pieces!",
  ui_story_5084_50840401_178_dialog_content = "... Sniff...",
  ui_story_5084_50840501_1_dialog_content = "I think I've got the hang of it now. When the candle started to flicker, I began wondering what Wilhelm was thinking.",
  ui_story_5084_50840501_2_dialog_content = "So does that mean... We're in Lord Wilhelm's house now?",
  ui_story_5084_50840501_3_dialog_content = "It's him! Lord Wilhelm!",
  ui_story_5084_50840501_4_dialog_content = "He looks really sad holding that ring...",
  ui_story_5084_50840501_5_dialog_content = "We still don't know what he's actually thinking, though.",
  ui_story_5084_50840501_6_dialog_content = "You're the legendary Last Caelestite, aren't you? Just eavesdrop on his thoughts already!",
  ui_story_5084_50840501_7_dialog_content = "D-Don't call it \"eavesdropping\"! That's not what my powers are for!",
  ui_story_5084_50840501_8_dialog_content = "Well how else are we supposed to figure out what he's up to?!",
  ui_story_5084_50840501_9_dialog_content = "...",
  ui_story_5084_50840501_10_dialog_content = "Now quit wasting time! As an adult, you need to be more decisive!",
  ui_story_5084_50840501_11_dialog_content = "Fine! I'm pretty sure it's not against Sikare's rules if I just read his thoughts a little...",
  ui_story_5084_50840501_12_option_content = "Mind Link—",
  ui_story_5084_50840501_13_dialog_content = "The whispers trapped within this relic... By simply wearing it, I will experience the pain of being devoured countless times in an instant...",
  ui_story_5084_50840501_14_dialog_content = "The Varaki... And the rest of the family of vampire... Is there really escaping our fate...?",
  ui_story_5084_50840501_15_dialog_content = "Born as Aurorians yet cursed to live in this dark and sunless town, where power can only be passed through inheritance.",
  ui_story_5084_50840501_16_dialog_content = "Under the guidance of our ancestors, we run, hide, and lead lives that are no better than death...",
  ui_story_5084_50840501_17_dialog_content = "The will of our ancestors... The succession of power... How utterly meaningless. The Varaki will forsake our future generations before ceding any ounce of control.",
  ui_story_5084_50840501_18_dialog_content = "And though we have learned to subsist on blood substitutes, there is no getting rid of the source of our evil power.",
  ui_story_5084_50840501_19_dialog_content = "(Blood substitutes... The \"nectar of life\" that Victoria keeps talking about... Could it be...?)",
  ui_story_5084_50840501_20_dialog_content = "Curse this infernal ring...",
  ui_story_5084_50840501_21_dialog_content = "Curse it all...",
  ui_story_5084_50840501_22_dialog_content = "With each passing year, the heads of families grow hungrier for fresh blood...",
  ui_story_5084_50840501_23_dialog_content = "Sigh, Clavis... It has been three years since we last spoke. I wonder how he's faring these days?",
  ui_story_5084_50840501_24_dialog_content = "(It's been three years since Wilhelm and Victoria visited Charon's father? Wait... So what year is it now?)",
  ui_story_5084_50840501_25_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5084_50840501_26_dialog_content = "...",
  ui_story_5084_50840501_27_dialog_content = "It's Victoria...",
  ui_story_5084_50840501_28_dialog_content = "But that presence... Looks like it's still the past version of her.",
  ui_story_5084_50840501_29_dialog_content = "It's Lady Victoria from the past again! So, have you heard anything important just now?",
  ui_story_5084_50840501_30_dialog_content = "Wilhelm put away the ring as soon as Victoria walked into the room. Now it feels like something is blocking my powers...",
  ui_story_5084_50840501_31_dialog_content = "So you can't read his thoughts anymore?",
  ui_story_5084_50840501_32_dialog_content = "That's right... I think that ring is putting his psyche under enormous strain. Let's just see what they have to say this time.",
  ui_story_5084_50840501_33_dialog_content = "Ugh...",
  ui_story_5084_50840501_34_dialog_content = "Welcome back... You were gone for three months this time. How did you fare?",
  ui_story_5084_50840501_35_dialog_content = "... That's none of your concern.",
  ui_story_5084_50840501_36_dialog_content = "The look in your eyes... So full of resentment and uncertainty...",
  ui_story_5084_50840501_37_dialog_content = "What did you see in the outside world, Wilhelm Varaki?",
  ui_story_5084_50840501_38_dialog_content = "I don't recall letting you enter my room.",
  ui_story_5084_50840501_39_dialog_content = "You're the leader of the True Order, and yet you regularly leave without fulfilling your duties... You've been spending less time at home, as well.",
  ui_story_5084_50840501_40_dialog_content = "How many times must I tell you that it's none of your concern?! Now leave me!",
  ui_story_5084_50840501_41_dialog_content = "Very well then; I am no stranger to being denied your conversation. But given that tonight is the Advent of Truth, I was hoping we could have one final discussion.",
  ui_story_5084_50840501_42_dialog_content = "About The Truth, and ourselves...",
  ui_story_5084_50840501_43_dialog_content = "I said get out! Do not make me repeat myself!",
  ui_story_5084_50840501_44_dialog_content = "...",
  ui_story_5084_50840501_45_dialog_content = "Lord Wilhelm is so hostile now... What could've happened to him...?",
  ui_story_5084_50840501_46_dialog_content = "... Nngh... <size=45>Arrrgh...!</size>",
  ui_story_5084_50840501_47_dialog_content = "Something's wrong with Lord Wilhelm... Quick, do something!",
  ui_story_5084_50840501_48_dialog_content = "Is it that ring...?",
  ui_story_5084_50840501_49_option_content = "Mindlink—",
  ui_story_5084_50840501_50_dialog_content = "Hahahahaha! Bite off her fingers! Break her pretty little neck!",
  ui_story_5084_50840501_51_dialog_content = "Be silent...",
  ui_story_5084_50840501_52_dialog_content = "How utterly foolish. In your desperation to maintain power, you willingly wear a ring that drives you mad before the true leader of your people.",
  ui_story_5084_50840501_53_dialog_content = "Do you wish to end her life... Or your own?",
  ui_story_5084_50840501_54_dialog_content = "Heheh... I grew numb to the pain you inflicted upon me long ago...",
  ui_story_5084_50840501_55_dialog_content = "The Varaki shall be destroyed in your hands.",
  ui_story_5084_50840501_56_dialog_content = "Heh... If I am destined for destruction, then the True Order will share in my fate...",
  ui_story_5084_50840501_57_dialog_content = "She has made many new alliances. Once the Varaki bloodline is eradicated, the True Order will be born anew.",
  ui_story_5084_50840501_58_dialog_content = "She will be the one to end the Varaki once and for all.",
  ui_story_5084_50840501_59_dialog_content = "Including me?",
  ui_story_5084_50840501_60_dialog_content = "Only by dying at their hands will you truly start to live...",
  ui_story_5084_50840501_61_dialog_content = "Do you even hear yourself right now?",
  ui_story_5084_50840501_62_dialog_content = "Yes, and I'm telling you to die!!",
  ui_story_5084_50840501_63_dialog_content = "(These voices are terrifying! It's like they're eating away at Wilhelm's consciousness...)",
  ui_story_5084_50840501_64_dialog_content = "(Could it be that this ring grants its wearer enormous power in exchange for causing them immense suffering?)",
  ui_story_5084_50840501_65_dialog_content = "(It sounds a lot like something from the True Order, that's for sure...)",
  ui_story_5084_50840501_66_dialog_content = "(And whose voices are those? The Varaki ancestors? The original owner of the ring? Or maybe...)",
  ui_story_5084_50840501_67_dialog_content = "<size=45>Urgh... Ahhhhhhhhh!</size>",
  ui_story_5084_50840501_68_dialog_content = "Struggle against destiny to your heart's content...",
  ui_story_5084_50840501_69_dialog_content = "Get... Out!!!",
  ui_story_5084_50840501_70_dialog_content = "Know your limits, fool.",
  ui_story_5084_50840501_71_dialog_content = "My body... <size=45>Get out of my body!!!</size>",
  ui_story_5084_50840501_72_dialog_content = "Lord of Truth...! Show me the way!!!",
  ui_story_5084_50840501_73_dialog_content = "(Wilhelm's about to pass out!)",
  ui_story_5084_50840501_74_dialog_content = "(These voices are turning into monsters in his mind. I might be able to do something here!)",
  ui_story_5084_50840502_1_dialog_content = "Oh? It seems you've learned a new ability, Wilhelm...",
  ui_story_5084_50840502_2_dialog_content = "Your mind... So calm and stable...",
  ui_story_5084_50840502_3_dialog_content = "...",
  ui_story_5084_50840502_4_dialog_content = "(Uh-oh! Don't tell me they noticed me...)",
  ui_story_5084_50840502_5_dialog_content = "As a reward, I'll let you see something interesting.",
  ui_story_5084_50840502_6_dialog_content = "May The Truth bless him.",
  ui_story_5084_50840502_7_dialog_content = "Finally... Another grand accomplishment is now complete.",
  ui_story_5084_50840502_8_dialog_content = "The blood of a disciple... How I've yearned for its taste...",
  ui_story_5084_50840502_9_dialog_content = "What knowledge did you glean from The Truth?",
  ui_story_5084_50840502_10_dialog_content = "The Truth showed me but one thing... Gratitude.",
  ui_story_5084_50840502_11_dialog_content = "Only under the light of a blood moon can we truly quell our thirst for blood.",
  ui_story_5084_50840502_12_dialog_content = "The faithful dance wildly as they pray, offering their self-castigated bodies to a god they can never truly comprehend.",
  ui_story_5084_50840502_13_dialog_content = "For centuries... They have lived this way...",
  ui_story_5084_50840502_14_dialog_content = "But this delicious taste deserves far more appreciation...",
  ui_story_5084_50840502_15_dialog_content = "Why not select a few more faithful disciples for this year's Advent of Truth?",
  ui_story_5084_50840502_16_dialog_content = "Is this the knowledge you gained from consuming the blood of this faithful servant?",
  ui_story_5084_50840502_17_dialog_content = "Not entirely.",
  ui_story_5084_50840502_18_dialog_content = "When The Truth flows through their bodies, we consume their blood in order to gain this knowledge and pass it on to future generations.",
  ui_story_5084_50840502_19_dialog_content = "This is the covenant between us, the heads of family, and the faithful.",
  ui_story_5084_50840502_20_dialog_content = "Such sacrifices are meaningless if they do not allow us to witness Truth.",
  ui_story_5084_50840502_21_dialog_content = "Was anything revealed to you?",
  ui_story_5084_50840502_22_dialog_content = "Of course.",
  ui_story_5084_50840502_23_dialog_content = "Let me remind you of our tenets and our need for secrecy.",
  ui_story_5084_50840502_24_dialog_content = "As heads of families, you are obligated to uphold them. Under no circumstances are we permitted to return to our old, barbaric ways.",
  ui_story_5084_50840502_25_dialog_content = "May The Truth bless you.",
  ui_story_5084_50840502_26_dialog_content = "May The Truth bless you.",
  ui_story_5084_50840502_27_dialog_content = "These visions were revealed to me long ago, when the power of my bloodline was awakened.",
  ui_story_5084_50840502_28_dialog_content = "An ancient ritual for the Advent of Truth, in which our ancestors wholly consume the blood of a sacrifice to gain divine inspiration.",
  ui_story_5084_50840502_29_dialog_content = "Wait... Does this mean the Initiate gets eaten during every Advent of Truth?!",
  ui_story_5084_50840502_30_dialog_content = "No wonder they were laughing like that earlier!!",
  ui_story_5084_50840502_31_dialog_content = "Did Victoria really get sacrificed like this?!",
  ui_story_5084_50840502_32_dialog_content = "Is someone there...?",
  ui_story_5084_50840502_33_dialog_content = "Oh? It appears you have a visitor, Wilhelm.",
  ui_story_5084_50840502_34_dialog_content = "...",
  ui_story_5084_50840502_35_dialog_content = "Uh, PlayerName... What did you do? Lord Wilhelm doesn't see us, does he?",
  ui_story_5084_50840502_36_dialog_content = "Sorry... I must've gotten too worked up just now...",
  ui_story_5084_50840502_37_dialog_content = "But I saw some really disturbing stuff in Wilhelm's mind...",
  ui_story_5084_50840502_38_dialog_content = "I'm still pretty worried about Victoria, so I'll try again!",
  ui_story_5084_50840502_39_option_content = "Mindlink—",
  ui_story_5084_50840502_40_dialog_content = "What about these?",
  ui_story_5084_50840502_41_dialog_content = "Even after offering your own niece, the Lord of Truth did not grace you with any revelations. Has your own failure finally driven you mad?",
  ui_story_5084_50840502_42_dialog_content = "It matters not. I've long since grown tired of your games, Wilhelm.",
  ui_story_5084_50840502_43_dialog_content = "The Bloody Bible is mine now! The Truth is within my reach!",
  ui_story_5084_50840502_44_dialog_content = "...! Is this a prophecy...? The Advent of Truth... Tonight...",
  ui_story_5084_50840502_45_dialog_content = "(It's that guy I saw in the temple earlier! They're about to sacrifice Victoria for the Advent of Truth... Which means we're back in the year 1915!)",
  ui_story_5084_50840502_46_dialog_content = "Still don't believe me?",
  ui_story_5084_50840502_47_dialog_content = "... Is this how my life ends?",
  ui_story_5084_50840502_48_dialog_content = "You still fail to comprehend the power of the Varaki, yet you would sentence the family of vampire to death because of your own misfortune.",
  ui_story_5084_50840502_49_dialog_content = "The youth always turn their noses up at the dogma of their predecessors.",
  ui_story_5084_50840502_50_dialog_content = "But you were never the leader of the True Order to begin with.",
  ui_story_5084_50840502_51_dialog_content = "Heheh... Hahahaha...",
  ui_story_5084_50840502_52_dialog_content = "The Truth? How preposterous...",
  ui_story_5084_50840502_53_dialog_content = "Did you spend so much time on my brother's hand that you inherited his ill temper?",
  ui_story_5084_50840502_54_dialog_content = "He cursed me by entrusting the family and his daughter to me... And now Victoria, the true leader of the order, has left...",
  ui_story_5084_50840502_55_dialog_content = "He allowed himself to be fooled by a false vision of the future, letting it warp and manipulate him to someone else's own ends.",
  ui_story_5084_50840502_56_dialog_content = "A feeling I know all too well...",
  ui_story_5084_50840502_57_dialog_content = "I made that mistake before. Am I capable of doing so again?",
  ui_story_5084_50840502_58_dialog_content = "Do you truly wish to spare Victoria?",
  ui_story_5084_50840502_59_dialog_content = "I do.",
  ui_story_5084_50840502_60_dialog_content = "You hesitated.",
  ui_story_5084_50840502_61_dialog_content = "The ones who wish to see her dead are the other heads of families. As the second son of the Varaki, my death would be of no consequence; what they truly fear is seeing Victoria rise to power.",
  ui_story_5084_50840502_62_dialog_content = "If the prophecy is true...",
  ui_story_5084_50840502_63_dialog_content = "The power in Victoria's bloodline awakened relatively late, and she was unresponsive to The Truth that I conveyed to her.",
  ui_story_5084_50840502_64_dialog_content = "If I die, those parasites will never let her go...",
  ui_story_5084_50840502_65_dialog_content = "Victoria... Victoria...",
  ui_story_5084_50840502_66_dialog_content = "(Huh? Is he worried about Victoria?)",
  ui_story_5084_50840502_67_dialog_content = "That's right! As leader of the True Order, I am the one who declares the Initiate! But...",
  ui_story_5084_50840502_68_dialog_content = "She said she had no intention of being at the Advent of Truth tonight... Where could she possibly be...?",
  ui_story_5084_50840502_69_dialog_content = "That means Victoria showed up in the temple at the worst possible time! She really did get sacrificed!",
  ui_story_5084_50840502_70_dialog_content = "Who's there? Show yourself...",
  ui_story_5084_50840502_71_dialog_content = "(Oh no, not again...!)",
  ui_story_5084_50840502_72_dialog_content = "Heheh, so you have a contingency in mind?",
  ui_story_5084_50840502_73_dialog_content = "PlayerName! Did you do something again?!",
  ui_story_5084_50840502_74_dialog_content = "It's over... As soon as he mentioned sacrificing Victoria, I couldn't help myself...",
  ui_story_5084_50840502_75_dialog_content = "Sacrificing Lady Victoria... Wait, that's tonight? Does that mean the same exact thing is about to happen?!",
  ui_story_5084_50840502_76_dialog_content = "I'm afraid so... Even though Wilhelm seems to be worried about Victoria, I still need to know what he plans to do to her...",
  ui_story_5084_50840502_77_dialog_content = "This study... Is one of <color=#FFB400>Osten Varaki's</color> relics still here somewhere?",
  ui_story_5084_50840502_78_dialog_content = "Or could it be... Him?",
  ui_story_5084_50840502_79_dialog_content = "Tell me! Offering Victoria as a sacrifice... Is this your will?",
  ui_story_5084_50840502_80_dialog_content = "\"Him\"?",
  ui_story_5084_50840502_81_dialog_content = "Who spoke to you just now?! Tell me!",
  ui_story_5084_50840502_82_dialog_content = "My lord...!",
  ui_story_5084_50840502_83_dialog_content = "... Uraaagh! <size=45>Blast this accursed ring!!!</size>",
  ui_story_5084_50840502_84_dialog_content = "Kill me, my lord... Free me from my suffering!!!",
  ui_story_5084_50840502_85_dialog_content = "Just look at your warped state... Pathetic.",
  ui_story_5084_50840502_86_dialog_content = "Ugh... Aaaaahhh!",
  ui_story_5084_50840502_87_dialog_content = "Ahahahaha—! I am the rightful leader of the True Order! Me!!!",
  ui_story_5084_50840502_88_dialog_content = "(The ring is attacking Wilhelm's mind again... What should I do?)",
  ui_story_5084_50840502_89_dialog_content = "Wilhelm, you hopeless fool. As I said before, you must die in order to live.",
  ui_story_5084_50840502_90_dialog_content = "I don't fear death... But Victoria... What about her?!?",
  ui_story_5084_50840502_91_dialog_content = "Lord of Truth...",
  ui_story_5084_50840502_92_dialog_content = "Tell me what will become of Victoria after today...!!!",
  ui_story_5084_50840502_93_dialog_content = "He's completely lost control! He won't survive if this keeps up!",
  ui_story_5084_50840502_94_dialog_content = "It looks like you can make contact with him using your powers, PlayerName. Why not give that a try?",
  ui_story_5084_50840502_95_dialog_content = "But if I do that, it might affect the past! We'll be in huge trouble if that happens...",
  ui_story_5084_50840502_96_dialog_content = "You believe in the Lord of Truth, right May? What would make you feel calm in a situation like this without raising any suspicions?",
  ui_story_5084_50840502_97_dialog_content = "I dunno, something simple like \"May The Truth bless you,\" or \"Follow the guidance,\" I suppose?",
  ui_story_5084_50840502_98_dialog_content = "Really...? Guess it's worth a try...",
  ui_story_5084_50840502_99_option_content = "Mindlink—",
  ui_story_5084_50840502_100_dialog_content = "May The Truth bless you.",
  ui_story_5084_50840502_101_dialog_content = "...",
  ui_story_5084_50840502_102_dialog_content = "May The Truth bless you.",
  ui_story_5084_50840502_103_dialog_content = "M-May The Truth bless you...",
  ui_story_5084_50840502_104_dialog_content = "You... Who exactly are you...?",
  ui_story_5084_50840502_105_dialog_content = "(Looks like it's working, but I'd better be careful not to say the wrong thing...)",
  ui_story_5084_50840502_106_dialog_content = "I'm sorry, but I cannot believe in a god that manipulates people's hearts any longer. The Truth in my heart will not lead me astray.",
  ui_story_5084_50840502_107_dialog_content = "The True Order cannot continue to exist this way, at least not in Victoria's future.",
  ui_story_5084_50840502_108_dialog_content = "If you also believe in the Lord of Truth, you will understand my words.",
  ui_story_5084_50840502_109_dialog_content = "For you to appear before me right now, it must mean that you have something to tell me... Correct?",
  ui_story_5084_50840502_110_dialog_content = "... Follow the guidance.",
  ui_story_5084_50840502_111_dialog_content = "... So you believe that I should accept reality, and allow myself to be consumed by the heads of our families...",
  ui_story_5084_50840502_112_dialog_content = "So that Victoria can continue bearing the curse of our people, and ultimately meet her demise at the hands of that vampire?",
  ui_story_5084_50840502_113_dialog_content = "(No, that's not right... How did I make things worse...?)",
  ui_story_5084_50840502_114_dialog_content = "... No! Absolutely not!",
  ui_story_5084_50840502_115_dialog_content = "I've come so far despite being forsaken by my family, and I owe it all to The Truth within my own heart! That Truth will never lead me astray!",
  ui_story_5084_50840502_116_dialog_content = "It's these so-called \"revelations\" that have caused the True Order to fall so low...",
  ui_story_5084_50840502_117_dialog_content = "I must... Undo this curse.",
  ui_story_5084_50840502_118_dialog_content = "But how...",
  ui_story_5084_50840502_119_dialog_content = "... The only sacred relic which has not been tainted by a leader... Is <color=#FFB400>that one</color>.",
  ui_story_5084_50840502_120_dialog_content = "The blood moon... When its vines assume living form, a guardian will await the master of the crypt at its entrance.",
  ui_story_5084_50840502_121_dialog_content = "But aside from transporting the coffin of our ancestor in and out of the tomb... The only way to enter is with the <color=#FFB400>key</color>, or with the consent of the heads of families...",
  ui_story_5084_50840502_122_dialog_content = "Hah! Wilhelm, you wretch... Still thinking about the rules even when you're about to be eaten? You deserve to be ridiculed...",
  ui_story_5084_50840502_123_dialog_content = "Even if Clavis refuses to give me the key, the Vinekeepers have served the Varaki for generations...",
  ui_story_5084_50840502_124_dialog_content = "Surely he will allow me to enter the crypt now that I've acquired this knowledge?",
  ui_story_5084_50840502_125_dialog_content = "I must enter it before the start of the procession!",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>Fwoosh!</color>",
  ui_story_5084_50840502_127_dialog_content = "Hang on tight, May!",
  ui_story_5084_50840502_128_dialog_content = "Where are we going this time?!",
  ui_story_5084_50840502_129_dialog_content = "The tomb of the Varaki!",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>At the entrance to a tailor's shop in Varaki Town</color>",
  ui_story_5084_50840601_2_dialog_content = "May The Truth bless you, a skilled seamstress.",
  ui_story_5084_50840601_3_dialog_content = "And may The Truth bless you as well, kind sir. With such a pious appearance, you will definitely be chosen as the Initiate this year.",
  ui_story_5084_50840601_4_dialog_content = "I pray it will be so, my dear. I must be going now; till we meet at the banquet tonight. Don't be late.",
  ui_story_5084_50840601_5_dialog_content = "I assure you I won't.",
  ui_story_5084_50840601_6_dialog_content = "What the... How did we end up here?",
  ui_story_5084_50840601_7_dialog_content = "Are you here for the ceremonial robe, sir?",
  ui_story_5084_50840601_8_dialog_content = "Ceremonial robe...?",
  ui_story_5084_50840601_9_dialog_content = "Ah, you must be someone else's customer.",
  ui_story_5084_50840601_10_dialog_content = "Our family of tailors has been in business for generations here in Varaki Town. During every Advent of Truth, our shop receives the most orders for robes.",
  ui_story_5084_50840601_11_dialog_content = "Even the people living on the edges of our town will come to buy our robes on the very night of the celebration.",
  ui_story_5084_50840601_12_dialog_content = "So why not place an order with us? I guarantee the price will be to your liking.",
  ui_story_5084_50840601_13_dialog_content = "...",
  ui_story_5084_50840601_14_dialog_content = "Look, friend! The blood moon has appeared.",
  ui_story_5084_50840601_15_dialog_content = "The blood moon... The Advent of Truth is tonight...",
  ui_story_5084_50840601_16_dialog_content = "My mentor said he would choose me as this year's Initiate, meaning I must dress piously for the occasion.",
  ui_story_5084_50840601_17_dialog_content = "The Initiate?! Did I hear that correctly...?",
  ui_story_5084_50840601_18_dialog_content = "But the only person who can announce the Initiate is Lord Wilhelm Varaki! Why did he choose you, of all people?",
  ui_story_5084_50840601_19_dialog_content = "Yes, that's my mentor's name. We met in his family's crypt.",
  ui_story_5084_50840601_20_dialog_content = "The tomb of the Varaki...?! I see... Tell me, how did you manage to draw so close to The Truth?",
  ui_story_5084_50840601_21_dialog_content = "... I confess my sins and seek penance every single day, but everyone still avoids me. Everyone... Except for my mentor.",
  ui_story_5084_50840601_22_dialog_content = "Penance... The Advent of Truth... And the blood moon... Yes, I think I understand now...",
  ui_story_5084_50840601_23_dialog_content = "Thank you for imparting this knowledge of The Truth to me, honorable Initiate...",
  ui_story_5084_50840601_24_dialog_content = "I've been accepting money from the faithful in the name of the Advent of Truth... And so The Truth has shunned me...",
  ui_story_5084_50840601_25_dialog_content = "Bless you, Initiate... Bless you for showing me the error of my ways.",
  ui_story_5084_50840601_26_dialog_content = "Would you mind gracing us with your presence a while longer? My mother, my daughter, and I would be honored to fashion a set of robes for you with the utmost urgency!",
  ui_story_5084_50840601_27_dialog_content = "Th-That won't be necessary... I was simply passing by in search of my mentor.",
  ui_story_5084_50840601_28_dialog_content = "This was no coincidence, sir; The Truth must have guided you here today! Please forgive me for behaving so rudely just now—",
  ui_story_5084_50840601_29_dialog_content = "Again, it really isn't necessary...",
  ui_story_5084_50840601_30_dialog_content = "Mother? What are you still doing here?! Our customers are tired of waiting!",
  ui_story_5084_50840601_31_dialog_content = "Tell them we will deliver their robes free of charge today!",
  ui_story_5084_50840601_32_dialog_content = "Ha?",
  ui_story_5084_50840601_33_dialog_content = "After that, we will be crafting a set of robes for this young man right away! He's the Initiate!",
  ui_story_5084_50840601_34_dialog_content = "You mean right now?",
  ui_story_5084_50840601_35_dialog_content = "Yes, dear!",
  ui_story_5084_50840601_36_dialog_content = "Grandmother won't be happy about this...",
  ui_story_5084_50840601_37_dialog_content = "Just do as I say, for now, child. I will explain everything to your grandmother.",
  ui_story_5084_50840601_38_dialog_content = "Okay...",
  ui_story_5084_50840601_39_dialog_content = "Ah... Forgive me, Lord of Truth! I appear to have made yet another mistake...",
  ui_story_5084_50840601_40_dialog_content = "Thank goodness... I still have some money on my person... I only pray that it will cover some of their losses for the day...",
  ui_story_5084_50840601_41_dialog_content = "But I mustn't impose on this kind of seamstress or her family any further...",
  ui_story_5084_50840601_42_dialog_content = "Wilhelm.",
  ui_story_5084_50840601_43_dialog_content = "Who dares speak my name and block my path?! Stand aside! The Advent of Truth requires my presence!",
  ui_story_5084_50840601_44_dialog_content = "You have lost sight of The Truth, and your vision is obscured by reality instead.",
  ui_story_5084_50840601_45_dialog_content = "This responsibility is too great for you to bear. Allow me to take your place...",
  ui_story_5084_50840601_46_dialog_content = "Were you sent by the other heads of families? Come at me then!",
  ui_story_5084_50840601_47_dialog_content = "<color=#e8d9bb>The candle flickers and their surroundings change once more—Suddenly, a tomb of clearly ancient origins appears before them.</color>",
  ui_story_5084_50840601_48_dialog_content = "<color=#e8d9bb>A cold wind blows away the dust and debris that have settled on its vines for centuries.</color>",
  ui_story_5084_50840601_49_dialog_content = "<color=#e8d9bb>With a start, the vines begin to wriggle and unwind, releasing the person trapped within...</color>",
  ui_story_5084_50840601_50_dialog_content = "We're here... Wait, is that...?",
  ui_story_5084_50840601_51_dialog_content = "Wh-What am I doing here...?",
  ui_story_5084_50840601_52_dialog_content = "Was it that person I encountered earlier? He must have used some sort of trick to bring me here... And now he's taken my place in the ceremony...",
  ui_story_5084_50840601_53_dialog_content = "The blood moon has been obscured... What time is it now? Have I missed the Advent of Truth?",
  ui_story_5084_50840601_54_dialog_content = "You have been blessed with The Truth's wisdom.",
  ui_story_5084_50840601_55_dialog_content = "<color=#e8d9bb>The vines at the entrance to the crypt converge and assume the form of a sallow-faced man with dull, lifeless eyes.</color>",
  ui_story_5084_50840601_56_dialog_content = "My lord, the tomb of your ancestors is open to you.",
  ui_story_5084_50840601_57_dialog_content = "But... How?",
  ui_story_5084_50840601_58_dialog_content = "The <color=#FFB400>key</color> is nearby... I can sense its flame.",
  ui_story_5084_50840601_59_dialog_content = "What flame? The only fire I see around here... Is on the candlestick in your hands.",
  ui_story_5084_50840601_60_dialog_content = "Could all of this be... Because of me? First I guided him here with my voice, and now I've opened the tomb's door for him?",
  ui_story_5084_50840601_61_dialog_content = "What exactly have I been changing here?",
  ui_story_5084_50840601_62_dialog_content = "Wait, I don't...",
  ui_story_5084_50840601_63_dialog_content = "<color=#e8d9bb>Without waiting for Wilhelm to finish speaking, the Vinekeeper returns to the mossy ground and resumes his silent vigil.</color>",
  ui_story_5084_50840601_64_dialog_content = "The crypt is open, and its guardian has granted me entry...",
  ui_story_5084_50840601_65_dialog_content = "Yet I haven't done a thing. Could this be The Truth's doing?",
  ui_story_5084_50840601_66_dialog_content = "Destiny has guided me here, which means the Lord of Truth wishes for me to carry out his divine will.",
  ui_story_5084_50840601_67_dialog_content = "I must go inside.",
  ui_story_5084_50840601_68_dialog_content = "What's he doing now...? Come on, May!",
  ui_story_5084_50840601_69_dialog_content = "Perhaps the Varaki ancestor can offer more guidance...",
  ui_story_5084_50840601_70_dialog_content = "Wh-Where is the ancestral coffin?! It was supposed to be returned once the procession ended...",
  ui_story_5084_50840601_71_dialog_content = "Who would dare disturb the Varaki's final resting place?! No...",
  ui_story_5084_50840601_72_dialog_content = "The ancestral coffin, and even the Bloody Bible... Both are gone...",
  ui_story_5084_50840601_73_dialog_content = "Have the heads of families already put their plans into motion?",
  ui_story_5084_50840601_74_dialog_content = "Victoria... She's in danger!",
  ui_story_5084_50840601_75_dialog_content = "Sir Frost! Take me back to the temple!",
  ui_story_5084_50840601_76_dialog_content = "What a cool-looking black horse... No wait, we need to go after it!",
  ui_story_5084_50840601_77_dialog_content = "Dead disciples? Why are they wandering about here?!",
  ui_story_5084_50840601_78_dialog_content = "More corpses... What in the world happened in the town?!",
  ui_story_5084_50840601_79_dialog_content = "Filthy creature! How dare you invade this place and harm the faithful!",
  ui_story_5084_50840601_80_dialog_content = "These wretched beings have no minds of their own. Their master must have set them loose in the town.",
  ui_story_5084_50840601_81_dialog_content = "I'll cleanse the world of their existence!",
  ui_story_5084_50840602_1_dialog_content = "Ah, Lord Wilhelm Varaki... What a powerful and captivating figure!",
  ui_story_5084_50840602_2_dialog_content = "Through his wisdom, I was granted a glimpse through the door of Truth.",
  ui_story_5084_50840602_3_dialog_content = "It seems the faithful are completely unaware of the monsters threatening the town...",
  ui_story_5084_50840602_4_dialog_content = "The Advent of Truth ceremony is over, but the heads of families should still be in the temple...",
  ui_story_5084_50840602_5_dialog_content = "Huff, huff... W-We finally... Caught up...",
  ui_story_5084_50840602_6_dialog_content = "Look, May! It's those two disciples that you tried preaching to earlier! We're back to this time again!",
  ui_story_5084_50840602_7_dialog_content = "Which means we should be in the temple right now!",
  ui_story_5084_50840602_8_dialog_content = "Once the disciples left, I thought the ceremony had concluded. I didn't expect to find you waiting for me here.",
  ui_story_5084_50840602_9_dialog_content = "Nails! What are you doing here?!",
  ui_story_5084_50840602_10_dialog_content = "And what the heck are you wearing...?",
  ui_story_5084_50840602_11_dialog_content = "A kind seamstress and her family tailor-made these robes for me. I am eternally grateful for their generosity.",
  ui_story_5084_50840602_12_dialog_content = "I am also grateful to my mentor for letting me be here today.",
  ui_story_5084_50840602_13_dialog_content = "You...",
  ui_story_5084_50840602_14_dialog_content = "Huh? What are you talking about, Nails?",
  ui_story_5084_50840602_15_dialog_content = "To be honest, I don't really understand what he says half the time, either...",
  ui_story_5084_50840602_16_dialog_content = "It was my immense honor to serve as the sacrifice for this Advent of Truth.",
  ui_story_5084_50840602_17_dialog_content = "Forgive me, but I have no idea what you're talking about.",
  ui_story_5084_50840602_18_dialog_content = "Porfirio! Where is the Bloody Bible?!",
  ui_story_5084_50840602_19_dialog_content = "I have questions as well, Wilhelm. What was that black wind just now? And where has Victoria gone?!",
  ui_story_5084_50840602_20_dialog_content = "Victoria?",
  ui_story_5084_50840602_21_dialog_content = "Even after offering your own niece, the Lord of Truth did not grace you with any revelations. Has your own failure finally driven you mad?",
  ui_story_5084_50840602_22_dialog_content = "It matters not. I've long since grown tired of your games, Wilhelm.",
  ui_story_5084_50840602_23_dialog_content = "The Bloody Bible is mine now! The Truth is within my reach!",
  ui_story_5084_50840602_24_dialog_content = "However... Now that this year's ritual has concluded, I believe we have something to discuss.",
  ui_story_5084_50840602_25_dialog_content = "It's just as I saw in the prophecy... Heheh—There is nothing left to discuss. I know you mean to attack me, Porfirio!",
  ui_story_5084_50840602_26_dialog_content = "There's no use feigning ignorance; I've already purged the town of your servants, which you unleashed on the innocent faithful!",
  ui_story_5084_50840602_27_dialog_content = "So it's come to this...",
  ui_story_5084_50840602_28_dialog_content = "It appears Wilhelm Varaki has no intention of yielding to us... The Truth still has much to tell me, so I must bid you both farewell.",
  ui_story_5084_50840602_29_dialog_content = "Not another step, Porfirio!",
  ui_story_5084_50840602_30_dialog_content = "It's useless to resist, Wilhelm. With the Bloody Bible in my hands, destiny is now on my side...",
  ui_story_5084_50840602_31_dialog_content = "It's time to work, old friend.",
  ui_story_5084_50840602_32_dialog_content = "What do you intend to do to my mentor? I am the Initiate, not him.",
  ui_story_5084_50840602_33_dialog_content = "And just where did you come from, outsider?",
  ui_story_5084_50840602_34_dialog_content = "Not even Wilhelm's followers will be spared.",
  ui_story_5084_50840602_35_dialog_content = "As leader of the True Order, I won't allow you to harm any more of the faithful!",
  ui_story_5084_50840602_36_dialog_content = "You should worry about yourself first, fool! Hahahaha!",
  ui_story_5084_50840602_37_dialog_content = "Wilhelm...!",
  ui_story_5084_50840602_38_dialog_content = "My lord, grant me your pain and allow me to suffer in your place. Swallow it, shed it, and allow The Truth to prevail over evil...",
  ui_story_5084_50840602_39_dialog_content = "No, Mr. Nails! You have to run—",
  ui_story_5084_50840602_40_dialog_content = "Stop, May! We're not allowed to interfere... Remember what Sikare told us!",
  ui_story_5084_50840602_41_dialog_content = "This is all my fault. None of this would've happened if I had just kept quiet... We need to think of another way to help them. We still have the candlestick, so there must be something we can do.",
  ui_story_5084_50840602_42_dialog_content = "Hmph, how surprising. Your bones are as strong as your faith, it seems.",
  ui_story_5084_50840602_43_dialog_content = "Die!",
  ui_story_5084_50840602_44_dialog_content = "Lord of Truth, your rituals are so unbearably cruel. Can your believers truly withstand this? If so, how can they survive such immense pain?",
  ui_story_5084_50840602_45_dialog_content = "I will endure it! I will swallow this suffering and cleanse my body of its sins. I will accept this curse of pain and burn away the wounds of my soul—",
  ui_story_5084_50840602_46_dialog_content = "Allow me to bear this pain in solitude, so that no other person must experience it! Come and erase my sins through agony!",
  ui_story_5084_50840602_47_dialog_content = "A life of suffering in exchange for their redemption!",
  ui_story_5084_50840602_48_dialog_content = "(At this rate, Nails is really going to die at their hands! Come on, candlestick... Take me where I can make a difference...!)",
  ui_story_5084_50840602_49_dialog_content = "You fool!",
  ui_story_5084_50840602_50_dialog_content = "This is no ritual, and they're not helping you cleanse your soul! Can't you see that they're trying to kill you?!",
  ui_story_5084_50840602_51_dialog_content = "Do you consider yourself an ascetic? If so, you must survive and devote the rest of your life to searching for The Truth!",
  ui_story_5084_50840602_52_dialog_content = "My lord?",
  ui_story_5084_50840602_53_dialog_content = "Live, you fool!",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>Wilhelm grabs Nails and hurls him away with surprising strength. He slams into the temple doors, throwing them wide open and allowing the black wind to enter.</color>",
  ui_story_5084_50840602_55_dialog_content = "Ah! The candle went out!",
  ui_story_5084_50840602_56_dialog_content = "Wilhelm Varaki will not be forced to kneel so easily! Now what else do you have in store for me?!",
  ui_story_5084_50840602_57_dialog_content = "You treacherous fiends will taste of my blade before the night is through!",
  ui_story_5084_50840602_58_dialog_content = "Awaken, <color=#FF0000>Crimson Tide</color>! My demonic blade, which drinks of my blood in exchange for cutting down my enemies!",
  ui_story_5084_50840602_59_dialog_content = "What's going on? Are they about to fight...?",
  ui_story_5084_50840602_60_dialog_content = "I don't know! I can't see anything!",
  ui_story_5084_50840602_61_dialog_content = "The world is starting to shift around us again, but I have to watch this to the end! I can't let myself... Get teleported away—",
  ui_story_5084_50840602_62_dialog_content = "Hold onto me and go as far back as you can, May!",
  ui_story_5084_50840602_63_dialog_content = "Damn, I can't see a thing in here.",
  ui_story_5084_50840602_64_dialog_content = "Even so, he won't last much longer on his own.",
  ui_story_5084_50840602_65_dialog_content = "Ah!",
  ui_story_5084_50840602_66_dialog_content = "Which of you is my next victim?",
  ui_story_5084_50840602_67_dialog_content = "Come and stand at my side, Clavis! We can defeat them together!",
  ui_story_5084_50840602_68_dialog_content = "...",
  ui_story_5084_50840602_69_dialog_content = "It's pointless, Wilhelm. Even if you sever my head, I won't die.",
  ui_story_5084_50840602_70_dialog_content = "Then I'll keep cutting you until you can't bear the pain any longer!",
  ui_story_5084_50840602_71_dialog_content = "Incredible... Even though he's fighting so many people in the dark... He's not at a disadvantage at all.",
  ui_story_5084_50840602_72_dialog_content = "Pitiful... Are you even trying to kill him?",
  ui_story_5084_50840602_73_dialog_content = "It's easier said than done...",
  ui_story_5084_50840602_74_dialog_content = "Still counting on others, Porfirio? Your end is near, and no one will save you from it!",
  ui_story_5084_50840602_75_dialog_content = "You remember our deal... Don't you?",
  ui_story_5084_50840602_76_dialog_content = "...",
  ui_story_5084_50840602_77_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840602_78_dialog_content = "What happened? I can't sense his breathing anymore! Is he...",
  ui_story_5084_50840602_79_dialog_content = "Just keep hanging on! We're... We're about to get teleported somewhere else!",
  ui_story_5084_50840602_80_dialog_content = "Why... Why does it have to be like this?",
  ui_story_5084_50840602_81_dialog_content = "(If he actually dies... What's going to happen to Victoria?)",
  ui_story_5084_50840602_82_dialog_content = "Hey, PlayerName? Lord Wilhelm doesn't seem like a cold-blooded murderer at all, does he? Do you really think he sacrificed Lady... Victoria...?",
  ui_story_5084_50840602_83_dialog_content = "I have my doubts about it now too... Ever since the candlestick first teleported us away, the Wilhelm we've been seeing is nothing like the Wilhelm we saw at the Advent of Truth's ceremony...",
  ui_story_5084_50840602_84_dialog_content = "Did my words really cause all of these changes to happen...?",
  ui_story_5084_50840602_85_dialog_content = "Or is there something else happening between the Wilhelms that we've seen...?",
  ui_story_5084_50840602_86_dialog_content = "I wonder where Lady Victoria is right now...",
  ui_story_5084_50840602_87_dialog_content = "During the ceremony, Victoria mentioned something about Wilhelm going missing. Maybe she's trying to find the answers behind his disappearance?",
  ui_story_5084_50840602_88_dialog_content = "Something tells me that this sacrifical ceremony isn't as simple as it seems... If she's willing to revisit all of this, it must mean that she's looking for something.",
  ui_story_5084_50840602_89_dialog_content = "It seems like she and Wilhelm misunderstood each other for the longest time... They still had more to tell each other.",
  ui_story_5084_50840700_1_dialog_content = "Wow, look at all these candles and flowers, PlayerName! Wait... Is that a coffin?!",
  ui_story_5084_50840700_2_dialog_content = "I think so...",
  ui_story_5084_50840700_3_dialog_content = "Wonder where we are now?",
  ui_story_5084_50840700_4_dialog_content = "It's so dark and gloomy outside, too. Let me take a look...",
  ui_story_5084_50840700_5_dialog_content = "We're in an ancient castle overlooking a cliff! Who would build their house in a place like this...?",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>Pit-pat, pit-pat—</color>",
  ui_story_5084_50840700_7_dialog_content = "Ah—It's Lady Victoria!",
  ui_story_5084_50840700_8_dialog_content = "But how...? Is it because I was thinking of her just now?",
  ui_story_5084_50840700_9_dialog_content = "Wait, there's someone else.",
  ui_story_5084_50840700_10_dialog_content = "So you've come in search of Wilhelm as well?",
  ui_story_5084_50840700_11_dialog_content = "Aside from family, it seems the only people who come to his home are his enemies.",
  ui_story_5084_50840700_12_dialog_content = "Do you know where he is?",
  ui_story_5084_50840700_13_dialog_content = "Unfortunately, I do not. He left no clues regarding his whereabouts before he disappeared.",
  ui_story_5084_50840700_14_dialog_content = "What a shame. I thought he would at least have one or two trusted confidants.",
  ui_story_5084_50840700_15_dialog_content = "We were once that close, yes.",
  ui_story_5084_50840700_16_dialog_content = "If only Wilhelm hadn't been so reckless... It could have stayed that way.",
  ui_story_5084_50840700_17_dialog_content = "You never understood your uncle very well... Did you, Victoria?",
  ui_story_5084_50840700_18_dialog_content = "I have no interest in knowing people like him, much less understanding them.",
  ui_story_5084_50840700_19_dialog_content = "Before your father became leader of the True Order, your uncle Wilhelm coveted the role more than anything else.",
  ui_story_5084_50840700_20_dialog_content = "Blinded by the prospect of fortune and glory, he fervently pursued the most radical beliefs and espoused them as The Truth.",
  ui_story_5084_50840700_21_dialog_content = "Because of this, he repeatedly lost control whenever he tried to inherit the power of our ancestors... Though he was already seen as a pariah, he refused to accept defeat.",
  ui_story_5084_50840700_22_dialog_content = "That refusal, in turn, made him the puppet of another's ambitions, which ultimately resulted in his expulsion from the family.",
  ui_story_5084_50840700_23_dialog_content = "... I don't care to learn his story.",
  ui_story_5084_50840700_24_dialog_content = "I'm actually quite content to be free from his control.",
  ui_story_5084_50840700_25_dialog_content = "During my travels, the Lord of Truth revealed something to me... Which is why I've come to say farewell.",
  ui_story_5084_50840700_26_dialog_content = "I'm leaving for the place I was shown, where I will await the Lord of Truth's glorious arrival.",
  ui_story_5084_50840700_27_dialog_content = "You are the successor to the Varaki bloodline. You are free to make any decision as you see fit.",
  ui_story_5084_50840700_28_dialog_content = "But before I leave, may I ask you about something? That day, when we visited your home... What was it that Wilhelm wanted to borrow from you?",
  ui_story_5084_50840700_29_dialog_content = "That <color=#FFB400>key</color> will only bring you harm.",
  ui_story_5084_50840700_30_dialog_content = "Just before he died, my brother took it back from the <color=#FFB400>Vinekeepers</color> and gave it to you... Clearly, it was to ensure that the key would make it into my hands someday.",
  ui_story_5084_50840700_31_dialog_content = "... Or perhaps it was to prevent you from forcibly taking it from the <color=#FFB400>Vinekeepers</color> yourself.",
  ui_story_5084_50840700_32_dialog_content = "...! It is a key to all doors... But those who burn with ambition will only be consumed by it.",
  ui_story_5084_50840700_33_dialog_content = "... Take care, Victoria Varaki. You bear a great and heavy burden, and the path to The Truth is long and arduous.",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>Victoria watches as Clavis takes his leave. Once he is out of sight, she turns and enters Wilhelm's room.</color>",
  ui_story_5084_50840700_35_dialog_content = "Where have you gone, you incomprehensible man?",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>She peers around the room before finally opening Wilhelm's opulent coffin and lying down inside it.</color>",
  ui_story_5084_50840700_37_dialog_content = "If I see things like my parents once did... Will I be able to understand your ambitions?",
  ui_story_5084_50840700_38_dialog_content = "(This feeling... She's trying to remember something...)",
  ui_story_5084_50840700_39_dialog_content = "We are gathered here today to honor the heads of the Varaki Family as we lay their bodies to rest.",
  ui_story_5084_50840700_40_dialog_content = "As they follow in the footsteps of our noble ancestors, they are survived by their beloved daughter—Victoria Varaki.",
  ui_story_5084_50840700_41_dialog_content = "Come, child; place this ring upon your father's grave with your own hands. It was a symbol of his honor, and should be treated as such in this moment.",
  ui_story_5084_50840700_42_dialog_content = "Father... Mother...",
  ui_story_5084_50840700_43_dialog_content = "Take your time, my dear. We understand that you are still overwhelmed by grief and confusion.",
  ui_story_5084_50840700_44_dialog_content = "But fear not, my lady, for we shall stay by your side as you navigate this darkest of hours—Ah, but where are my manners? My name is David Porfirio.",
  ui_story_5084_50840700_45_dialog_content = "Your father once helped me tame the chaos within my blood, and restored my precious sanity.",
  ui_story_5084_50840700_46_dialog_content = "And I am Clavis Abraham. I have never forgotten the kindness shown to me by the Varaki Family.",
  ui_story_5084_50840700_47_dialog_content = "Should you ever require assistance with anything at all, you only need to ask for it.",
  ui_story_5084_50840700_48_dialog_content = "Lady Varaki... You need not know my name. I am but a humble servant, so please address me as such.",
  ui_story_5084_50840700_49_dialog_content = "My father... What did he call you?",
  ui_story_5084_50840700_50_dialog_content = "Graves, my lady...",
  ui_story_5084_50840700_51_dialog_content = "The passage of time can be cruel, so much so that I have all but forgotten my name... Everyone refers to me as <color=#FFB400>Viper</color>, so please feel free to do so as well.",
  ui_story_5084_50840700_52_dialog_content = "The ritual is over, and the leaders of the Varaki Family have now been laid to rest. Now the time has come for us to discuss the future.",
  ui_story_5084_50840700_53_dialog_content = "You are still quite young, Lady Victoria. I fear that you are not yet ready to bear the power of this ring.",
  ui_story_5084_50840700_54_dialog_content = "I shall gladly watch over it in your stead—Fear not, for it is nothing more than a normal ring in the hands of someone who does not belong to the Varaki.",
  ui_story_5084_50840700_55_dialog_content = "Is that so? Then why do you insist on keeping it for yourself, Porfirio?",
  ui_story_5084_50840700_56_dialog_content = "Wilhelm Varaki?!",
  ui_story_5084_50840700_57_dialog_content = "Hmph, don't forget that another member of the Varaki still lives, and that only a Varaki can assume leadership of the True Order.",
  ui_story_5084_50840700_58_dialog_content = "...",
  ui_story_5084_50840700_59_dialog_content = "How dare you speak such madness before Lady Victoria! Have you forgotten that you were banished from the Varaki Family?!",
  ui_story_5084_50840700_60_dialog_content = "Hah! Witness me as I inherit the wisdom and power of our ancestors!",
  ui_story_5084_50840700_61_dialog_content = "Urgh...",
  ui_story_5084_50840700_62_dialog_content = "Hahahaha! Why the look of disappointment, Porfirio? Does the prospect of seeing another Varaki don that ring torment you so?",
  ui_story_5084_50840700_63_dialog_content = "Behold! I, Wilhelm Varaki, now tower over all of you!",
  ui_story_5084_50840700_64_dialog_content = "Our ancestor has deemed me worthy of becoming the new head of the Varaki Family!",
  ui_story_5084_50840700_65_dialog_content = "Wilhelm... It seems your ambitions have not been extinguished.",
  ui_story_5084_50840700_66_dialog_content = "Heh... Hahahaha! Dear Victoria, it seems your uncle is unwilling to grant you that which is rightfully yours.",
  ui_story_5084_50840700_67_dialog_content = "We have no right to interfere in Varaki's affairs. Let us take our leave.",
  ui_story_5084_50840700_68_dialog_content = "Wilhelm Varaki... My uncle...",
  ui_story_5084_50840700_69_dialog_content = "Where do you wish to go?",
  ui_story_5084_50840700_70_dialog_content = "Naturally, I wish to leave this town and go to the place which I have rightfully inherited.",
  ui_story_5084_50840700_71_dialog_content = "Victoria Varaki... From this day forth, I will serve as your guardian. So long as I am the head of the family, you must do exactly as I say.",
  ui_story_5084_50840700_72_dialog_content = "... That ring belonged to my father, which means it should now belong to me. When The Truth speaks to me and awakens my power, I will take it back.",
  ui_story_5084_50840700_73_dialog_content = "As you wish. But for now, it stays in my hands.",
  ui_story_5084_50840700_74_dialog_content = "The honor of hearing The Truth... I dearly wish to hear the thoughts of one as precocious as you, Victoria Varaki. What, in your definition, is The Truth?",
  ui_story_5084_50840700_75_dialog_content = "The Truth... is knowledge.",
  ui_story_5084_50840700_76_dialog_content = "Humph, Victoria Varaki... Though we share the same bloodline, in terms of strength, wisdom, capability, and even beauty... I stand far above you.",
  ui_story_5084_50840700_77_dialog_content = "So what makes you think this ring is rightfully yours?",
  ui_story_5084_50840700_78_dialog_content = "I am a true Varaki, and the leader of the True Order!",
  ui_story_5084_50840700_79_dialog_content = "As for you... You must first demonstrate that you are worthy of our family name. Do not disappoint me.",
  ui_story_5084_50840700_80_dialog_content = "(Wilhelm is saying such awful things, and to a child who just lost her parents, no less... He's not being serious, is he?)",
  ui_story_5084_50840700_81_dialog_content = "(Then again, that child is still Victoria... It's so strange! The Wilhelm we've been seeing isn't nearly this...)",
  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>A bolt of lightning peals through the sky outside as young Victoria opens her parents' coffin and crawls inside.</color>",
  ui_story_5084_50840700_83_dialog_content = "Father... Mother...",
  ui_story_5084_50840700_84_dialog_content = "Give me your guidance... Tell me what to do...",
  ui_story_5084_50840700_85_dialog_content = "Am I... Home? But how?",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>Rustle, rustle—</color>",
  ui_story_5084_50840700_87_dialog_content = "Who dares intrude upon the house of the Varaki—",
  ui_story_5084_50840700_88_dialog_content = "... What are you doing here? And where are my servants?",
  ui_story_5084_50840700_89_dialog_content = "Gone. From this moment on, time will be our everlasting servant.",
  ui_story_5084_50840700_90_dialog_content = "<color=#e8d9bb>Wilhelm Varaki, the man who had suddenly broken into Victoria's, was there to stay and watch over her as her uncle.</color>",
  ui_story_5084_50840700_91_dialog_content = "My dear Victoria, your plight weighs heavily on our hearts, and truly, it does... But we are powerless to change it. Please forgive us, child.",
  ui_story_5084_50840700_92_dialog_content = "For as long as Wilhelm is the head of the Varaki, we must obey him. In truth, he is the one who keeps us at arm's length...",
  ui_story_5084_50840700_93_dialog_content = "Hoping that nothing was amiss, I rushed over here as quickly as I could... I am relieved to see that you are indeed well.",
  ui_story_5084_50840700_94_dialog_content = "He's only being cautious of me. He fears that I will conspire with you and the others to dethrone him.",
  ui_story_5084_50840700_95_dialog_content = "Yes, this is what Wilhelm fears... For he knows that your father was a far more capable leader. He is nothing more than an outcast and an opportunist.",
  ui_story_5084_50840700_96_dialog_content = "Lady Victoria, I must ask... Your talents should be just as awe-inspiring as those of your father. Tell me, were you able to resonate with the ancestor's sacred vessel?",
  ui_story_5084_50840700_97_dialog_content = "If so, how did it feel?",
  ui_story_5084_50840700_98_dialog_content = "It felt like... Someone had entered my mind to tell me about the nectar it once held.",
  ui_story_5084_50840700_99_dialog_content = "Some of its stories were told quietly, as if to say...",
  ui_story_5084_50840700_100_dialog_content = "Porfirio! Who granted you entry into my domain?!",
  ui_story_5084_50840700_101_dialog_content = "Heheh, I only came to see how Lady Victoria is faring, Wilhelm. I will take my leave now.",
  ui_story_5084_50840700_102_dialog_content = "She's faring perfectly well. If you were expecting fresh blood, I suggest you perish the thought immediately.",
  ui_story_5084_50840700_103_dialog_content = "Do not influence her actions with your wild ambitions!",
  ui_story_5084_50840700_104_dialog_content = "I am free to speak to whoever I please, Wilhelm.",
  ui_story_5084_50840700_105_dialog_content = "You are still far too naive, Victoria. You will not learn about the world by immersing yourself in ancient texts; you will only distance yourself from it.",
  ui_story_5084_50840700_106_dialog_content = "You know about the Bloody Bible that lies within the tomb of our ancestors, yes? The wisdom it provides can never be found in the pages of any other book.",
  ui_story_5084_50840700_107_dialog_content = "Ever since your parents were laid to rest, not once have you visited the crypt.",
  ui_story_5084_50840700_108_dialog_content = "But it matters not. I don't fault you for detesting the True Order, but your emotions are not reason enough for doing so.",
  ui_story_5084_50840700_109_dialog_content = "Otherwise, it makes you no better than a petulant child.",
  ui_story_5084_50840700_110_dialog_content = "I had to become stronger, so that no one could ever control me again.",
  ui_story_5084_50840700_111_dialog_content = "To that end, I sought The Truth by attempting to resonate with several relics through ancient rituals...",
  ui_story_5084_50840700_112_dialog_content = "Where is it? Where could that ancient text be...?",
  ui_story_5084_50840700_113_dialog_content = "The Lord of Truth appeared to me in my dream, beckoning me to find his sacred text before Wilhelm Varaki realized that I was missing...",
  ui_story_5084_50840700_114_dialog_content = "Ah!",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>The stars</color>... It's devouring the <color=#FFB400>stars</color>... There's no time! No time at all... A <color=#FFB400>new beginning</color> is at hand...",
  ui_story_5084_50840700_116_dialog_content = "<size=45>The true ending lies within that darkness—!</size>",
  ui_story_5084_50840700_117_dialog_content = "Let go of that immediately, you fool! How dare you attempt to resonate with that ancient relic!",
  ui_story_5084_50840700_118_dialog_content = "The wisdom of the olden days, the revelations of a madman—I, Wilhelm Varaki, command you to stay away from her!",
  ui_story_5084_50840700_119_dialog_content = "... Ah!",
  ui_story_5084_50840700_120_dialog_content = "... Return to your eternal slumber.",
  ui_story_5084_50840700_121_dialog_content = "Y-You saved me? But how did you know I was...",
  ui_story_5084_50840700_122_dialog_content = "Learn to distinguish between the characteristics of different relics, or else your corpse will be the only thing I retrieve next time.",
  ui_story_5084_50840700_123_dialog_content = "And do not misunderstand my intentions. As leader of the True Order, the last thing I need is for the faithful to accuse me of harming my late brother's daughter.",
  ui_story_5084_50840700_124_dialog_content = "Keeping you alive only helps to ensure the stability of my position.",
  ui_story_5084_50840700_125_dialog_content = "What's more, rather than save someone on the brink of death, the family of vampire prefers to drain every last drop of blood from their body.",
  ui_story_5084_50840700_126_dialog_content = "Wilhelm Varaki...!",
  ui_story_5084_50840700_127_dialog_content = "That boastful, arrogant, despicable man... He took my life and freedom away, and his reasons for doing so are always so strange.",
  ui_story_5084_50840700_128_dialog_content = "But compared to my detestable uncle, the others were hardly any better.",
  ui_story_5084_50840700_129_dialog_content = "The heads of families were black-hearted fools, every last one of them. The people they led were like maggots or reanimated corpses, shambling about town with neither purpose nor awareness.",
  ui_story_5084_50840700_130_dialog_content = "Their sermons reeked of wickedness and folly, and offered no guidance for The Truth's faithful. Such people are unfit to shepherd the lost.",
  ui_story_5084_50840700_131_dialog_content = "I had to be wary of them... I could not let myself fall prey to the foul tendencies of the True Order.",
  ui_story_5084_50840700_132_dialog_content = "To heed the will of the Lord of Truth, and to resolve the \"ending\" which was shown to me.",
  ui_story_5084_50840700_133_dialog_content = "You've been locking yourself away in the house recently. Have you finally lost interest in the relics?",
  ui_story_5084_50840700_134_dialog_content = "By the time we were your age, your father and I had long since awakened the power of our bloodline, and our hearts were insatiable for The Truth's wisdom.",
  ui_story_5084_50840700_135_dialog_content = "Could it be that you are still as ignorant as before? Are you still incapable of answering my question about The Truth?",
  ui_story_5084_50840700_136_dialog_content = "... I have decided to travel the world in search of The Truth.",
  ui_story_5084_50840700_137_dialog_content = "Do as you please.",
  ui_story_5084_50840700_138_dialog_content = "And so I began my journey, and sought The Truth's guidance for myself.",
  ui_story_5084_50840700_139_dialog_content = "The moment I set foot outside of my home, I began to gain a deeper knowledge of the world.",
  ui_story_5084_50840700_140_dialog_content = "And as I strengthened my understanding of The Truth, the power of my bloodline began to gradually awaken... Even so, I refused to join the True Order.",
  ui_story_5084_50840700_141_dialog_content = "When I finally found the answer he had asked for, I returned to Varaki Town to tell him... Only to discover that he no longer expected it from me.",
  ui_story_5084_50840700_142_dialog_content = "Welcome back... You were gone for three months this time. How did you fare?",
  ui_story_5084_50840700_143_dialog_content = "... That's none of your concern.",
  ui_story_5084_50840700_144_dialog_content = "The look in your eyes... So full of resentment and uncertainty...",
  ui_story_5084_50840700_145_dialog_content = "What did you see in the outside world, Wilhelm Varaki?",
  ui_story_5084_50840700_146_dialog_content = "I don't recall letting you enter my room.",
  ui_story_5084_50840700_147_dialog_content = "You're the leader of the True Order, and yet you regularly leave without fulfilling your duties... You've been spending less time at home, as well.",
  ui_story_5084_50840700_148_dialog_content = "How many times must I tell you that it's none of your concern?! Now leave me!",
  ui_story_5084_50840700_149_dialog_content = "Very well then; I am no stranger to being denied your conversation. But given that tonight is the Advent of Truth, I was hoping we could have one final discussion.",
  ui_story_5084_50840700_150_dialog_content = "About The Truth, and ourselves...",
  ui_story_5084_50840700_151_dialog_content = "I said get out! Do not make me repeat myself!",
  ui_story_5084_50840700_152_dialog_content = "...",
  ui_story_5084_50840700_153_dialog_content = "In the end, I still don't understand him.",
  ui_story_5084_50840700_154_dialog_content = "I fear that I missed my last chance to do so, as well.",
  ui_story_5084_50840700_155_dialog_content = "Wilhelm Varaki: my arrogant, despicable, and inscrutable uncle, as well as my last living relative... Where have you gone?",
  ui_story_5084_50840700_156_dialog_content = "(So that's how Victoria sees Wilhelm in her memories...)",
  ui_story_5084_50840700_157_dialog_content = "(But from Wilhelm's perspective, he's always been looking after her...)",
  ui_story_5084_50840700_158_dialog_content = "(He suffered losing control on his own, and refused to drink the blood of the faithful like the rest of the heads of families. He was thinking of others to the very end, and even managed to save Nails...)",
  ui_story_5084_50840700_159_dialog_content = "(For so many years... They never managed to understand each other... Even when Wilhelm fell under attack...)",
  ui_story_5084_50840700_160_dialog_content = "(I wonder if Victoria is able to see what I've seen...)",
  ui_story_5084_50840801_1_dialog_content = "The candle's starting to flicker again—Where's it gonna take us this time?",
  ui_story_5084_50840801_2_dialog_content = "It's Victoria... And the rest of the heads of families. What are they all doing here?",
  ui_story_5084_50840801_3_dialog_content = "Huh? Is that Faust standing next to her? And I think he's looking at us!",
  ui_story_5084_50840801_4_dialog_content = "Could this be...?",
  ui_story_5084_50840801_5_option_content = "Mindlink",
  ui_story_5084_50840801_6_dialog_content = "Faust! Can you hear my voice?",
  ui_story_5084_50840801_7_dialog_content = "Of course, and I am fully aware of your present doubts.",
  ui_story_5084_50840801_8_dialog_content = "The person you see here is Lady Victoria, the one you are so well-acquainted.",
  ui_story_5084_50840801_9_dialog_content = "But if it's the Victoria from our time... Why is she standing in front of these people...?",
  ui_story_5084_50840801_10_dialog_content = "Wilhelm has been missing for three years now. The only remaining descendants of the Varaki are Ibrahim's child and Victoria, Wilhelm's niece.",
  ui_story_5084_50840801_11_dialog_content = "(Three years... Wilhelm got attacked in 1915, which means we should be in the year 1918 now, right?)",
  ui_story_5084_50840801_12_dialog_content = "However, Clavis Abraham is unwilling to allow his child to enter the True Order, meaning he has no right to its leadership.",
  ui_story_5084_50840801_13_dialog_content = "As it stands, the position is still vacant and the family ring is nowhere to be found. We suspect that it disappeared along with Wilhelm Varaki.",
  ui_story_5084_50840801_14_dialog_content = "And since Victoria no longer has the privilege of inheriting the wisdom of our ancestors...",
  ui_story_5084_50840801_15_dialog_content = "Oh? Did all of you gather here today simply to tell me this?",
  ui_story_5084_50840801_16_dialog_content = "I am told that you prefer seeking The Truth by traveling across the outside world. We respect your choice.",
  ui_story_5084_50840801_17_dialog_content = "You are free to leave this place, or stay and become a part of the Porfirio Family. In any case, you are no longer qualified to lead the True Order.",
  ui_story_5084_50840801_18_dialog_content = "With the Advent of Truth taking place tonight, the leadership of the True Order must fall to...",
  ui_story_5084_50840801_19_dialog_content = "Have the Order's meetings truly become so lonely and depraved in Wilhelm's absence?",
  ui_story_5084_50840801_20_dialog_content = "Even the family of vampire must pay a steep price for drinking blood that is not meant to be consumed.",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>Victoria pours a glass of blood-red wine on the table before her. At the bottom of the glass lies the ring that Wilhelm once wore.</color>",
  ui_story_5084_50840801_22_dialog_content = "...?",
  ui_story_5084_50840801_23_dialog_content = "... Wilhelm's ring.",
  ui_story_5084_50840801_24_dialog_content = "He entrusted it to me shortly before leaving this place. The words of our ancestors have long since guided my steps.",
  ui_story_5084_50840801_25_dialog_content = "Now tell me, what else do you have to say about the leadership of the True Order?",
  ui_story_5084_50840801_26_dialog_content = "Impossible!",
  ui_story_5084_50840801_27_dialog_content = "The plan must be changed...",
  ui_story_5084_50840801_28_dialog_content = "It seems that every single one of you is privy to some sort of scheme.",
  ui_story_5084_50840801_29_dialog_content = "This is the knowledge that was revealed to me during the Advent of Truth three years ago.",
  ui_story_5084_50840801_30_dialog_content = "Three years ago...",
  ui_story_5084_50840801_31_dialog_content = "No, this can't be!",
  ui_story_5084_50840801_32_dialog_content = "Still counting on others, Porfirio? Your end is near, and no one will save you from it!",
  ui_story_5084_50840801_33_dialog_content = "You remember our deal... Don't you?",
  ui_story_5084_50840801_34_dialog_content = "...",
  ui_story_5084_50840801_35_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840801_36_dialog_content = "Doomed to a disgraceful death in your very own hometown... How I pity you, Wilhelm Varaki.",
  ui_story_5084_50840801_37_dialog_content = "...",
  ui_story_5084_50840801_38_dialog_content = "And with no descendants to speak of, the Varaki's ring has lost all meaning.",
  ui_story_5084_50840801_39_dialog_content = "What have you done? By crushing the ring, you've...",
  ui_story_5084_50840801_40_dialog_content = "It's useless to you or me now. Let the debris rest with Wilhelm in peace.",
  ui_story_5084_50840801_41_dialog_content = "From this day forth, it cannot be used to threaten us ever again.",
  ui_story_5084_50840801_42_dialog_content = "The shackle that is the head of Varaki is in the past!",
  ui_story_5084_50840801_43_dialog_content = "That ring... It should have been burned to ashes, along with Wilhelm...",
  ui_story_5084_50840801_44_dialog_content = "It seems you've uncovered the truth.",
  ui_story_5084_50840801_45_dialog_content = "Oh? Was it supposed to remain a secret?",
  ui_story_5084_50840801_46_dialog_content = "... But have you actually worn it? Has it truly imparted its wisdom unto you?",
  ui_story_5084_50840801_47_dialog_content = "Unless deemed worthy by our ancestors, you will never succeed Wilhelm!",
  ui_story_5084_50840801_48_dialog_content = "I was given the name Varaki by our ancestors, and this long-lost ring is a symbol of their approval. I will now put it on for all to see.",
  ui_story_5084_50840801_49_dialog_content = "PlayerName! That ring's gonna make Lady Victoria lose control!",
  ui_story_5084_50840801_50_dialog_content = "Don't worry May, I'm slowly starting to realize why I'm here now. I know exactly what to do!",
  ui_story_5084_50840801_51_option_content = "Mindlink—",
  ui_story_5084_50840801_52_dialog_content = "Urgh... Not again...",
  ui_story_5084_50840801_53_dialog_content = "The voices... The ancient revelations...",
  ui_story_5084_50840801_54_dialog_content = "Don't worry Victoria, I'll help you suppress them!",
  ui_story_5084_50840801_55_dialog_content = "? I see... This must be the Lord of Truth's will. In that case, I leave it to you.",
  ui_story_5084_50840801_56_dialog_content = "She's wearing it... She's actually wearing it...",
  ui_story_5084_50840801_57_dialog_content = "Why were you all so concerned? A true Varaki should have no problem enduring the voices of our ancestors, after all.",
  ui_story_5084_50840801_58_dialog_content = "Heheh... Hahahaha—",
  ui_story_5084_50840801_59_dialog_content = "That laugh...",
  ui_story_5084_50840801_60_dialog_content = "Behold! I, Wilhelm Varaki, now tower over all of you!",
  ui_story_5084_50840801_61_dialog_content = "Our ancestor has deemed me worthy of becoming the new head of the Varaki Family!",
  ui_story_5084_50840801_62_dialog_content = "Varaki...!",
  ui_story_5084_50840801_63_dialog_content = "Behold, the successor of the Varaki Family!",
  ui_story_5084_50840802_1_dialog_content = "I'll cleanse the world of your existence!",
  ui_story_5084_50840802_2_dialog_content = "What am I seeing...?",
  ui_story_5084_50840802_3_dialog_content = "I did my best to keep the voices at bay, but these visions still managed to escape from the ring.",
  ui_story_5084_50840802_4_dialog_content = "They don't seem to be connected to the voices, though. If anything, I think they're coming from an even higher level of consciousness.",
  ui_story_5084_50840802_5_dialog_content = "They don't appear to be dangerous. Allow me to see them.",
  ui_story_5084_50840802_6_dialog_content = "<size=45>Ah—!!!</size>",
  ui_story_5084_50840802_7_dialog_content = "Your blood and the authority it bequeaths are mine now, Wilhelm Varaki!",
  ui_story_5084_50840802_8_dialog_content = "You will serve as my <color=#FFB400>key</color> and unlock the wisdom of our ancestors for me! Hahahaha!",
  ui_story_5084_50840802_9_dialog_content = "Wilhelm Varaki... He...!",
  ui_story_5084_50840802_10_dialog_content = "Wilhelm... When you told me of your plans to leave, I assumed that you had found a safe haven for Victoria and yourself.",
  ui_story_5084_50840802_11_dialog_content = "So why... Why did you return to this place, you fool...",
  ui_story_5084_50840802_12_dialog_content = "Heheh... Though I suppose I am also a fool for believing <color=#FFB400>that man</color> so easily.",
  ui_story_5084_50840802_13_dialog_content = "Ancestors, I beseech you to accept Wilhelm Varaki into your fold. In spite of the impure ambition that burned in his veins, he has more than lived up to the noble name of the Varaki.",
  ui_story_5084_50840802_14_dialog_content = "Now that he has been betrayed by a sinner such as myself, absolve him of his crimes and give them unto me.",
  ui_story_5084_50840802_15_dialog_content = "Though my soul will soon be cursed, I humbly pray that my wife and Charon will find a way to leave this place...",
  ui_story_5084_50840802_16_dialog_content = "Wilhelm Varaki, my former friend... May you find eternal peace in this coffin.",
  ui_story_5084_50840802_17_dialog_content = "Did he... Really die? Wilhelm Varaki... He's been dead all this time...",
  ui_story_5084_50840802_18_dialog_content = "Is this the truth that the ring wishes to show me?",
  ui_story_5084_50840802_19_dialog_content = "The man who gave it to me three years ago... Is he really gone?",
  ui_story_5084_50840802_20_dialog_content = "... What will you do now?",
  ui_story_5084_50840802_21_dialog_content = "I can sense that I'm drawing ever closer to The Truth.",
  ui_story_5084_50840802_22_dialog_content = "As the current leader of the True Order, I thought that the Lord of Truth guided me here to simply witness this moment once more.",
  ui_story_5084_50840802_23_dialog_content = "But your presence and the previous sacrifice have shown me that I must participate. Aside from my lord's blessing, I also carry an undeniable hatred in my heart.",
  ui_story_5084_50840802_24_dialog_content = "This is something that only I can do, and only with enough control over my power and mind.",
  ui_story_5084_50840802_25_dialog_content = "Blessed be the Lord of Truth for dispelling my doubts and granting me the pleasure of retribution.",
  ui_story_5084_50840802_26_dialog_content = "Tonight is the Advent of Truth. Our resentment arose from our thirst for the wisdom of our ancestors; let them watch as we put an end to it all.",
  ui_story_5084_50840802_27_dialog_content = "People of Varaki Town, please forgive me for keeping you all waiting.",
  ui_story_5084_50840802_28_dialog_content = "After receiving guidance from the Lord of Truth, I now understand my purpose.",
  ui_story_5084_50840802_29_dialog_content = "Doesn't that ring bring you immense pain?",
  ui_story_5084_50840802_30_dialog_content = "Even Wilhelm was unable to wear it so easily.",
  ui_story_5084_50840802_31_dialog_content = "What revelation did you receive?",
  ui_story_5084_50840802_32_dialog_content = "<color=#e8d9bb>Victoria stands up and walks to the head of the table.</color>",
  ui_story_5084_50840802_33_dialog_content = "<color=#FF0000>To purge the order.</color>",
  ui_story_5084_50840802_34_dialog_content = "What?!",
  ui_story_5084_50840802_35_dialog_content = "<color=#e8d9bb>A black wind surges into the temple, violently rattling its doors and windows. Wielding a power far beyond her time, the successor of the Varaki appears to issue an ultimatum to the heads of houses.</color>",
  ui_story_5084_50840802_36_dialog_content = "<color=#e8d9bb>Smash—</color>",
  ui_story_5084_50840802_37_dialog_content = "Dropping your glass in surprise? How crass.",
  ui_story_5084_50840802_38_dialog_content = "...",
  ui_story_5084_50840802_39_dialog_content = "That ring... Tell me what it showed you!",
  ui_story_5084_50840802_40_dialog_content = "Stop, David! Have you forgotten that we are in the Temple of Truth?!",
  ui_story_5084_50840802_41_dialog_content = "...!",
  ui_story_5084_50840802_42_dialog_content = "Since everything began with the festival of our ancestors, it's only fitting that everything should end tonight.",
  ui_story_5084_50840802_43_dialog_content = "Now, if you'll excuse me, as the new head of the Varaki, I must prepare for the Advent of Truth.",
  ui_story_5084_50840802_44_dialog_content = "When the blood moon hands in the sky and the temple halls ring with the sound of bells, we must gather once more to witness the end of this long night.",
  ui_story_5084_50840900_1_dialog_content = "<color=#e8d9bb>In the dim lantern's light, David Porfirio stands in a puddle of blood. Aside from his crazed followers, the only other person in the room is Clavis Abraham, whose body has been tortured beyond recognition.</color>",
  ui_story_5084_50840900_2_dialog_content = "Tell me... Does Wilhelm still live?!",
  ui_story_5084_50840900_3_dialog_content = "Speak... Now...!",
  ui_story_5084_50840900_4_dialog_content = "I've told you everything I know... There's no use torturing me any longer...",
  ui_story_5084_50840900_5_dialog_content = "I laid his lifeless body in that coffin with my own two hands... There was no denying his death...",
  ui_story_5084_50840900_6_dialog_content = "During the Advent of Truth three years ago, Wilhelm helped Victoria escape from the coffin.",
  ui_story_5084_50840900_7_dialog_content = "Unable to suffer his tyranny any longer, we finally rose up against him and destroyed the ring that bound us together.",
  ui_story_5084_50840900_8_dialog_content = "So why, after three years, has Victoria appeared with the very same ring in her hands?!",
  ui_story_5084_50840900_9_dialog_content = "Those two must be plotting something.",
  ui_story_5084_50840900_10_dialog_content = "The Bloody Bible holds no written text. It will not show you the words of the divine which you so desperately seek.",
  ui_story_5084_50840900_11_dialog_content = "The Varaki girl, on the other hand, has proven herself to be much like her father.",
  ui_story_5084_50840900_12_dialog_content = "Heh... Heheheh... Hahahaha—",
  ui_story_5084_50840900_13_dialog_content = "What do you find so amusing?",
  ui_story_5084_50840900_14_dialog_content = "We were fools to cower in fear of Wilhelm's bluffing, and now we are left with no choice.",
  ui_story_5084_50840900_15_dialog_content = "We should have killed him and Victoria the day her parents passed away.",
  ui_story_5084_50840900_16_dialog_content = "Wilhelm's powers were still not awakened at the time, and Victoria was hardly a threat.",
  ui_story_5084_50840900_17_dialog_content = "After bowing to the Varaki for so long, it appears we've all but forgotten... That the so-called \"Truth\" is nothing but the dregs of an outside faith.",
  ui_story_5084_50840900_18_dialog_content = "Indeed. Consuming fresh blood and drawing power from it is the only way for our people to survive!",
  ui_story_5084_50840900_19_dialog_content = "Without our true power, we have been forced to uphold our faith in the <color=#FFB400>Lord of Truth</color> through affirmation, repetition, restraint, and prayer. It's nothing short of heresy!",
  ui_story_5084_50840900_20_dialog_content = "It's too late now, Porfirio... With the ring's power in her hands, she is preparing to destroy us as we speak.",
  ui_story_5084_50840900_21_dialog_content = "No matter how we prepare ourselves, we have less than half a day before we are all...",
  ui_story_5084_50840900_22_dialog_content = "Silence! Wilhelm wore that ring in the past as well, and we were still able to bleed him dry!",
  ui_story_5084_50840900_23_dialog_content = "My only regret is that drinking his blood didn't allow me to form a pact with the Bloody Bible. To begin with, it seems he was never the successor to the Varaki.",
  ui_story_5084_50840900_24_dialog_content = "But thanks to my endless supply of believers, I have steadily regained my power... And now I can finally hear the faint call of the Bloody Bible!",
  ui_story_5084_50840900_25_dialog_content = "Just a bit more... And soon its knowledge will reveal itself to me!",
  ui_story_5084_50840900_26_dialog_content = "The Varaki are to blame for suppressing our bloodline and preventing us from achieving true superiority!",
  ui_story_5084_50840900_27_dialog_content = "We were born to consume the blood of the living, yet the Varaki sought to restrict our natural tendencies... Presumably because they feared our power.",
  ui_story_5084_50840900_28_dialog_content = "What do you intend to do...?",
  ui_story_5084_50840900_29_dialog_content = "The same as we have planned all along... I will appear before the faithful during tonight's ritual, and demonstrate that the Bloody Bible has acknowledged me.",
  ui_story_5084_50840900_30_dialog_content = "With neither strength nor support, Victoria has no way of stopping me.",
  ui_story_5084_50840900_31_dialog_content = "Their family tomb and its meek guardian are the only things they have to rely upon. Goblin, Viper, Undine... I leave the Vinekeepers to the three of you.",
  ui_story_5084_50840900_32_dialog_content = "Understood.",
  ui_story_5084_50840900_33_dialog_content = "If I could kill Wilhelm, then Victoria should be no issue.",
  ui_story_5084_50840900_34_dialog_content = "I need only replenish my strength and see what tricks she has saved for tonight.",
  ui_story_5084_50840900_35_dialog_content = "Nngh... David...",
  ui_story_5084_50840900_36_dialog_content = "... And that's about all we know. After traveling back and forth through time so many times, we barely know where we are.",
  ui_story_5084_50840900_37_dialog_content = "Though The Truth's revelations can be obscure, its plans are not without their meaning.",
  ui_story_5084_50840900_38_dialog_content = "Three years ago, in our current time—the year 1915—I last saw Wilhelm. It was during that Advent of Truth that he ordered me into the ancestral coffin.",
  ui_story_5084_50840900_39_dialog_content = "I recall seeing him twisting the ring on his finger at the time, which was something I had never seen him do before. It was then that I knew...",
  ui_story_5084_50840900_40_dialog_content = "He was trying to tell me something. That was why I decided to take part in the ritual.",
  ui_story_5084_50840900_41_dialog_content = "But when I came to, I found myself in the current \"present.\"",
  ui_story_5084_50840900_42_dialog_content = "Three years had passed, and I woke up in my bed with our family's ring in my hand.",
  ui_story_5084_50840900_43_dialog_content = "Wilhelm had given it to me at the very end of that ritual.",
  ui_story_5084_50840900_44_dialog_content = "And when I awoke, I found myself in that mansion just as someone arrived with a letter. He entrusted me with delivering it to Lady Victoria before taking his leave.",
  ui_story_5084_50840900_45_dialog_content = "Just as I began wondering about my situation, Lady Victoria emerged from the nearby room.",
  ui_story_5084_50840900_46_dialog_content = "The letter merely asked that I attend the meeting of the heads of families before the Advent of Truth. But clearly, they were not anticipating my appearance.",
  ui_story_5084_50840900_47_dialog_content = "Whoever came to deliver that letter knew I was here. Not only that, but they knew it was the present me, not the Victoria, belonging to this point.",
  ui_story_5084_50840900_48_dialog_content = "That reminds me, Lady Victoria... We ran into Nails earlier but... He was acting really strangely...",
  ui_story_5084_50840900_49_dialog_content = "He thanked Wilhelm for giving him a chance to be there, even though Wilhelm had no idea who he was.",
  ui_story_5084_50840900_50_dialog_content = "Could the person who arranged all of this be the Wilhelm from the Advent of Truth three years ago?",
  ui_story_5084_50840900_51_dialog_content = "He was dead in the visions we saw earlier, and yet he somehow still exists in the past.",
  ui_story_5084_50840900_52_dialog_content = "He must have done something during the Advent of Truth three years ago, something that still lies beyond our understanding.",
  ui_story_5084_50840900_53_dialog_content = "Even so, I can sense that we're drawing even closer to The Truth.",
  ui_story_5084_50840900_54_dialog_content = "Lady Victoria, I must ask... Where exactly were you during the Advent of Truth of 1918?",
  ui_story_5084_50840900_55_dialog_content = "If I remember correctly... I was still traveling during that year's Advent of Truth. As such, I had no way of being present at that meeting.",
  ui_story_5084_50840900_56_dialog_content = "But that same night, I was asleep in the town of Vortex when The Truth commanded me to return for the Bloody Bible.",
  ui_story_5084_50840900_57_dialog_content = "When I woke up, I found myself in a <color=#FFB400>coffin</color> deep within the tomb of the Varaki, the Bloody Bible clutched tightly in my hands.",
  ui_story_5084_50840900_58_dialog_content = "Afterwards, it revealed to me that it had acknowledged Vortex, and that I was to be the leader of the True Order.",
  ui_story_5084_50840900_59_dialog_content = "This was the memory that was shown to me by the ring before we departed on our quest.",
  ui_story_5084_50840900_60_dialog_content = "Did you say... A <color=#FFB400>coffin</color> in the tomb of the Varaki? But why was it a <color=#FFB400>coffin</color>?",
  ui_story_5084_50840900_61_dialog_content = "Perhaps it was because... I have a habit of sleeping in them as well.",
  ui_story_5084_50840900_62_dialog_content = "(That's true... She did that in her parents' coffin... Wilhelm's too...)",
  ui_story_5084_50840900_63_dialog_content = "Perhaps the coffins in the Varaki Family's tomb possess some sort of unknown power?",
  ui_story_5084_50840900_64_dialog_content = "Like the power to travel to different times?",
  ui_story_5084_50840900_65_dialog_content = "Much like the Caelestite's candlestick, perhaps they can also transport you to various points in time.",
  ui_story_5084_50840900_66_dialog_content = "It also helped Wilhelm open the door to the crypt during the Advent of Truth three years ago...",
  ui_story_5084_50840900_67_dialog_content = "Sikare... Just how many of these things does she have?!",
  ui_story_5084_50840900_68_dialog_content = "Sikare's family has always protected the crypt and kept Lady Victoria from peering within.",
  ui_story_5084_50840900_69_dialog_content = "Whenever we asked, Sikare would simply say that it was not yet time... So why is this the right time?",
  ui_story_5084_50840900_70_dialog_content = "Perhaps there is a deeper meaning behind Wilhelm's disappearance, and even his death.",
  ui_story_5084_50840900_71_dialog_content = "It seems he had been aware of the danger that he faced on that day for a long time, and he was simply waiting for us to appear.",
  ui_story_5084_50840900_72_dialog_content = "He once demanded that I give him an explanation of The Truth. He was almost relentless about it... But now I realize that he never expected a \"correct\" answer from me.",
  ui_story_5084_50840900_73_dialog_content = "Because The Truth has no correct answer, and it never will.",
  ui_story_5084_50840900_74_dialog_content = "It is an unwavering faith that seeks to offer infinite answers.",
  ui_story_5084_50840900_75_dialog_content = "And now that I understand the power of these answers, I no longer harbor any fear or doubt. My purpose is clear: I must purge the heads of families from the True Order.",
  ui_story_5084_50840900_76_dialog_content = "If only he had been able to speak candidly with me three years ago and understood my search...",
  ui_story_5084_50840900_77_dialog_content = "(The two of them were just being stubborn for so long... Is there really no way for them to reconcile after all this time?)",
  ui_story_5084_50840900_78_dialog_content = "In any case, I will not stop... Until I've discovered the meaning behind this ring reappearing in my possession.",
  ui_story_5084_50840900_79_dialog_content = "(After leaping back and forth through time so many times... I'd like a definitive answer, too...)",
  ui_story_5084_50840900_80_dialog_content = "(Why do Victoria and I see Wilhelm so differently? From what I've seen, he really does care about her, but he doesn't seem that way in her memories.)",
  ui_story_5084_50840900_81_dialog_content = "(Something's still missing... Whatever it is, I'm sure things will be much clearer once we find it. Victoria might even have a chance to give Wilhelm her answer...)",
  ui_story_5084_50840900_82_dialog_content = "(... What gives, candlestick? You always lead me to an answer whenever I have questions, so why aren't you working this time?)",
  ui_story_5084_50840900_83_dialog_content = "(Ah... I think I finally understand where the True Order's unshakeable faith comes from...)",
  ui_story_5084_50840900_84_dialog_content = "Night has fallen, and the Advent of Truth is nearly upon us. We don't have much time left.",
  ui_story_5084_50840900_85_dialog_content = "Time... That reminds me, I only have about a third of my candlestick left.",
  ui_story_5084_50840900_86_dialog_content = "Don't worry, I know what must be done now.",
  ui_story_5084_50840900_87_dialog_content = "My threats during the meeting struck fear into their hearts, which has only stoked their desire for more power. They will stop at nothing to defeat me now.",
  ui_story_5084_50840900_88_dialog_content = "But what if they try to run away? You can be pretty scary when you want to be, Victoria.",
  ui_story_5084_50840900_89_dialog_content = "David Porfirio's ambition won't allow him to run away. He will never be content unless he achieves his goal.",
  ui_story_5084_50840900_90_dialog_content = "It appears he has the Bloody Bible of this time in his possession.",
  ui_story_5084_50840900_91_dialog_content = "To realize his aspiration of becoming the leader of the True Order, he will stay and do everything in his power to preside over tonight's ritual.",
  ui_story_5084_50840900_92_dialog_content = "Ambition can be a terrifying beast. Just as it consumed Wilhelm, so too will it consume David.",
  ui_story_5084_50840900_93_dialog_content = "So where should we go?",
  ui_story_5084_50840900_94_dialog_content = "To the tomb of my ancestors—There's something I need to confirm there. If things proceed as expected, David will send someone there as well.",
  ui_story_5084_50840900_95_dialog_content = "Wait, Lady Victoria... What should we do about Mr. Nails?",
  ui_story_5084_50840900_96_dialog_content = "He's still somewhere in the town.",
  ui_story_5084_50840900_97_dialog_content = "There's no need to worry for his sake. Our lord has blessed him with protection, and The Truth will guide him to where he needs to be.",
  ui_story_5084_50840900_98_dialog_content = "But Lady Victoria, I saw the heads of families hurt him badly with my own two eyes...",
  ui_story_5084_50840900_99_dialog_content = "I'm still worried about him, and I've been wanting to look for him all this time. I'm just not sure if it'll cause more problems for everyone.",
  ui_story_5084_50840900_100_dialog_content = "To feel confused is no cause for alarm, and worrying for the sake of others is a noble quality. Do as your heart tells you to do, May.",
  ui_story_5084_50840900_101_dialog_content = "Faust, please stay with May and look after Nails.",
  ui_story_5084_50840900_102_dialog_content = "The Caelestite and I will meet you in the temple tonight.",
  ui_story_5084_50841001_1_dialog_content = "The vines at the entrance are covered in blood, and the coffins have been pried open... Were the heads of families one step ahead of us?",
  ui_story_5084_50841001_2_dialog_content = "Disturbing the remains of our ancestors... Their disregard for our doctrines knows no bounds.",
  ui_story_5084_50841001_3_dialog_content = "I think this is the place we saw earlier!",
  ui_story_5084_50841001_4_dialog_content = "This is where Clavis placed Wilhelm in that coffin...",
  ui_story_5084_50841001_5_dialog_content = "Yet his coffin is nowhere to be seen.",
  ui_story_5084_50841001_6_dialog_content = "My lady... Lady Victoria... Is that you?",
  ui_story_5084_50841001_7_dialog_content = "Graves? Thank goodness you still live. When I saw the vines outside, I feared the worst...",
  ui_story_5084_50841001_8_dialog_content = "Three years, my lady... For three years, there was no head of the Varaki Family to defend this place, and so it fell into chaos.",
  ui_story_5084_50841001_9_dialog_content = "With Wilhelm's death and your whereabouts unknown, the heads of the branch families plundered the relics of this tomb with absolute impunity.",
  ui_story_5084_50841001_10_dialog_content = "They took my family and tortured them... Tortured me...",
  ui_story_5084_50841001_11_dialog_content = "It was David Porfirio... He seeks to take everything away, including my power as a servant of the Varaki...",
  ui_story_5084_50841001_12_dialog_content = "... Forgive me. I had no idea that my absence would bring you and your family such unspeakable harm.",
  ui_story_5084_50841001_13_dialog_content = "Graves... Is Wilhelm truly dead?",
  ui_story_5084_50841001_14_dialog_content = "Clavis... What have you done?",
  ui_story_5084_50841001_15_dialog_content = "... I've merely come to place another body in your care.",
  ui_story_5084_50841001_16_dialog_content = "Please watch over my fool of a friend.",
  ui_story_5084_50841001_17_dialog_content = "Clavis... Clavis...",
  ui_story_5084_50841001_18_dialog_content = "I saw it with my own eyes, my lady. Wilhelm was dead... And Clavis Abraham used that key to enter the tomb and lay him to rest.",
  ui_story_5084_50841001_19_dialog_content = "... Let us go inside, Caelestite.",
  ui_story_5084_50841001_20_dialog_content = "You have my word, Graves: I will put a stop to all of this strife tonight.",
  ui_story_5084_50841001_21_dialog_content = "Please be careful... My lady...",
  ui_story_5084_50841001_22_dialog_content = "In the furthest reaches of the crypt... They continue to disturb the dead... In search of something...",
  ui_story_5084_50841001_23_dialog_content = "Well look who's here.",
  ui_story_5084_50841001_24_dialog_content = "The young lady of the Varaki herself.",
  ui_story_5084_50841001_25_dialog_content = "... My lady!",
  ui_story_5084_50841001_26_dialog_content = "I'm surprised you survived, Vinekeeper...",
  ui_story_5084_50841001_27_dialog_content = "Porfirio wishes to dispose of the Varaki woman, yes?",
  ui_story_5084_50841001_28_dialog_content = "Now is our chance.",
  ui_story_5084_50841001_29_dialog_content = "Foolish minions...!",
  ui_story_5084_50841001_30_dialog_content = "How dare you trespass into the tomb of the Varaki and disturb our slumbering ancestors!",
  ui_story_5084_50841001_31_dialog_content = "I meant to punish every single one of you during tonight's ritual, but it seems you've brought the fight to me.",
  ui_story_5084_50841002_1_dialog_content = "Victoria... The one called Undine burrowed underground and escaped...",
  ui_story_5084_50841002_2_dialog_content = "Hmph, that just leaves these two. Are you ready to accept your fates?",
  ui_story_5084_50841002_3_dialog_content = "Wait, Lady Victoria... As an adult and a respectable member of the Varaki, perhaps you should speak to Porfirio before doing anything rash?",
  ui_story_5084_50841002_4_dialog_content = "Impossible! You were gone for only three years... Where did you obtain such power?!",
  ui_story_5084_50841002_5_dialog_content = "Three years, you say? It seems you've been trapped in your own stagnant world for so long that you cannot fathom such drastic changes any longer.",
  ui_story_5084_50841002_6_dialog_content = "I have been accumulating this power for far longer than three years... But I have no intention of revealing my secrets to you.",
  ui_story_5084_50841002_7_dialog_content = "For allowing your desires to lead you away from The Truth, your lives must be offered as a prelude to the Advent of Truth!",
  ui_story_5084_50841002_8_dialog_content = "(Sikare told us not to change anything, but Victoria killed them both... Does that not count as changing the past?!)",
  ui_story_5084_50841002_9_dialog_content = "(Or could it be... were Victoria's actions written in the pages of history long ago?)",
  ui_story_5084_50841002_10_dialog_content = "Hmm?",
  ui_story_5084_50841002_11_dialog_content = "It seems you don't understand... the secret of the viper either.",
  ui_story_5084_50841002_12_dialog_content = "Even if you sever my head, I will shed my skin and be born anew...",
  ui_story_5084_50841002_13_dialog_content = "Then I will sever it as many times as it takes!",
  ui_story_5084_50841002_14_dialog_content = "W-Wait! You can't kill me this way!",
  ui_story_5084_50841002_15_dialog_content = "It was never my intention to do so. I'm simply curious to see how much longer you can withstand the pain of having your head cut off.",
  ui_story_5084_50841002_16_dialog_content = "Now scream! Plead for mercy! <size=45>Beg me to put you out of your misery—!</size>",
  ui_story_5084_50841002_17_dialog_content = "(Jeez, Victoria... I didn't realize she could be this cruel...)",
  ui_story_5084_50841002_18_dialog_content = "<color=#e8d9bb>Suddenly, one of the coffins within the crypt bursts open with violent force, and a person steps out of it—</color>",
  ui_story_5084_50841002_19_dialog_content = "No need to waste your strength on the likes of him.",
  ui_story_5084_50841002_20_dialog_content = "?!",
  ui_story_5084_50841002_21_dialog_content = "... W-Wilhelm?!?",
  ui_story_5084_50841002_22_dialog_content = "Impossible! You were supposed to have died a long time ago!",
  ui_story_5084_50841002_23_dialog_content = "... So you're still alive after all.",
  ui_story_5084_50841002_24_dialog_content = "Not quite. Following my death, I spent many years traversing the endless flow of time, and now I finally have a faint inkling of our lord's will.",
  ui_story_5084_50841002_25_dialog_content = "The Advent of Truth three years ago... It was you.",
  ui_story_5084_50841002_26_dialog_content = "Three years... A blink of an eye in the grand scheme of existence. It was destiny which guided me here, and this appears to be my final stop.",
  ui_story_5084_50841002_27_dialog_content = "...?!",
  ui_story_5084_50841002_28_dialog_content = "(I knew it! There really were two Wilhelms all along!)",
  ui_story_5084_50841002_29_dialog_content = "(So the one who sacrificed Victoria and arranged all of this... Was Wilhelm after his own death?)",
  ui_story_5084_50841002_30_dialog_content = "Take this. It is a symbol of fate's desire to follow you—",
  ui_story_5084_50841002_31_dialog_content = "... The Bloody Bible?",
  ui_story_5084_50841002_32_dialog_content = "No... This is nothing like the relic that I've come to know over the years.",
  ui_story_5084_50841002_33_dialog_content = "A new Bloody Bible, meant for one who will guide the future.",
  ui_story_5084_50841002_34_dialog_content = "Take it, for you are the only one who can wield its power.",
  ui_story_5084_50841002_35_dialog_content = "Use it to defeat the foolish traitors who stand before you.",
  ui_story_5084_50841002_36_dialog_content = "... I refuse.",
  ui_story_5084_50841002_37_dialog_content = "...?!",
  ui_story_5084_50841002_38_dialog_content = "I don't need your power—They were the ones who killed you, so your revenge is your own business.",
  ui_story_5084_50841002_39_dialog_content = "What is the meaning of this? Why are we powerless against him?!",
  ui_story_5084_50841002_40_dialog_content = "That man is not the same man we killed in the past.",
  ui_story_5084_50841002_41_dialog_content = "Curse you, Wilhelm! What exactly happened to you after you died?! You have to tell us... At least share this Truth with us!",
  ui_story_5084_50841002_42_dialog_content = "... Silence, traitors!",
  ui_story_5084_50841002_43_dialog_content = "The Truth has no need for your understanding!",
  ui_story_5084_50841002_44_dialog_content = "It only demands your blood in exchange for your crimes against the Varaki's ancestors!",
  ui_story_5084_50841002_45_dialog_content = "Va... raki...",
  ui_story_5084_50841002_46_dialog_content = "(Wilhelm destroyed them both with a single attack...!)",
  ui_story_5084_50841002_47_dialog_content = "Wilhelm Varaki... This coffin was supposed to contain the remains of our ancestors. What exactly happened to you?",
  ui_story_5084_50841002_48_dialog_content = "Why did you disappear? And what caused you to reappear before us today?",
  ui_story_5084_50841002_49_dialog_content = "Have you been reborn? Or are you just a phantom now?",
  ui_story_5084_50841002_50_dialog_content = "You are just as I remember, Victoria: always so full of questions.",
  ui_story_5084_50841002_51_dialog_content = "Unfortunately, there is no use discussing these things anymore. Time has slipped past us, and we have long since been dead.",
  ui_story_5084_50841002_52_dialog_content = "Farewell, Victoria.",
  ui_story_5084_50841002_53_dialog_content = "(He's leaving just like that...? They finally have a chance to see each other again and clearly care about each other... So why won't they say anything?)",
  ui_story_5084_50841002_54_dialog_content = "P-Please wait, Mr. Wilhelm!",
  ui_story_5084_50841002_55_dialog_content = "Caelestite...",
  ui_story_5084_50841002_56_dialog_content = "And you are...?",
  ui_story_5084_50841002_57_dialog_content = "Wait, that voice...",
  ui_story_5084_50841002_58_dialog_content = "Ah... I see now...",
  ui_story_5084_50841002_59_dialog_content = "This must be fate...",
  ui_story_5084_50841002_60_dialog_content = "Heheh... How amusing...",
  ui_story_5084_50841002_61_dialog_content = "Mr. Wilhelm! You may call it \"fate\"—",
  ui_story_5084_50841002_62_dialog_content = "But when you heard its words, you still decided to pursue The Truth in your heart. You went to the crypt because you were worried about Victoria!",
  ui_story_5084_50841002_63_dialog_content = "And rather than accept her predetermined fate, Victoria chose to wear the ring and endure those voices in order to find you...",
  ui_story_5084_50841002_64_dialog_content = "You've already accomplished the unimaginable by traveling back and forth through time; would it really be that unreasonable for the two of you to have a normal conversation?",
  ui_story_5084_50841002_65_dialog_content = "When you fought side-by-side against the heads of families... I was able to see the emotions driving your actions.",
  ui_story_5084_50841002_66_dialog_content = "I'm sorry... I don't know if I'm changing history by saying something I shouldn't say...",
  ui_story_5084_50841002_67_dialog_content = "But from the bottom of my heart, I believe in everything that I'm about to say—",
  ui_story_5084_50841002_68_dialog_content = "I've always thought words were the best way to keep a secret... If you don't open up to each other right now, you may never have a chance to understand one another ever again.",
  ui_story_5084_50841002_69_dialog_content = "...",
  ui_story_5084_50841002_70_dialog_content = "...",
  ui_story_5084_50841002_71_dialog_content = "Questions, answers... Neither of them really matters anymore. All that matters is that you two are here right now.",
  ui_story_5084_50841002_72_dialog_content = "Regardless of whether or not \"fate\" decides it, each of your decisions should come from the heart.",
  ui_story_5084_50841002_73_dialog_content = "Caelestite... You...",
  ui_story_5084_50841002_74_dialog_content = "Heheh, if only the rest of the world could be as sincere as you... Then perhaps they wouldn't be led astray so easily.",
  ui_story_5084_50841002_75_dialog_content = "A sincerity so pure is one of the greatest treasures belonging to young Caelestites.",
  ui_story_5084_50841002_76_dialog_content = "Now then... Where to begin?",
  ui_story_5084_50841002_77_dialog_content = "I have drifted through time for countless ages now... And I have never yearned for the end more than I do now.",
  ui_story_5084_50841002_78_dialog_content = "Victoria... I finally understand my brother's wish for eternal sleep, and I believe you understand it as well.",
  ui_story_5084_50841002_79_dialog_content = "The choices made by our hearts are more numerous than the stars in the sky.",
  ui_story_5084_50841002_80_dialog_content = "I must thank you, Victoria... You will free the Varaki from their blood curse someday, and I will finally be able to rest in peace.",
  ui_story_5084_50841002_81_dialog_content = "It's so unlike you to express gratitude... Will I truly be the one to undo our family's curse...?",
  ui_story_5084_50841002_82_dialog_content = "As the Caelestite says, our questions and answers...",
  ui_story_5084_50841002_83_dialog_content = "Are not important now!",
  ui_story_5084_50841002_84_dialog_content = "The Truth varies from person to person. There is no final or absolute answer; only a belief which must be constantly pursued.",
  ui_story_5084_50841002_85_dialog_content = "... You may speak your mind now.",
  ui_story_5084_50841002_86_dialog_content = "Our world is marked by suffering and differences. Those blessed with immortality are consumed by their desire for death, while their mortal counterparts yearn for longer futures.",
  ui_story_5084_50841002_87_dialog_content = "Does a savior truly exist in <color=#FFB400>Eoria</color>?",
  ui_story_5084_50841002_88_dialog_content = "In my visions, I have seen untold suffering, and yet my belief in <color=#FFB400>salvation</color> has only grown stronger because of it.",
  ui_story_5084_50841002_89_dialog_content = "Therefore, The Truth which I seek must lead to the <color=#FFB400>salvation</color> of the world, and the eradication of every fallen seed.",
  ui_story_5084_50841002_90_dialog_content = "By transcending the limitations of consciousness and corporeality, Aurorians will attain their final evolution and draw closer to the stars, where the supreme Truth awaits their arrival.",
  ui_story_5084_50841002_91_dialog_content = "... You have indeed grown and become a worthy leader, Victoria. It is just as The Truth revealed to me.",
  ui_story_5084_50841002_92_dialog_content = "You mentioned the stars... In the moment of my demise, I saw a river in the darkness.",
  ui_story_5084_50841002_93_dialog_content = "In it, the causality of all existence flows without end. Even the slightest disturbance can result in an unfathomable catastrophe.",
  ui_story_5084_50841002_94_dialog_content = "As members of the immortal family of blood, we have spent an inordinate amount of time chasing after something that is but a grain of sand in this river.",
  ui_story_5084_50841002_95_dialog_content = "Even so, my relentless obsession led me to that river.",
  ui_story_5084_50841002_96_dialog_content = "I have since strengthened The Truth within my heart—And though my journey has been one of hardship and suffering, I am convinced that my wishes will eventually influence the flow of causality.",
  ui_story_5084_50841002_97_dialog_content = "Do you believe your convictions are powerful enough to transcend the shackles of destiny?",
  ui_story_5084_50841002_98_dialog_content = "Yes. I will obey them, practice them, and ultimately... I will find a way to see fate's designs and reshape them with my own hands.",
  ui_story_5084_50841002_99_dialog_content = "... Now go, Victoria. Travel down the path of your Truth, and remove any obstacles which stand in your way.",
  ui_story_5084_50841002_100_dialog_content = "As I surely will.",
  ui_story_5084_50841002_101_dialog_content = "Then I leave David to you. Stop him before he turns our town into a place of death.",
  ui_story_5084_50841002_102_dialog_content = "Where will you go now?",
  ui_story_5084_50841002_103_dialog_content = "I am already a being which exists outside the flow of time. I can only alter the events of history if destiny permits...",
  ui_story_5084_50841002_104_dialog_content = "... I never expected to have this final discussion with you, uncle.",
  ui_story_5084_50841002_105_dialog_content = "You really have matured, Victoria... How reassuring.",
  ui_story_5084_50841002_106_dialog_content = "Now, take this Bloody Bible in your hands. You will need it.",
  ui_story_5084_50841002_107_dialog_content = "I already have the power I need to pursue The Truth. There's no reason for me to take it.",
  ui_story_5084_50841002_108_dialog_content = "... Even so, destiny will guide you to it someday.",
  ui_story_5084_50841002_109_dialog_content = "Farewell, Victoria Varaki.",
  ui_story_5084_50841002_110_dialog_content = "Your disciple, the one called Nails... He can be taught much.",
  ui_story_5084_50841002_111_dialog_content = "I leave the future of the True Order in your hands.",
  ui_story_5084_50841002_112_dialog_content = "... Will we ever see each other again?",
  ui_story_5084_50841002_113_dialog_content = "I have already completed the task set before me by our lord. Now, the time has come for me to attend to my own matters.",
  ui_story_5084_50841002_114_dialog_content = "When all things have ended, come find me here.",
  ui_story_5084_50841002_115_dialog_content = "And as for you, Caelestite of the future... Thank you for guiding me with your sincerity.",
  ui_story_5084_50841101_1_dialog_content = "This is all grandmother's fault... She insisted on making me listen to her prayers to the Lord of Truth before letting me leave...",
  ui_story_5084_50841101_2_dialog_content = "Now I'm stuck at the back of the crowd with no way of seeing the procession!",
  ui_story_5084_50841101_3_dialog_content = "Your grandmother is too old to take part in the Advent of Truth anymore, dear.",
  ui_story_5084_50841101_4_dialog_content = "But after spending all her life making clothes for the faithful, she still wants someone to present her wishes to the Lord of Truth. That is why she entrusted them to you.",
  ui_story_5084_50841101_5_dialog_content = "I'll hold you up to see the procession—But you must remember your grandmother's words. This is a sincere occasion, and you must treat it as such.",
  ui_story_5084_50841101_6_dialog_content = "... I understand.",
  ui_story_5084_50841101_7_dialog_content = "This street's pretty familiar. It's where I ran into PlayerName before.",
  ui_story_5084_50841101_8_dialog_content = "But how are we supposed to find Nails in a huge crowd like this?",
  ui_story_5084_50841101_9_dialog_content = "May... Do you remember seeing these strangely-garbed people before?",
  ui_story_5084_50841101_10_dialog_content = "L-Let me think about it...",
  ui_story_5084_50841101_11_dialog_content = "Ah—!!!",
  ui_story_5084_50841101_12_dialog_content = "What was that? Let us go investigate, May!",
  ui_story_5084_50841101_13_dialog_content = "... It's the undead! They walk among us—!",
  ui_story_5084_50841101_14_dialog_content = "Almighty lord... This must be my punishment for reading my sister's secret diary and revealing her hypocrisy to the public...",
  ui_story_5084_50841101_15_dialog_content = "But the leaders of the True Order claimed that I was sick, and that you would never favor my blood.",
  ui_story_5084_50841101_16_dialog_content = "I must repent with my flesh...!",
  ui_story_5084_50841101_17_dialog_content = "Mother...?",
  ui_story_5084_50841101_18_dialog_content = "But I beg you to spare my daughter, lord. She is but an innocent child...",
  ui_story_5084_50841101_19_dialog_content = "O Lord of Truth!",
  ui_story_5084_50841101_20_dialog_content = "Are these your servants? Have they come... To punish me for my sins?",
  ui_story_5084_50841101_21_dialog_content = "I understand, and I submit to your divine will! Do as you must to me!",
  ui_story_5084_50841101_22_dialog_content = "—!",
  ui_story_5084_50841101_23_dialog_content = "Mother—!",
  ui_story_5084_50841101_24_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_25_dialog_content = "R-Run, child—!",
  ui_story_5084_50841101_26_dialog_content = "Blood is flowing through the streets. These robed monsters... They're attacking the townspeople!",
  ui_story_5084_50841101_27_dialog_content = "May! Prepare for battle!",
  ui_story_5084_50841101_28_dialog_content = "As I thought... Now that Lady Victoria has taken action, fate is allowing us to interfere.",
  ui_story_5084_50841101_29_dialog_content = "Sounds good to me! Time to punish some naughty children!",
  ui_story_5084_50841101_30_dialog_content = "... I feel no pain!",
  ui_story_5084_50841101_31_dialog_content = "There are still so many of them...!",
  ui_story_5084_50841101_32_dialog_content = "Ah...!!!",
  ui_story_5084_50841101_33_dialog_content = "Mother—!!!!",
  ui_story_5084_50841101_34_dialog_content = "Fear not, my lost lamb... The Sacred Blood is about to condense and take shape...",
  ui_story_5084_50841101_35_dialog_content = "It's you... The Initiate! But why are you hurting yourself?!",
  ui_story_5084_50841101_36_dialog_content = "Silly child... This is not my power, and I am not this so-called \"Initiate.\" I am Nails...",
  ui_story_5084_50841101_37_dialog_content = "The Lord of Truth told me to feel neither pity nor remorse.",
  ui_story_5084_50841101_38_dialog_content = "Though your mother is a sinner just like me...",
  ui_story_5084_50841101_39_dialog_content = "I must answer for all sinners!",
  ui_story_5084_50841101_40_dialog_content = "What... What is this...?",
  ui_story_5084_50841101_41_dialog_content = "It is both a sin... And a blessing...",
  ui_story_5084_50841101_42_dialog_content = "It is the power of the Sacred Blood... The power mentioned by my mentor!",
  ui_story_5084_50841101_43_dialog_content = "It boils with life as it courses through my veins, burning me with the infinite warmth of our lord!",
  ui_story_5084_50841101_44_dialog_content = "Behold, my lost lamb—",
  ui_story_5084_50841101_45_dialog_content = "The Lord of Truth shall absolve us of our sins!",
  ui_story_5084_50841101_46_dialog_content = "...!",
  ui_story_5084_50841101_47_dialog_content = "It's you... The Initiate from earlier today! You've ascended and become one of our lord's holy saints!",
  ui_story_5084_50841101_48_dialog_content = "No... Please don't refer to me that way... I am simply—",
  ui_story_5084_50841101_49_dialog_content = "The robes you're wearing... They're the robes that my mother and grandmother crafted just for you.",
  ui_story_5084_50841101_50_dialog_content = "It was thanks to you and your family that I was able to become the person I am today.",
  ui_story_5084_50841101_51_dialog_content = "Lord Wilhelm must have had his reasons back then... But you will most certainly be chosen as the Initiate this year!",
  ui_story_5084_50841101_52_dialog_content = "My mentor has shown me many noble truths, for which I am eternally grateful.",
  ui_story_5084_50841101_53_dialog_content = "Now please, leave this place before the danger returns. All will be well, I assure you.",
  ui_story_5084_50841101_54_dialog_content = "Very well. May the Truth bless you now and forever, Saint Nails!",
  ui_story_5084_50841101_55_dialog_content = "May The Truth bless you, Saint Nails!",
  ui_story_5084_50841101_56_dialog_content = "May The Truth bless you as well.",
  ui_story_5084_50841101_57_dialog_content = "\"Saint Nails,\" huh?",
  ui_story_5084_50841101_58_dialog_content = "We saw you vanquish those monsters from afar.",
  ui_story_5084_50841101_59_dialog_content = "Oh? May, Faust... It's been quite some time, hasn't it?",
  ui_story_5084_50841101_60_dialog_content = "I... I'm just glad you're okay!",
  ui_story_5084_50841101_61_dialog_content = "PlayerName and I were so worried about you!",
  ui_story_5084_50841101_62_dialog_content = "It was my fault for overestimating my abilities... I caused you unnecessary concern... And for that I must repent...",
  ui_story_5084_50841101_63_dialog_content = "Your power just now was incredible! Does it have something to do with these robes?",
  ui_story_5084_50841101_64_dialog_content = "Possibly... For the last three years, I have been wearing the robes crafted for me by that family of seamstresses.",
  ui_story_5084_50841101_65_dialog_content = "Y-You mean you never went anywhere else? In other words... You've been sitting around in Varaki Town for three whole years?!",
  ui_story_5084_50841101_66_dialog_content = "Not sitting around, May, but practicing under my mentor... He took me to many different places... Not just in town, either.",
  ui_story_5084_50841101_67_dialog_content = "Your mentor...",
  ui_story_5084_50841101_68_dialog_content = "Is it because of his training that you can condense and reshape your blood like this now?",
  ui_story_5084_50841101_69_dialog_content = "Indeed... My mentor claims that my Rare Blood is anything but a curse...",
  ui_story_5084_50841101_70_dialog_content = "\"Where you lose, here you gain. Where you atone, here you are blessed.\"",
  ui_story_5084_50841102_1_dialog_content = "<color=#e8d9bb>Three years ago...</color>",
  ui_story_5084_50841102_2_dialog_content = "O Lord of Truth, your humble servant Nails begs you to free him from his suffering once more...",
  ui_story_5084_50841102_3_dialog_content = "A vile presence permeates my blood... I have long since been ready for the end...",
  ui_story_5084_50841102_4_dialog_content = "What's this...?",
  ui_story_5084_50841102_5_dialog_content = "Though Lady Victoria once said that my piety would guide me... I yearn for sacrifice...",
  ui_story_5084_50841102_6_dialog_content = "I will...",
  ui_story_5084_50841102_7_dialog_content = "...",
  ui_story_5084_50841102_8_dialog_content = "... My lord?",
  ui_story_5084_50841102_9_dialog_content = "It's you! The almighty Lord of Truth!",
  ui_story_5084_50841102_10_dialog_content = "Did you just say... Lady Victoria?",
  ui_story_5084_50841102_11_dialog_content = "I am but a shameless sinner... But my faults did not concern Lady Victoria.",
  ui_story_5084_50841102_12_dialog_content = "She took me in and blessed me with the companionship of the True order... Yet I repay her kindness by allowing my tainted blood to pollute this world.",
  ui_story_5084_50841102_13_dialog_content = "So this Lady Victoria is the leader of the True Order, and you are one of its members?",
  ui_story_5084_50841102_14_dialog_content = "Yes, my lord... My name is Nails.",
  ui_story_5084_50841102_15_dialog_content = "Are you the only one in this crypt?",
  ui_story_5084_50841102_16_dialog_content = "No, my lord. I am joined by Lady Victoria, Faust, May, and the Caelestite... We entered the crypt together, but were separated soon afterwards.",
  ui_story_5084_50841102_17_dialog_content = "They are brave, kind, and full of light... I'm certain you guided them to where they needed to be, my lord...",
  ui_story_5084_50841102_18_dialog_content = "\"To serve as a guide for The Truth...\"",
  ui_story_5084_50841102_19_dialog_content = "You followed your own paths... I am surprised that a Caelestite has joined the True Order...",
  ui_story_5084_50841102_20_dialog_content = "\"The Truth has revealed itself in his heart and blessed him. He is an agent of change within the True Order.\"",
  ui_story_5084_50841102_21_dialog_content = "To be blessed by The Truth...",
  ui_story_5084_50841102_22_dialog_content = "Do you wish to confess anything to the Lord of Truth?",
  ui_story_5084_50841102_23_dialog_content = "I confess... That I have sinned from the very moment I was born. See for yourself, my lord...",
  ui_story_5084_50841102_24_dialog_content = "Only a sinful creature such as myself would be cursed with such tainted blood...",
  ui_story_5084_50841102_25_dialog_content = "Such foolish words...",
  ui_story_5084_50841102_26_dialog_content = "M-My lord...?",
  ui_story_5084_50841102_27_dialog_content = "The sun yet shines upon the land. I have time to listen to your sinful past.",
  ui_story_5084_50841102_28_dialog_content = "You need not concern yourself with my actions, now speak.",
  ui_story_5084_50841102_29_dialog_content = "I only ask that you put that nail away. This is the tomb of the Varaki, and I will not allow you to spill your blood in it.",
  ui_story_5084_50841102_30_dialog_content = "As you command, Lord of Truth!",
  ui_story_5084_50841102_31_dialog_content = "Furthermore, I'm not the Lord of Truth.",
  ui_story_5084_50841102_32_dialog_content = "No? Then who are you—?",
  ui_story_5084_50841102_33_dialog_content = "My name is Wilhelm Varaki, though that surname is hardly fitting for a man such as myself.",
  ui_story_5084_50841102_34_dialog_content = "... \"Varaki\"?! You share the same glorious surname as Lady Victoria!",
  ui_story_5084_50841102_35_dialog_content = "\"Glorious,\" you say? Heheh, it's nothing more than a name used to intimidate others.",
  ui_story_5084_50841102_36_dialog_content = "The person you see before you is someone with intricate ties to the True Order, a being that exists beyond the flow of time.",
  ui_story_5084_50841102_37_dialog_content = "Now tell me, who is it that sees you as a monster?",
  ui_story_5084_50841102_38_dialog_content = "My brother... My parents... My entire family...",
  ui_story_5084_50841102_39_dialog_content = "And this is all because of the so-called \"Rare Blood\" that flows in your veins?",
  ui_story_5084_50841102_40_dialog_content = "Yes... But also because my very existence brought harm to my brother, and shame to my family.",
  ui_story_5084_50841102_41_dialog_content = "My brother was once a kind and brave member of the Order, much like my companions...",
  ui_story_5084_50841102_42_dialog_content = "In the past, I was seemingly on the path to wealth and glory because of my powers, which allowed me to best many other knights in duels.",
  ui_story_5084_50841102_43_dialog_content = "My brother, however, was not so fortunate...",
  ui_story_5084_50841102_44_dialog_content = "When the son of a rival family attacked him, I tried to protect him without realizing the scope of my own powers...",
  ui_story_5084_50841102_45_dialog_content = "And as a result...!",
  ui_story_5084_50841102_46_dialog_content = "My poor brother... He knew how shameful it would have been for our family... If a sinner like me continued to live in that pure and noble city.",
  ui_story_5084_50841102_47_dialog_content = "So he decided to free me, letting my \"rare blood\" manifest and subsequently... banished me from Lumopolis.",
  ui_story_5084_50841102_48_dialog_content = "Where have I seen that before...",
  ui_story_5084_50841102_49_dialog_content = "Then you moved around before Victoria recruited you into the True Order?",
  ui_story_5084_50841102_50_dialog_content = "Yes, even though I had hoped to die in the war between Aurorians and Eclipsites.",
  ui_story_5084_50841102_51_dialog_content = "But the Lord must have pegged me as a sinner, since Rare Blood kept dragging me out of coma time after time to remind me...",
  ui_story_5084_50841102_52_dialog_content = "I haven't atoned yet... I still can't return to the Lord of Truth.",
  ui_story_5084_50841102_53_dialog_content = "...",
  ui_story_5084_50841102_54_dialog_content = "Did I say too much? Sorry, Mr. Wilhelm, I thought, rather naively, that I'd been pardoned and back in the Lord's good graces.",
  ui_story_5084_50841102_55_dialog_content = "Your story sounds like you were born to a noble family and very talented to me.",
  ui_story_5084_50841102_56_dialog_content = "But that inept brother of yours held a grudge against you and wanted to be the patriarch, thus plotting to eliminate you.",
  ui_story_5084_50841102_57_dialog_content = "He's taken over as the patriarch now, hasn't he?",
  ui_story_5084_50841102_58_dialog_content = "Oh, he deserved it, and it wasn't a \"plot to eliminate\".",
  ui_story_5084_50841102_59_dialog_content = "Well, I have my doubts... Child of Lumopolis, kind, courageous, optimistic?",
  ui_story_5084_50841102_60_dialog_content = "The twelfth chief of the True Order is a heretic shunned by Lumopolis.",
  ui_story_5084_50841102_61_dialog_content = "The True Order of today would not exist without him.",
  ui_story_5084_50841102_62_dialog_content = "I am indeed the heretic shunned by Lumopolis, but my brother...",
  ui_story_5084_50841102_63_dialog_content = "Tell me, how did he look when you left?",
  ui_story_5084_50841102_64_dialog_content = "...",
  ui_story_5084_50841102_65_dialog_content = "I doubt you'd ever forget it. His face as he watched the brother he did everything to ruin go into exile.",
  ui_story_5084_50841102_66_dialog_content = "He smiled and wished me well.",
  ui_story_5084_50841102_67_dialog_content = "Hah! They always found something to blame you for, to persecute you.",
  ui_story_5084_50841102_68_dialog_content = "Therefore, you thought you were unredeemable and joined the True Order, while holding on to the self-guilt and torment.",
  ui_story_5084_50841102_69_dialog_content = "The root of your penance is self-loathing. You loathe the Rare Blood!",
  ui_story_5084_50841102_70_dialog_content = "And the root of my hatred is the hope you have for those evildoers, who spoke ill of you yet you took that for the truth.",
  ui_story_5084_50841102_71_dialog_content = "Let me tell you, Rare Blood isn't a curse but a blessing from the Lord of Truth.",
  ui_story_5084_50841102_72_dialog_content = "The fact they helped you kill Eclipsites is proof. Make no doubt about it. You have no reason to hate yourself.",
  ui_story_5084_50841102_73_dialog_content = "He didn't deserve to be your brother, Nails. But the sad thing is you're a nice brother.",
  ui_story_5084_50841102_74_dialog_content = "Brothers betray and separate from each other... Fate decreed we meet here, Wilhelm Varaki.",
  ui_story_5084_50841102_75_dialog_content = "You really made sure to mock me again!",
  ui_story_5084_50841102_76_dialog_content = "Listen carefully, Nails. You're kind and courageous, but a little short of sweet. How does Hails sound? It's close to your name.",
  ui_story_5084_50841102_77_dialog_content = "You will enjoy true salvation if you choose to protect others with your Rare Blood.",
  ui_story_5084_50841102_78_dialog_content = "You are very bold to feel that way, but I...",
  ui_story_5084_50841102_79_dialog_content = "You can handle it—",
  ui_story_5084_50841102_80_dialog_content = "...",
  ui_story_5084_50841102_81_dialog_content = "The Lord shows a bias toward no one. If you cannot forgive yourself, how can He redeem you?",
  ui_story_5084_50841102_82_dialog_content = "Remember, only when you acknowledge yourself will the Lord acknowledge you.",
  ui_story_5084_50841102_83_dialog_content = "Why are you saying all this to me, Mr. Wilhelm?",
  ui_story_5084_50841102_84_dialog_content = "Because I know our encounter here has changed something forever.",
  ui_story_5084_50841102_85_dialog_content = "I firmly believe it's the Lord who sent you here.",
  ui_story_5084_50841102_86_dialog_content = "So this is not the end for you, Nails, but the beginning of your devotion. Will you learn with me?",
  ui_story_5084_50841102_87_dialog_content = "I will do anything to cleanse myself of the sins.",
  ui_story_5084_50841102_88_dialog_content = "Good. Let's begin then. We have a lot to be done, but not here.",
  ui_story_5084_50841102_89_dialog_content = "This is where the past ends, and your three years of cultivation started from the Advent of Truth upon your arrival.",
  ui_story_5084_50841102_90_dialog_content = "Your leader has returned there. Lay inside the casket behind me and recall the Advent of Truth in Varaki, where you'll find your fellows.",
  ui_story_5084_50841102_91_dialog_content = "When you open your eyes again, find me at the Advent of Truth. I'll make sure you get initiated and receive the blessings of The Truth.",
  ui_story_5084_50841102_92_dialog_content = "How do I get there?",
  ui_story_5084_50841102_93_dialog_content = "Through your faith, Nails.",
  ui_story_5084_50841102_94_dialog_content = "It's your faith that brought you here. Just feel it with your body.",
  ui_story_5084_50841102_95_dialog_content = "When you're born again with any blessing or celebration, you've discovered The Truth.",
  ui_story_5084_50841102_96_dialog_content = "Are you referring to faith...?",
  ui_story_5084_50841102_97_dialog_content = "Yes. From now on, I am your mentor.",
  ui_story_5084_50841102_98_dialog_content = "<color=#e8d9bb>At the entrance to a tailor's shop in Varaki Town</color>",
  ui_story_5084_50841102_99_dialog_content = "How did I get here?",
  ui_story_5084_50841102_100_dialog_content = "Are you here for the ceremonial robe, sir?",
  ui_story_5084_50841102_101_dialog_content = "Ceremonial robe...?",
  ui_story_5084_50841102_102_dialog_content = "No wonder you spoke in words we don't understand... You've known Mr. Wilhelm for a long time, I see.",
  ui_story_5084_50841102_103_dialog_content = "And the more enigmatic one at that.",
  ui_story_5084_50841102_104_dialog_content = "I can't believe I really thought I was chosen for the initiation... and actually went into the hall with that idea.",
  ui_story_5084_50841102_105_dialog_content = "I still can't believe everything that's happening to me. I don't even know when the first time I saw my mentor was.",
  ui_story_5084_50841102_106_dialog_content = "But when he sent me back to the Advent of Truth, that man did not recognize me...",
  ui_story_5084_50841102_107_dialog_content = "What then, Nails? What happened after Wilhelm threw you out of the church?",
  ui_story_5084_50841102_108_dialog_content = "...",
  ui_story_5084_50841102_109_dialog_content = "Oh, may all sinful blood drain out of me... I will never pray for the Lord's redemption again...",
  ui_story_5084_50841102_110_dialog_content = "I am a sinner... Unforgivable sins...",
  ui_story_5084_50841102_111_dialog_content = "I'm a monster that brings doom to all, even here.",
  ui_story_5084_50841102_112_dialog_content = "In my hurry to get to the Advent of Truth, I let the seamstress and her daughter down.",
  ui_story_5084_50841102_113_dialog_content = "They lost the opportunity to make a living because they met me...",
  ui_story_5084_50841102_114_dialog_content = "Those people saw right through me, wouldn't approve my initiation and wanted to kill me instead...",
  ui_story_5084_50841102_115_dialog_content = "I'm not an initiate... I am to blame for the trouble between my mentor and the Order.",
  ui_story_5084_50841102_116_dialog_content = "Wherever I go, I am shunned...",
  ui_story_5084_50841102_117_dialog_content = "Aghhhh!",
  ui_story_5084_50841102_118_dialog_content = "My hands and feet are getting numb... The chill I just felt is now a warmth I've been missing...",
  ui_story_5084_50841102_119_dialog_content = "Might as well...",
  ui_story_5084_50841102_120_dialog_content = "I'd die in silence with my sins. No more trouble for the world.",
  ui_story_5084_50841102_121_dialog_content = "I...",
  ui_story_5084_50841102_122_dialog_content = "I am pondering whether I have not made myself clear.",
  ui_story_5084_50841102_123_dialog_content = "...?",
  ui_story_5084_50841102_124_dialog_content = "Why do you hate such a marvelous gift as the Rare Blood so much?",
  ui_story_5084_50841102_125_dialog_content = "Mentor? My mentor! You're okay!",
  ui_story_5084_50841102_126_dialog_content = "Don't move. Let me take a look at your wound.",
  ui_story_5084_50841102_127_dialog_content = "It was me that you met, but not the original or the present me.",
  ui_story_5084_50841102_128_dialog_content = "I have been observing the events all along and still cannot figure out what you're guilty of.",
  ui_story_5084_50841102_129_dialog_content = "I'm sure you can tell I have monsters in me...",
  ui_story_5084_50841102_130_dialog_content = "Monsters? Even the past me could recognize how frightfully powerful you are and that you're destined to be with the True Order.",
  ui_story_5084_50841102_131_dialog_content = "You should know the future I see for the Order is a congregation of the eccentric yet graceful, sensible yet wise.",
  ui_story_5084_50841102_132_dialog_content = "As long you keep uncovering your own uniqueness, time will take you to the right place and the right people.",
  ui_story_5084_50841102_133_dialog_content = "I told you, you are learning with me. Everything you've experienced is a part of that process, too.",
  ui_story_5084_50841102_134_dialog_content = "I see you didn't take me seriously and tried to kill yourself in guilt.",
  ui_story_5084_50841102_135_dialog_content = "Punish me, please... I didn't follow what I promised you, my mentor...",
  ui_story_5084_50841102_136_dialog_content = "It's all right. You were humiliated, which caused you to stray off course. Not your fault.",
  ui_story_5084_50841102_137_dialog_content = "But now that you've come to the right place, you must shine with your unique abilities.",
  ui_story_5084_50841102_138_dialog_content = "Me...?",
  ui_story_5084_50841102_139_dialog_content = "Think carefully. Everyone else aside, has Rare Blood tried to hurt you at any time?",
  ui_story_5084_50841102_140_dialog_content = "...",
  ui_story_5084_50841102_141_dialog_content = "The abundance that makes the advantaged fall from grace is perhaps what will save the displaced.",
  ui_story_5084_50841102_142_dialog_content = "It's you who has been damaging your soul with others' sins, thus overlooking the very thing trying to save you and them.",
  ui_story_5084_50841102_143_dialog_content = "Why wouldn't you believe Rare Blood could slay monsters and save others?",
  ui_story_5084_50841102_144_dialog_content = "They will avoid me... dislike my...",
  ui_story_5084_50841102_145_dialog_content = "They again... Listen up, that notion belongs in the past. Don't fall for it ever again.",
  ui_story_5084_50841102_146_dialog_content = "To quote you, \"I will do anything to cleanse myself of the sins.\" The first step, then, is to believe you have no sin.",
  ui_story_5084_50841102_147_dialog_content = "Can you do that?",
  ui_story_5084_50841102_148_dialog_content = "Mr. Wilhelm...",
  ui_story_5084_50841102_149_dialog_content = "Yes, I know you're definitely smart enough to get that.",
  ui_story_5084_50841102_150_dialog_content = "Follow me back to my domicile. It is perfectly secluded.",
  ui_story_5084_50841102_151_dialog_content = "From there, you can reach many towns to seek out and help lost sheep.",
  ui_story_5084_50841102_152_dialog_content = "Save them with your power. Guide them for their praise of Rare Blood.",
  ui_story_5084_50841102_153_dialog_content = "Rare Blood is blessed by The Truth. In time, you'll be able to understand it through meditation.",
  ui_story_5084_50841102_154_dialog_content = "I understand...",
  ui_story_5084_50841102_155_dialog_content = "Thus, I've been wandering for the last three years, curbing my temper and listening to what others say.",
  ui_story_5084_50841102_156_dialog_content = "I noticed my Rare Blood slowly changed after healing others' pain.",
  ui_story_5084_50841102_157_dialog_content = "But it was not until I helped out the seamstress and her daughter a moment ago that I realized the three years were well spent.",
  ui_story_5084_50841102_158_dialog_content = "In all these years with The True Order, I wouldn't listen and simply reiterate my repentance.",
  ui_story_5084_50841102_159_dialog_content = "I was my mentor who discovered the root of my sins. I was too busy talking to hear The Truth.",
  ui_story_5084_50841102_160_dialog_content = "My negative words shaped my thoughts and deepened my guilt...",
  ui_story_5084_50841102_161_dialog_content = "I didn't know what The Truth really was. That's why it refused to manifest in me.",
  ui_story_5084_50841102_162_dialog_content = "I now realize The Truth has been a part of my faith all along.",
  ui_story_5084_50841102_163_dialog_content = "Like pain, The Truth never showed bias toward anyone.",
  ui_story_5084_50841102_164_dialog_content = "Whatever I lost, I was supposed to lose. Whatever I gained, I was supposed to gain.",
  ui_story_5084_50841102_165_dialog_content = "One must have committed sin to repent. The disciples' blessings allowed me to be anointed by the Holy Blood.",
  ui_story_5084_50841102_166_dialog_content = "To be honest, I don't understand half of what you said, Mr. Nails...",
  ui_story_5084_50841102_167_dialog_content = "But I feel comforted by your demeanor as if I just took a warm bath.",
  ui_story_5084_50841102_168_dialog_content = "It's my mentor who made me believe that Rare Blood is not a sin but sacred, because the Lord of Truth is with me at all times.",
  ui_story_5084_50841102_169_dialog_content = "Lady Victoria will be pleased to know the changes in you.",
  ui_story_5084_50841102_170_dialog_content = "But I do not know how things are going with her.",
  ui_story_5084_50841102_171_dialog_content = "I believe in Lady Victoria! More importantly, I believe I can be of significant help to her!",
  ui_story_5084_50841102_172_dialog_content = "My mentor has put my training on pause. I need to do something important for the True Order with my power.",
  ui_story_5084_50841102_173_dialog_content = "Come, I want to bring my joy to Lady Victoria as well as more disciples.",
  ui_story_5084_50841201_1_dialog_content = "Even if no one else rides my train again, I promise you I'll convince Father to take you on a trip to Astra.",
  ui_story_5084_50841201_2_dialog_content = "<color=#e8d9bb>Splat, splat....</color>",
  ui_story_5084_50841201_3_dialog_content = "Hold on, let me shut the window.",
  ui_story_5084_50841201_4_dialog_content = "Whoa!",
  ui_story_5084_50841201_5_dialog_content = "<color=#e8d9bb>Smack!</color>",
  ui_story_5084_50841201_6_dialog_content = "That's weird. These disgusting worms have been hanging around here lately...",
  ui_story_5084_50841201_7_dialog_content = "But Father only told me to shut the windows and nothing else. I don't even know where he is right now.",
  ui_story_5084_50841201_8_dialog_content = "<color=#e8d9bb>The blood moon hung high over Varaki Town like a timeless clock, ringing for the Advent of Truth at midnight.</color>",
  ui_story_5084_50841201_9_dialog_content = "This is simply surreal. Why can't this happen every day of my life...?",
  ui_story_5084_50841201_10_dialog_content = "Are you referring to the appointment of a new leader for The True Order? There are mentions of someone being killed not too long ago.",
  ui_story_5084_50841201_11_dialog_content = "It's not unusual for leadership to change. But I'm more concerned about how those in charge always exclude everyone not of Varaki heritage.",
  ui_story_5084_50841201_12_dialog_content = "Maybe the glow of this blood moon shines only on that bloodline.",
  ui_story_5084_50841201_13_dialog_content = "It's never up to us to make it to the casket in the Temple of Truth and listen to the Lord's lecture.",
  ui_story_5084_50841201_14_dialog_content = "Don't fall for the the bloodline conspiracy theory. The Lord rejected the eldest daughter of the Varakis three years ago.",
  ui_story_5084_50841201_15_dialog_content = "And chose another follower in seclusion instead. He is now a saint and redeems others through the Lord's power.",
  ui_story_5084_50841201_16_dialog_content = "He is said to be not from here. Maybe The Truth can proliferate outside Varaki Town.",
  ui_story_5084_50841201_17_dialog_content = "This is indeed motivating. The heads of the families in the town seem to be facing a reform too.",
  ui_story_5084_50841201_18_dialog_content = "If it is Porfirio tonight, The True Order is going to have difficulties ahead...",
  ui_story_5084_50841201_19_dialog_content = "The world is changing, and so is The Truth. May it bless our home.",
  ui_story_5084_50841201_20_dialog_content = "Still no signs of Lady Victoria and PlayerName... I hope nothing happens to them.",
  ui_story_5084_50841201_21_dialog_content = "Lady Victoria's never gone back on her word. Maybe it's too crowded right now, and she'll show after the disciples disperse.",
  ui_story_5084_50841201_22_dialog_content = "No. Given the situation, I don't think she has any reason to hide.",
  ui_story_5084_50841201_23_dialog_content = "PlayerName is present, too, and should stand out in the crowd.",
  ui_story_5084_50841201_24_dialog_content = "Mr. Faust is right! I have a feeling I'll witness a True Order miracle tonight!",
  ui_story_5084_50841201_25_dialog_content = "What a story I'll have for Lenore!",
  ui_story_5084_50841201_26_dialog_content = "Despite the recent murder spree in town, the followers still turn out for the event.",
  ui_story_5084_50841201_27_dialog_content = "I guess that's the True Order tradition that has lasted until the year 2000 of the Morning Calendar for you.",
  ui_story_5084_50841201_28_dialog_content = "I will remain vigilant and make sure all disciples stay safe throughout the ceremony.",
  ui_story_5084_50841201_29_dialog_content = "It's been a long while, and Lady Victoria is still not here.",
  ui_story_5084_50841201_30_dialog_content = "Did you see that Varaki girl is in the ceremony?",
  ui_story_5084_50841201_31_dialog_content = "Yeah, and wearing a gorgeous outfit too... That's a violation of True Order rules!",
  ui_story_5084_50841201_32_dialog_content = "(Did she go back and change? Where is she?)",
  ui_story_5084_50841201_33_dialog_content = "There are always issues between her and her uncle. It's normal for her to not follow the rules.",
  ui_story_5084_50841201_34_dialog_content = "Are the Varakis going to give up on the position of the heads of families?",
  ui_story_5084_50841201_35_dialog_content = "Can't be... I heard Lady Victoria came back specifically to lead The True Order.",
  ui_story_5084_50841201_36_dialog_content = "Really? But in the Advent of Truth three years ago, didn't she...",
  ui_story_5084_50841201_37_dialog_content = "Who knows? It was she who got into the coffin, not us.",
  ui_story_5084_50841201_38_dialog_content = "I can't explain this, but it's been hundreds of years and I'm more comfortable with a Varaki leading The True Order.",
  ui_story_5084_50841201_39_dialog_content = "Sorry to keep you waiting.",
  ui_story_5084_50841201_40_dialog_content = "Wow... Did you make it a point to change into something fitting the event?",
  ui_story_5084_50841201_41_dialog_content = "Not quite. This dress is a gift from those who are still missing Varakis and know I'm in town.",
  ui_story_5084_50841201_42_dialog_content = "Something this fine cannot be done by one or two people in such a short time.",
  ui_story_5084_50841201_43_dialog_content = "Perhaps the party involved is trying to voice their objection to the powerful cabal of leaders through this.",
  ui_story_5084_50841201_44_dialog_content = "So, to appreciate their effort and show that you have what it takes to lead the Order...",
  ui_story_5084_50841201_45_dialog_content = "You have to wear this for tonight's ceremony?",
  ui_story_5084_50841201_46_dialog_content = "Authority has nothing to do with outfits. I can exhibit my power in any costume, old or new.",
  ui_story_5084_50841201_47_dialog_content = "But exciting changes are also exactly what this historic town has been missing.",
  ui_story_5084_50841201_48_dialog_content = "Like Bloody Bible, the ring, and the blood moon, it is all means to mark the moments people believed to be important.",
  ui_story_5084_50841201_49_dialog_content = "If the heads of families hate such salient changes, then that's exactly what I'll show them.",
  ui_story_5084_50841201_50_dialog_content = "Since to them, a woman adopting a flamboyant image is saying farewell to her submissive past.",
  ui_story_5084_50841201_51_dialog_content = "Yes. I just want to say that the outfit fits you to a tee.",
  ui_story_5084_50841201_52_dialog_content = "PlayerName! PlayerName!",
  ui_story_5084_50841201_53_dialog_content = "It's you!",
  ui_story_5084_50841201_54_dialog_content = "Yes, it's Lady Victoria, someone I can spot in any crowd!",
  ui_story_5084_50841201_55_dialog_content = "I couldn't believe it was you when I saw you from a distance.",
  ui_story_5084_50841201_56_dialog_content = "How do I look?",
  ui_story_5084_50841201_57_dialog_content = "It's Lady Victoria! And more stunning than before!",
  ui_story_5084_50841201_58_dialog_content = "It seems everything is fine with you, Lady Victoria. Congratulations.",
  ui_story_5084_50841201_59_dialog_content = "Nails underwent great changes, I see.",
  ui_story_5084_50841201_60_dialog_content = "It's been a long time, Lady Victoria! I credit my mentor for the results...",
  ui_story_5084_50841201_61_dialog_content = "I have so much I want to say to you!",
  ui_story_5084_50841201_62_dialog_content = "Yes, I saw you on the street. I look forward to hearing it later.",
  ui_story_5084_50841201_63_dialog_content = "It's almost time.",
  ui_story_5084_50841201_64_dialog_content = "But we just saw undead wounding people, Lady Victoria...",
  ui_story_5084_50841201_65_dialog_content = "I now know what the recent rumor in town regarding the Black Rider is about.",
  ui_story_5084_50841201_66_dialog_content = "Come, followers on the street. Wilhelm will ensure they are safe.",
  ui_story_5084_50841201_67_dialog_content = "The True Order must show its strength tonight. Follow me to the church.",
  ui_story_5084_50841201_68_dialog_content = "Yes!",
  ui_story_5084_50841201_69_dialog_content = "May The Truth forever bless The True Order.",
  ui_story_5084_50841201_70_dialog_content = "<color=#e8d9bb>Creak!</color>",
  ui_story_5084_50841201_71_dialog_content = "They're...",
  ui_story_5084_50841201_72_dialog_content = "All on the ground as if...",
  ui_story_5084_50841201_73_dialog_content = "...",
  ui_story_5084_50841201_74_dialog_content = "They've stopped breathing, Lady Victoria.",
  ui_story_5084_50841201_75_dialog_content = "...!",
  ui_story_5084_50841201_76_dialog_content = "Let me try to help them... I'm willing to bear the pain for them.",
  ui_story_5084_50841201_77_dialog_content = "Hey, I see the head of the Varaki family and her minions are finally here.",
  ui_story_5084_50841201_78_dialog_content = "This is a True Order celebration, how can I not be present?",
  ui_story_5084_50841201_79_dialog_content = "Lady Victoria...",
  ui_story_5084_50841201_80_dialog_content = "...",
  ui_story_5084_50841201_81_dialog_content = "Clavis is wounded in many places...",
  ui_story_5084_50841201_82_dialog_content = "That is the consequence of betraying me.",
  ui_story_5084_50841201_83_dialog_content = "Whatever you do is fine... just don't hurt Charon or my wife...",
  ui_story_5084_50841201_84_dialog_content = "Hurting people in the Temple of Truth...",
  ui_story_5084_50841201_85_dialog_content = "Stay where you are, Varaki!",
  ui_story_5084_50841201_86_dialog_content = "Why you...!",
  ui_story_5084_50841201_87_dialog_content = "Get behind me, May.",
  ui_story_5084_50841201_88_dialog_content = "You must have forgotten a lot of the rules for vampires. I'll let Abraham explain to you just which ones you violated...",
  ui_story_5084_50841201_89_dialog_content = "You should not have come back, Victoria...",
  ui_story_5084_50841201_90_dialog_content = "Not even you can do anything about it, now that the ritual is over. All the \"sacrifices\" to the Lord have been made.",
  ui_story_5084_50841201_91_dialog_content = "Now, I'm only teaching my little ones not to waste food.",
  ui_story_5084_50841201_92_dialog_content = "Aurorians are a gift from the Lord of Truth. Do you think they're food?",
  ui_story_5084_50841201_93_dialog_content = "Oh, lady of the Varaki, don't you send your people out to procure fresh blood for you when you also get the thirst deep into the night?",
  ui_story_5084_50841201_94_dialog_content = "I myself did not squander one drop of the sacrifice that belonged to me.",
  ui_story_5084_50841201_95_dialog_content = "But the same cannot be said for Abraham, who not only wasted his share but lied to me too!",
  ui_story_5084_50841201_96_dialog_content = "!",
  ui_story_5084_50841201_97_dialog_content = "Stop it, Porfirio... Stop!",
  ui_story_5084_50841201_98_dialog_content = "Where's Wilhelm?!",
  ui_story_5084_50841201_99_dialog_content = "Stop, David Porfirio!",
  ui_story_5084_50841201_100_dialog_content = "So, do you call the shots now?",
  ui_story_5084_50841201_101_dialog_content = "Get it over here.",
  ui_story_5084_50841201_102_dialog_content = "Yes, Lady Victoria.",
  ui_story_5084_50841201_103_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5084_50841201_104_dialog_content = "What are you doing, Vine?",
  ui_story_5084_50841201_105_dialog_content = "I'm just following Miss Varaki's orders to deliver the parade coffin to you, Lord Porfirio.",
  ui_story_5084_50841201_106_dialog_content = "Don't tell me you think the ancestral remains of Varaki would scare me.",
  ui_story_5084_50841201_107_dialog_content = "Or are you trying to run away with the same trick Wilhelm Varaki pulled?",
  ui_story_5084_50841201_108_dialog_content = "It's Wilhelm in the coffin.",
  ui_story_5084_50841201_109_dialog_content = "...?",
  ui_story_5084_50841201_110_dialog_content = "You've hurt him without mercy as it is and you want more?",
  ui_story_5084_50841201_111_dialog_content = "Well, I'm down to my last thread of patience...",
  ui_story_5084_50841201_112_dialog_content = "After I'm done with the blood in this bottle, I think I might have to feed off you.",
  ui_story_5084_50841201_113_dialog_content = "Come closer and tell me what shenanigans you and Wilhelm are up to.",
  ui_story_5084_50841201_114_dialog_content = "Wilhelm is dead.",
  ui_story_5084_50841201_115_dialog_content = "Liar!",
  ui_story_5084_50841201_116_dialog_content = "Watch out, Victoria!",
  ui_story_5084_50841201_117_dialog_content = "Over my dead body!",
  ui_story_5084_50841201_118_dialog_content = "This isn't new for someone trying to build a group around The Truth, but it is rare for you minions to protect your superior like this.",
  ui_story_5084_50841201_119_dialog_content = "Don't take me for a fool, however. I saw you two kill Viper and Gold Rush.",
  ui_story_5084_50841201_120_dialog_content = "Are you spooked? Viper and Gold Rush, as well as all you conspirators, will die by his sword.",
  ui_story_5084_50841201_121_dialog_content = "So, regardless of how you try to torment, assassinate, or bury Wilhelm Varaki, you can never kill him.",
  ui_story_5084_50841201_122_dialog_content = "Wilhelm... is not dead? He is alive...?",
  ui_story_5084_50841201_123_dialog_content = "...",
  ui_story_5084_50841201_124_dialog_content = "Not dead... so Varaki could become a spirit after dying?",
  ui_story_5084_50841201_125_dialog_content = "There are no spirits in the world! The revenants only became what they were after absorbing the power of Porfirio.",
  ui_story_5084_50841201_126_dialog_content = "This is my power over the revenants... One and only in the history of vampire houses!",
  ui_story_5084_50841201_127_dialog_content = "Make no joke about it, it is not resurrection. Not a chance.",
  ui_story_5084_50841201_128_dialog_content = "You thought the power held by the Varakis was just an ancestral gift used to see into the future?",
  ui_story_5084_50841201_129_dialog_content = "...?",
  ui_story_5084_50841201_130_dialog_content = "Just a moment ago, I made a pact with Bloody Bible for its approval as the leader of The True Order.",
  ui_story_5084_50841201_131_dialog_content = "The disciples bow and return to The Truth with pious praises...",
  ui_story_5084_50841201_132_dialog_content = "I should know by now the selection of Varaki is just the Varakis' means of holding on to power.",
  ui_story_5084_50841201_133_dialog_content = "I, Porfirio, should have had the honor long ago and bear the duty of returning the Order to the followers.",
  ui_story_5084_50841201_134_dialog_content = "Vampires are the rulers of blood and night. Why should I serve the creatures of light?",
  ui_story_5084_50841201_135_dialog_content = "The title should be mine, and I will master the populace in accordance with how the ancestors wanted it. That is what the Bloody Bible revealed to me!",
  ui_story_5084_50841301_1_dialog_content = "<color=#e8d9bb>The fierce, mindless fight led to an overturned casket for everyone present to witness...</color>",
  ui_story_5084_50841301_2_dialog_content = "<color=#e8d9bb>A brand new Bloody Bible landing by Victoria's feet... as destined.</color>",
  ui_story_5084_50841301_3_dialog_content = "The Truth would like to finish paving the road to redemption, and it apparently prefers me for its proxy.",
  ui_story_5084_50841301_4_dialog_content = "Calamity Codex, manifest!",
  ui_story_5084_50841301_5_dialog_content = "...",
  ui_story_5084_50841301_6_dialog_content = "What is that supposed to be?",
  ui_story_5084_50841301_7_dialog_content = "The prophetic Codex offered you glimpses of the future, but you failed to capitalize on that while stumbling around like an infant learning to walk.",
  ui_story_5084_50841301_8_dialog_content = "This Codex, baptized in the Pristine River, knows all... It is omniscient.",
  ui_story_5084_50841301_9_dialog_content = "The new chapter has been revealed, and I shall turn the page over!",
  ui_story_5084_50841301_10_dialog_content = "Would you like to witness its revelations of when you were born, when you will die, and when you will repent?",
  ui_story_5084_50841301_11_dialog_content = "...!",
  ui_story_5084_50841301_12_dialog_content = "The rest of you who are consorting with Porfirio, listen up.",
  ui_story_5084_50841301_13_dialog_content = "The third head of twelve families, Porfirio...",
  ui_story_5084_50841301_14_dialog_content = "... has fallen prone to bloodthirst under the blood moon, murdered numerous disciples, imbibed their blood, and controlled the dead through a family heirloom, the Golden Pipe.",
  ui_story_5084_50841301_15_dialog_content = "He colluded with the head of the Order's abolished family to release an evil entity upon Varaki Town and slaughter followers.",
  ui_story_5084_50841301_16_dialog_content = "That forsaken child...?",
  ui_story_5084_50841301_17_dialog_content = "The thirteenth head sought the Lord of Truth's descent in the Dark Zone.",
  ui_story_5084_50841301_18_dialog_content = "Then led a false god to town, attacked disciples, and sabotaged the Lord's ceremony.",
  ui_story_5084_50841301_19_dialog_content = "David Porfirio created and seized the opportunity to drain blood from wounded followers.",
  ui_story_5084_50841301_20_dialog_content = "Is that the prospect you want to lead all of you and the Order?",
  ui_story_5084_50841301_21_dialog_content = "...",
  ui_story_5084_50841301_22_dialog_content = "Stop all this nonsense!",
  ui_story_5084_50841301_23_dialog_content = "By the power of the <color=#FFB400>Ring of Varaki</color>, show your <color=#FFB400>true nature</color>!",
  ui_story_5084_50841301_24_dialog_content = "—!",
  ui_story_5084_50841301_25_dialog_content = "I-I thought the thirteenth family would help me. I thought imbibing the blood of the followers would grow my power.",
  ui_story_5084_50841301_26_dialog_content = "The rest of the rulers received the Lord's blessing and switched to another alternative.",
  ui_story_5084_50841301_27_dialog_content = "Except me... My thirst for blood only grew. I must rely on this levitating blood vial now just to barely sustain myself.",
  ui_story_5084_50841301_28_dialog_content = "Apparently, you do not realize the head of the thirteenth family never felt any of this is in the pact between you.",
  ui_story_5084_50841301_29_dialog_content = "Sacrificing you is no different from sacrificing all creatures to her. She was just using you.",
  ui_story_5084_50841301_30_dialog_content = "<color=#FFB400>She</color> joined Eclipse and became one of the <color=#FFB400>Wraiths</color>. Did you think you could outsmart her?",
  ui_story_5084_50841301_31_dialog_content = "Shut up!",
  ui_story_5084_50841301_32_dialog_content = "You, Victoria Varaki... How is it possible for you to control me with the ring?",
  ui_story_5084_50841301_33_dialog_content = "No, this can't be... This is not how the Ring of Varaki acted before.",
  ui_story_5084_50841301_34_dialog_content = "I have mastered it and aligned it with all of Varaki's ancestors.",
  ui_story_5084_50841301_35_dialog_content = "What you are facing is the combined power of the Varaki Clan. Confess your sins now!",
  ui_story_5084_50841301_36_dialog_content = "Heh, I...",
  ui_story_5084_50841301_37_dialog_content = "I killed Wilhelm!",
  ui_story_5084_50841301_38_dialog_content = "But I did it to rid The True Order of the real roadblock!",
  ui_story_5084_50841301_39_dialog_content = "How could a twisted second son of Varaki, who lived in seclusion and harmed his brother, lead the Order?",
  ui_story_5084_50841301_40_dialog_content = "Wilhelm didn't harm anyone!",
  ui_story_5084_50841301_41_dialog_content = "It's not your place to speak!",
  ui_story_5084_50841301_42_dialog_content = "—!",
  ui_story_5084_50841301_43_dialog_content = "The Bloody Bible is a Varaki relic. It bestows power to the holder and frees me from fear.",
  ui_story_5084_50841301_44_dialog_content = "Even when I killed to satiate my lust for blood, it still approved and gave me power.",
  ui_story_5084_50841301_45_dialog_content = "No one in The True Order could hope to defy me!",
  ui_story_5084_50841301_46_dialog_content = "Bloody Bible, please grant me the power to eradicate Varakis!",
  ui_story_5084_50841301_47_dialog_content = "...",
  ui_story_5084_50841301_48_dialog_content = "Bloody Bible...!",
  ui_story_5084_50841301_49_dialog_content = "You never understood the reason why the Varakis became leaders of the Order.",
  ui_story_5084_50841301_50_dialog_content = "We would never harm anyone with the Bloody Bible.",
  ui_story_5084_50841301_51_dialog_content = "Quite the opposite, it was the Bible that siphoned Varaki's blood in exchange for revealing the future.",
  ui_story_5084_50841301_52_dialog_content = "...?",
  ui_story_5084_50841301_53_dialog_content = "It is the same whether it's the forefathers, my parents, Wilhelm, and even me.",
  ui_story_5084_50841301_54_dialog_content = "These relics retained the will of every head of the house, be it rational or otherwise.",
  ui_story_5084_50841301_55_dialog_content = "Those making a pact must have the resolve to resist the tempting whispers to reach The Truth...",
  ui_story_5084_50841301_56_dialog_content = "And interpret the Lord of Truth's revelations on a higher level!",
  ui_story_5084_50841301_57_dialog_content = "What revelations have you glimpsed?",
  ui_story_5084_50841301_58_dialog_content = "...",
  ui_story_5084_50841301_59_dialog_content = "What are you going to do...?!",
  ui_story_5084_50841301_60_dialog_content = "Did you forget about the meeting?",
  ui_story_5084_50841301_61_dialog_content = "What revelation did you receive?",
  ui_story_5084_50841301_62_dialog_content = "<color=#FF0000>To purge the order.</color>",
  ui_story_5084_50841301_63_dialog_content = "Why you...!",
  ui_story_5084_50841301_64_dialog_content = "Disciples of Truth, recite the mantra with me!",
  ui_story_5084_50841301_65_dialog_content = "I, Nails, shall recite the mantra with my life!",
  ui_story_5084_50841301_66_dialog_content = "I, May, shall recite the mantra with Mr. Beau!",
  ui_story_5084_50841301_67_dialog_content = "Disciple Faust shall recite the mantra with Lady Victoria!",
  ui_story_5084_50841301_68_dialog_content = "Concede, David.",
  ui_story_5084_50841301_69_dialog_content = "Coward! The head of House Porfirio must lead The True Order!",
  ui_story_5084_50841301_70_dialog_content = "Farewell.",
  ui_story_5084_50841301_71_dialog_content = "All of you promised me!",
  ui_story_5084_50841301_72_dialog_content = "Enough. Our bargain expires on blood moon. I see I made the right bet! Have fun drinking blood.",
  ui_story_5084_50841301_73_dialog_content = "My undead!",
  ui_story_5084_50841301_74_dialog_content = "The heads of the families in the Order, you are invited to witness—",
  ui_story_5084_50841301_75_dialog_content = "...",
  ui_story_5084_50841301_76_dialog_content = "The Spirit of Truth coursing through all disciples. Please stand!",
  ui_story_5084_50841301_77_dialog_content = "Hear The Truth with me!",
  ui_story_5084_50841301_78_dialog_content = "The rippling flow that danced with me breached the void and emerged here.",
  ui_story_5084_50841301_79_dialog_content = "I am the Rune held by the Lord of Truth, waiting for his arrival on sacred ground.",
  ui_story_5084_50841301_80_dialog_content = "I am the Herald of Light, Conductor of Darkness! May Death manifest in the Realm of Immortality.",
  ui_story_5084_50841301_81_dialog_content = "Almighty Lord of Truth, please bestow divine powers through the revelations of Varaki blood in me!",
  ui_story_5084_50841301_82_dialog_content = "The Sacred Blood shall take form... I shall hear all confessions!",
  ui_story_5084_50841301_83_dialog_content = "The vine has been revived. May the Lord come to me!",
  ui_story_5084_50841301_84_dialog_content = "Come to me in this true nightmare! I shall unleash ancient powers!",
  ui_story_5084_50841301_85_dialog_content = "Lend us your power, Navigator of the Universal Truth who serves as the bridge to the Pristine River!",
  ui_story_5084_50841301_86_dialog_content = "What do you mean by Universal Truth and bridge to the Pristine River?",
  ui_story_5084_50841301_87_dialog_content = "Of course, I will help!",
  ui_story_5084_50841301_88_dialog_content = "He will see your contribution. The pact has been completed. Await the God's arrival with me!",
  ui_story_5084_50841302_1_dialog_content = "You came from the same bloodthirsty, filthy, cursed-from-birth race as me...",
  ui_story_5084_50841302_2_dialog_content = "What made you Varakis, deserving of monopolizing the position?",
  ui_story_5084_50841302_3_dialog_content = "The answer should be clear to you when you ask the question.",
  ui_story_5084_50841302_4_dialog_content = "Varaki...",
  ui_story_5084_50841302_5_dialog_content = "The thirst for blood, immortality, curse... Vampires must pay a certain price for the power.",
  ui_story_5084_50841302_6_dialog_content = "That notion has been with me and shaped me since I was born.",
  ui_story_5084_50841302_7_dialog_content = "But recently, I have come to the enlightened conclusion that everything I experienced isn't the cost, but what makes me deserving of the gift and guidance I receive.",
  ui_story_5084_50841302_8_dialog_content = "The Lord of Truth chose and granted us the power to lead changes and new eras.",
  ui_story_5084_50841302_9_dialog_content = "Any of the Eclipsites, weapons of an old civilization, or false gods could pose threats to Aurorians' survival.",
  ui_story_5084_50841302_10_dialog_content = "Let alone evil, heretical Aurorians such as yourself.",
  ui_story_5084_50841302_11_dialog_content = "Without leaving Varaki Town to observe the rivers or stars...",
  ui_story_5084_50841302_12_dialog_content = "Without seeing how this blessed planet of Eoria operates under the Lord's watch...",
  ui_story_5084_50841302_13_dialog_content = "You will never understand how the lone star fell, for it has happened too many times.",
  ui_story_5084_50841302_14_dialog_content = "When Aurorians face extinction again, only the Varaki chosen by the Lord can prevent Eoria's destruction.",
  ui_story_5084_50841302_15_dialog_content = "The ability to turn back fear of the unknown through greater poise is the foundation for the Chosen.",
  ui_story_5084_50841302_16_dialog_content = "David Porfirio, as a vampire who received the honor but failed to grasp The Truth, you must return the power the Lord has granted you.",
  ui_story_5084_50841302_17_dialog_content = "It has nothing to do with understanding or the Lord's choice. Varakis are the only ones vampires recognize.",
  ui_story_5084_50841302_18_dialog_content = "Porfirios started as the descendants of Varakis...",
  ui_story_5084_50841302_19_dialog_content = "But my forefathers lost their places due to Varaki oppressions, subsequently preventing me from gaining approval...",
  ui_story_5084_50841302_20_dialog_content = "Several centuries later, it remains the same. You don't have the right to speak about enlightenment.",
  ui_story_5084_50841302_21_dialog_content = "You—and the Varakis—will never escape the fate of vampires.",
  ui_story_5084_50841302_22_dialog_content = "Haha... Hahaha...",
  ui_story_5084_50841302_23_dialog_content = "...",
  ui_story_5084_50841302_24_dialog_content = "Miss Varaki... I mean, Lady Victoria...",
  ui_story_5084_50841302_25_dialog_content = "Did you truly receive revelations from the Lord in your travels abroad?",
  ui_story_5084_50841302_26_dialog_content = "We always have many ancient relics in our possession.",
  ui_story_5084_50841302_27_dialog_content = "How can we judge what came from the whispers and whether we are fit for the power granted by the Lord of Truth?",
  ui_story_5084_50841302_28_dialog_content = "The Order has always been known for the vampires' superior spirits, thus the ability to resonate with relics is a gift.",
  ui_story_5084_50841302_29_dialog_content = "But over the years, power struggles between the heads of families and complacency have muddled the message in the relics passed on through generations.",
  ui_story_5084_50841302_30_dialog_content = "For many of the relics, it wasn't until I established attunement that I realized they contained nothing but maddening pain and screams.",
  ui_story_5084_50841302_31_dialog_content = "Fear is the basis for check-and-balances between Aurorians and objects.",
  ui_story_5084_50841302_32_dialog_content = "All Varaki successors paced every night from that fear, causing their body and mind to deteriorate under the burden...",
  ui_story_5084_50841302_33_dialog_content = "That is why I pored over tomes and scrolls for Aurorian wisdom and knowledge to control our innate instincts.",
  ui_story_5084_50841302_34_dialog_content = "Through which, I was able to navigate the voices and to the Lord's embrace.",
  ui_story_5084_50841302_35_dialog_content = "Continuing to ask questions and explore, then suppress weakness until they fear us and submit instead is, to me, the way.",
  ui_story_5084_50841302_36_dialog_content = "We are grateful for the insight, Lady Victoria.",
  ui_story_5084_50841302_37_dialog_content = "But I must say it does not apply exclusively to vampires.",
  ui_story_5084_50841302_38_dialog_content = "In my journey, I have found non vampiric Aurorians with unknown abilities to attract special objects.",
  ui_story_5084_50841302_39_dialog_content = "It may just be a wheel, a spoke...",
  ui_story_5084_50841302_40_dialog_content = "A vine, a piece of paper...",
  ui_story_5084_50841302_41_dialog_content = "A pet, a white suitcase...",
  ui_story_5084_50841302_42_dialog_content = "Depending on the owner, different amazing potentials were unlocked.",
  ui_story_5084_50841302_43_dialog_content = "I believe you have not seen malleable blood that could kill Eclipsites.",
  ui_story_5084_50841302_44_dialog_content = "My followers claim to have met a disciple capable of that on the streets before.",
  ui_story_5084_50841302_45_dialog_content = "...",
  ui_story_5084_50841302_46_dialog_content = "Disciples like that permeate the world. The Order should integrate into Aurorian societies and propagate The Truth, bringing such power into our fold.",
  ui_story_5084_50841302_47_dialog_content = "Others who also received revelations do exist but are scattered throughout the world, not realizing what they mean.",
  ui_story_5084_50841302_48_dialog_content = "We, as vampires, must compile the revelations to let the Lord of Truth know it is time for His arrival and lead Aurorians into the future.",
  ui_story_5084_50841302_49_dialog_content = "If that is the case, I approve of leaving town and spreading The Truth among Aurorians.",
  ui_story_5084_50841302_50_dialog_content = "Build followings and amass influence...",
  ui_story_5084_50841302_51_dialog_content = "But how can we get the message to the Lord?",
  ui_story_5084_50841302_52_dialog_content = "If I told you there is a Navigator able to reach the Pristine River through relics and even command those same relics...",
  ui_story_5084_50841302_53_dialog_content = "Wouldn't you eagerly anticipate The Order's future as well?",
  ui_story_5084_50841302_54_dialog_content = "What Navigator?",
  ui_story_5084_50841302_55_dialog_content = "Hey, I never said I was joining the Order of Truth!",
  ui_story_5084_50841302_56_dialog_content = "Hand me the candlestick, Caelestite.",
  ui_story_5084_50841302_57_dialog_content = "Huh? But there are so many people here...",
  ui_story_5084_50841302_58_dialog_content = "Hand it to me.",
  ui_story_5084_50841302_59_dialog_content = "...",
  ui_story_5084_50841302_60_dialog_content = "This is... a Caelestite, an ally of The Order.",
  ui_story_5084_50841302_61_dialog_content = "Uh, hi, everyone.",
  ui_story_5084_50841302_62_dialog_content = "I've heard of the Caelestites. They could pilot Colossi and were telepathic.",
  ui_story_5084_50841302_63_dialog_content = "Have you been here all along, Caelestite?",
  ui_story_5084_50841302_64_dialog_content = "Well, to be accurate, I'm around a lot of time, but I don't show myself for various reasons.",
  ui_story_5084_50841302_65_dialog_content = "Telepathic... Isn't that identical to the vampire's ability to resonate?",
  ui_story_5084_50841302_66_dialog_content = "No, it is not the same.",
  ui_story_5084_50841302_67_dialog_content = "As I mentioned, vampires communicate with relics through bloodline.",
  ui_story_5084_50841302_68_dialog_content = "Caelestite's telepathy actually shares in common the power possessed by vampires of a higher level, and that same power is also the foundation for all Aurorians.",
  ui_story_5084_50841302_69_dialog_content = "The Pristine River?",
  ui_story_5084_50841302_70_dialog_content = "Oh my! Have you tracked down the Ancient Scroll, Lady Victoria?",
  ui_story_5084_50841302_71_dialog_content = "No. No one has the scroll or knows its whereabouts.",
  ui_story_5084_50841302_72_dialog_content = "But the Pristine River behind the Ancient Scrolls has apparently been visited.",
  ui_story_5084_50841302_73_dialog_content = "I will seek that location, so I hereby would like to entrust the town to all of you.",
  ui_story_5084_50841302_74_dialog_content = "We will follow your words and the standard you've set.",
  ui_story_5084_50841302_75_dialog_content = "Really? Someone visited the Pristine River?",
  ui_story_5084_50841302_76_dialog_content = "Clavis Abraham, are you pondering whether to tell me the truth about killing Wilhelm?",
  ui_story_5084_50841302_77_dialog_content = "...",
  ui_story_5084_50841302_78_dialog_content = "I am here to borrow an object from you, Clavis.",
  ui_story_5084_50841302_79_dialog_content = "Faria the Black Box?",
  ui_story_5084_50841302_80_dialog_content = "Yes.",
  ui_story_5084_50841302_81_dialog_content = "Are you taking the Bloody Bible?!",
  ui_story_5084_50841302_82_dialog_content = "It's only a matter of time before the vampire seizes it from the tomb.",
  ui_story_5084_50841302_83_dialog_content = "He has no right to take it.",
  ui_story_5084_50841302_84_dialog_content = "That's because the succession of Varaki leaders left a mark on the minds of the house rulers.",
  ui_story_5084_50841302_85_dialog_content = "But even now, Victoria has not realized the significant power that is in her veins.",
  ui_story_5084_50841302_86_dialog_content = "Add in the fact that my history has marred the sanctity of the Varakis, the heads of families have long been eyeing my position.",
  ui_story_5084_50841302_87_dialog_content = "Should I no longer be around, they will certainly go after Victoria.",
  ui_story_5084_50841302_88_dialog_content = "And a True Order led by Porfirio will surely bring disaster to the world.",
  ui_story_5084_50841302_89_dialog_content = "About this, Wilhelm...",
  ui_story_5084_50841302_90_dialog_content = "Only when the light of a blood moon is cast upon the ivy on the night of Advent of Truth will the tomb be open to the heads of families.",
  ui_story_5084_50841302_91_dialog_content = "But it will be too late by then. We have discussed the possibilities regarding Faria the Black Box.",
  ui_story_5084_50841302_92_dialog_content = "Perhaps my brother trusted the book to you, his close friend, with the intention of letting me take it when the time was right.",
  ui_story_5084_50841302_93_dialog_content = "...",
  ui_story_5084_50841302_94_dialog_content = "Why the pregnant pause, Clavis?",
  ui_story_5084_50841302_95_dialog_content = "Wilhelm, assuming the box can open the tomb, it is forbidden by the common pact to take the book without all rulers present.",
  ui_story_5084_50841302_96_dialog_content = "I know.",
  ui_story_5084_50841302_97_dialog_content = "And yet you fully expressed the decision to break the pact to me... What are you thinking, Wilhelm?",
  ui_story_5084_50841302_98_dialog_content = "How old is Victoria now?",
  ui_story_5084_50841302_99_dialog_content = "Why do you ask?",
  ui_story_5084_50841302_100_dialog_content = "You've been caring for her for many years. That ambitious, selfish younger you...",
  ui_story_5084_50841302_101_dialog_content = "Has become an old man watching out for others.",
  ui_story_5084_50841302_102_dialog_content = "If you only knew how well Victoria and I usually get along, you probably wouldn't say that.",
  ui_story_5084_50841302_103_dialog_content = "What I want to say is do you know why I moved to Old Town?",
  ui_story_5084_50841302_104_dialog_content = "For Charon, without a doubt.",
  ui_story_5084_50841302_105_dialog_content = "Yes, Wilhelm. Charon's mother and I no longer wish to fret over the Order, much less let Charon join it.",
  ui_story_5084_50841302_106_dialog_content = "You backed off.",
  ui_story_5084_50841302_107_dialog_content = "No, Wilhelm, I took a difficult step forward for Charon's sake.",
  ui_story_5084_50841302_108_dialog_content = "What if I said you must give me the box for Charon and his mother to stay clear of trouble?",
  ui_story_5084_50841302_109_dialog_content = "...",
  ui_story_5084_50841302_110_dialog_content = "The Order can benefit only when the Bible is in Varaki hands. In all my inherited memories, that is the sole means to bring about reform!",
  ui_story_5084_50841302_111_dialog_content = "You seem to have reverted to your ambitious ways.",
  ui_story_5084_50841302_112_dialog_content = "Haven't the maddening voices trying to corrupt you punished you enough?",
  ui_story_5084_50841302_113_dialog_content = "That's right, I have ambitions! But so what?!",
  ui_story_5084_50841302_114_dialog_content = "Should I keep wallowing in the self-pity of being overshadowed by a talented, powerful brother? No! Never!",
  ui_story_5084_50841302_115_dialog_content = "...",
  ui_story_5084_50841302_116_dialog_content = "Sorry, Clavis. I didn't mean to say that.",
  ui_story_5084_50841302_117_dialog_content = "What I meant to say is I'm not doing it for me this time. It's for Victoria.",
  ui_story_5084_50841302_118_dialog_content = "I cannot agree with that, Wilhelm...",
  ui_story_5084_50841302_119_dialog_content = "What are you afraid of, exactly? Can't you see things are getting worse?",
  ui_story_5084_50841302_120_dialog_content = "Porfirio and the house rulers have stopped following the rules after branching off the Varaki bloodline.",
  ui_story_5084_50841302_121_dialog_content = "How good is it for you to follow the rules alone?",
  ui_story_5084_50841302_122_dialog_content = "The rules for vampires have always been a shackle. It's an impediment to The True Order now, to you, to me, to everyone in town.",
  ui_story_5084_50841302_123_dialog_content = "That's the nature of vampires, except you're more fortunate than us.",
  ui_story_5084_50841302_124_dialog_content = "When did you decide to bow to fate too?",
  ui_story_5084_50841302_125_dialog_content = "Do not fault me for this, Wilhelm. I simply cannot deny what I know to be true...",
  ui_story_5084_50841302_126_dialog_content = "That key will only bring you harm.",
  ui_story_5084_50841302_127_dialog_content = "But you don't plan on helping either, do you?",
  ui_story_5084_50841302_128_dialog_content = "...",
  ui_story_5084_50841302_129_dialog_content = "It's okay, Clavis. I'll think of something.",
  ui_story_5084_50841302_130_dialog_content = "I didn't give the Black Box to Wilhelm, and neither had the intent to kill him at the time.",
  ui_story_5084_50841302_131_dialog_content = "I thought I could just watch the rulers... kill him on the evening of Advent of Truth.",
  ui_story_5084_50841302_132_dialog_content = "...",
  ui_story_5084_50841302_133_dialog_content = "<size=45>Aahhhh!</size>",
  ui_story_5084_50841302_134_dialog_content = "Haha, hahaha...",
  ui_story_5084_50841302_135_dialog_content = "Clavis...",
  ui_story_5084_50841302_136_dialog_content = "Sorry, Wilhelm...",
  ui_story_5084_50841302_137_dialog_content = "I must afford Charon a clean slate.",
  ui_story_5084_50841302_138_dialog_content = "I know you'll understand from caring for Victoria.",
  ui_story_5084_50841302_139_dialog_content = "Victoria...",
  ui_story_5084_50841302_140_dialog_content = "Heh...",
  ui_story_5084_50841302_141_dialog_content = "Sorry...!",
  ui_story_5084_50841302_142_dialog_content = "I thought you'd never come around, Clavis.",
  ui_story_5084_50841302_143_dialog_content = "Did you think hiding her with your tricks would change anything, Wilhelm?",
  ui_story_5084_50841302_144_dialog_content = "Doomed to a disgraceful death in your very own hometown... How I pity you, Wilhelm Varaki.",
  ui_story_5084_50841302_145_dialog_content = "...",
  ui_story_5084_50841302_146_dialog_content = "Well, it's moot for the Ring of Varaki to be passed down now.",
  ui_story_5084_50841302_147_dialog_content = "<color=#e8d9bb>David Porfirio nudged the bloody canister behind him and applied the greatest force he had ever exerted between his fingers.</color>",
  ui_story_5084_50841302_148_dialog_content = "<color=#e8d9bb>He crushed the Ring of Varaki as silver and red dust splattered on Wilhelm.</color>",
  ui_story_5084_50841302_149_dialog_content = "What have you done? By crushing the ring, you've...",
  ui_story_5084_50841302_150_dialog_content = "It's useless to you or me now. Let the debris rest with Wilhelm in peace.",
  ui_story_5084_50841302_151_dialog_content = "From this day forth, it cannot be used to threaten us ever again.",
  ui_story_5084_50841302_152_dialog_content = "The shackle that is the heads of Varaki is in the past!",
  ui_story_5084_50841302_153_dialog_content = "I must say, you sure put on a scrumptious feast for the Advent of Truth, David!",
  ui_story_5084_50841302_154_dialog_content = "But Wilhelm is dead...!",
  ui_story_5084_50841302_155_dialog_content = "Yes, with your help. We must still follow the hierarchy in tasting Varaki blood.",
  ui_story_5084_50841302_156_dialog_content = "After myself, it is of course, my closest friend—Clavis.",
  ui_story_5084_50841302_157_dialog_content = "Once my guys are fed, Wilhelm is all yours.",
  ui_story_5084_50841302_158_dialog_content = "Since you two are old friends, you can give him a burial.",
  ui_story_5084_50841302_159_dialog_content = "I mean, resting eternally in a coffin is one of our traditions, after all.",
  ui_story_5084_50841302_160_dialog_content = "But don't forget to beg him for forgiveness. Maybe he can still hear the words of a friend who stabbed him in the back.",
  ui_story_5084_50841302_161_dialog_content = "So, will you stop making it hard for Charon and my wife now?",
  ui_story_5084_50841302_162_dialog_content = "Of course. But Clavis, there's something I don't quite understand... Is it true that my guys saw you planning to move?",
  ui_story_5084_50841302_163_dialog_content = "...",
  ui_story_5084_50841302_164_dialog_content = "That would make it harder for me to ask you for more favors, wouldn't it?",
  ui_story_5084_50841302_165_dialog_content = "Why you...!",
  ui_story_5084_50841302_166_dialog_content = "Hahaha!",
  ui_story_5084_50841302_167_dialog_content = "Fool.",
  ui_story_5084_50841302_168_dialog_content = "You got ears on the ground, Gold Rush. Don't forget to track Victoria down for me.",
  ui_story_5084_50841302_169_dialog_content = "What have I done... What have I done?!",
  ui_story_5084_50841302_170_dialog_content = "<color=#e8d9bb>Clavis carried the dead Wilhelm to the tomb of the Varaki.</color>",
  ui_story_5084_50841302_171_dialog_content = "<color=#e8d9bb>However, the keeper declined his request to bury Wilhelm within.</color>",
  ui_story_5084_50841302_172_dialog_content = "The universal key—<color=#FFB400>Faria the Black Box</color>!",
  ui_story_5084_50841302_173_dialog_content = "<color=#e8d9bb>The relic appeared and tore a rift. Through the crack in The Flow, Clavis entered the crypt.</color>",
  ui_story_5084_50841302_174_dialog_content = "This is the Varaki Tomb, Wilhelm. Even though nowhere else is safer for you, I must leave as soon as possible.",
  ui_story_5084_50841302_175_dialog_content = "I hope you will rest in peace and return to the Lord of Truth like your ancestors have.",
  ui_story_5084_50841302_176_dialog_content = "The key will only spell trouble for me.",
  ui_story_5084_50841302_177_dialog_content = "It is inevitable for Porfirio to find out if I should keep it.",
  ui_story_5084_50841302_178_dialog_content = "If the forefathers saw the event, let the agony of betrayal be my punishment.",
  ui_story_5084_50841302_179_dialog_content = "The True Order... Varaki... We tried, but couldn't control their fate.",
  ui_story_5084_50841302_180_dialog_content = "Wilhelm... Vampires... Have we all remained the prisoners of fate at the end, anyway?",
  ui_story_5084_50841302_181_dialog_content = "<color=#e8d9bb>As the tombkeeper watches in silence, Clavis places the Black Box inside the casket with Wilhelm.</color>",
  ui_story_5084_50841302_182_dialog_content = "<color=#e8d9bb>Neither is aware that the universal key arbitrarily opens a door called \"Fate.\"</color>",
  ui_story_5084_50841302_183_dialog_content = "I won't try to defend myself. I deserve all this.",
  ui_story_5084_50841302_184_dialog_content = "For the betrayal, you must repent to the Lord of Truth immediately, Mr. Clavis.",
  ui_story_5084_50841302_185_dialog_content = "I won't ask for the Lord's forgiveness, for I cannot even face Wilhelm.",
  ui_story_5084_50841302_186_dialog_content = "...",
  ui_story_5084_50841302_187_dialog_content = "No one knows about that place other than you and me. And Wilhelm is dead.",
  ui_story_5084_50841302_188_dialog_content = "The day I decided to leave Varaki Town, you weren't looking for Wilhelm. You were looking for me.",
  ui_story_5084_50841302_189_dialog_content = "If you stayed, I would confess everything to you. But if you left...",
  ui_story_5084_50841302_190_dialog_content = "You would not have said a word.",
  ui_story_5084_50841302_191_dialog_content = "Frankly, not a day went by without me feeling the torment...",
  ui_story_5084_50841302_192_dialog_content = "You can take my life anytime you want. All I ask is for you to let me do one last thing.",
  ui_story_5084_50841302_193_dialog_content = "...",
  ui_story_5084_50841302_194_dialog_content = "Are you doing okay, Mr. Clavis?",
  ui_story_5084_50841302_195_dialog_content = "Charon and my wife have nothing to do with all this. I must give them a clean slate.",
  ui_story_5084_50841302_196_dialog_content = "But even if I stay alive, Charon will probably still hate me for sure...",
  ui_story_5084_50841302_197_dialog_content = "What can I do? Maybe this is another punishment for me.",
  ui_story_5084_50841302_198_dialog_content = "I remember Charon telling me about his father. They indeed have a rocky relationship.",
  ui_story_5084_50841302_199_dialog_content = "...",
  ui_story_5084_50841302_200_dialog_content = "Hey, the candle is almost out, Victoria.",
  ui_story_5084_50841400_1_dialog_content = "About this \"Universal Key,\" Lady Victoria...",
  ui_story_5084_50841400_2_dialog_content = "Master Clavis buried it with Mr. Wilhelm, who is nowhere to be seen now, so this is all I could find.",
  ui_story_5084_50841400_3_dialog_content = "Isn't this Black Box...?",
  ui_story_5084_50841400_4_dialog_content = "PlayerName...",
  ui_story_5084_50841400_5_dialog_content = "Oh, sorry, I forgot such information doesn't belong here.",
  ui_story_5084_50841400_6_dialog_content = "I know you'll be leaving, so I'm passing it on to the leader of The True Order, Lady Victoria!",
  ui_story_5084_50841400_7_dialog_content = "No, none of us can hope to control it. Just leave it here.",
  ui_story_5084_50841400_8_dialog_content = "Make sure no one touches it, not even me. Everything must follow the Lord's will.",
  ui_story_5084_50841400_9_dialog_content = "I have a request, Lady Victoria. Is it possible to not make me its keeper?",
  ui_story_5084_50841400_10_dialog_content = "You are supposed to be its keeper. When my father gave it to Clavis, it was likely that he already saw how his fate would unfold.",
  ui_story_5084_50841400_11_dialog_content = "I do not know how long I will be able to guard the tomb of the Varaki.",
  ui_story_5084_50841400_12_dialog_content = "With permission, I'd like to abdicate my position as a house ruler and be a vine full-time that guards the tomb and awaits your arrival.",
  ui_story_5084_50841400_13_dialog_content = "I can cast magic to vanish the tomb from the rulers' minds, but is there a truth you hold resolute in your heart?",
  ui_story_5084_50841400_14_dialog_content = "The truth is I wanted to leave the world from the beginning, and this tomb happened to be the perfect choice.",
  ui_story_5084_50841400_15_dialog_content = "It has nothing to do with who leads the Order. I'm not questioning your decision, of course, Lady Victoria.",
  ui_story_5084_50841400_16_dialog_content = "Do you still prefer to guard the tomb over freedom?",
  ui_story_5084_50841400_17_dialog_content = "My family is no more. I'll be alone wherever I am.",
  ui_story_5084_50841400_18_dialog_content = "Then, I shall grant you the right to seek your peace here.",
  ui_story_5084_50841400_19_dialog_content = "You are the Varakis' most loyal friend. You have the right to replace David Porfirio and watch over the town while I am away.",
  ui_story_5084_50841400_20_dialog_content = "I would not dare to dream that...!",
  ui_story_5084_50841400_21_dialog_content = "But that is the very ending you hoped for. You can start a new family and future.",
  ui_story_5084_50841400_22_dialog_content = "I recall you abandoning all past associations with Lumopolis, including your surname.",
  ui_story_5084_50841400_23_dialog_content = "Go ahead, choose a new surname and let it be the foundation of a new start.",
  ui_story_5084_50841400_24_dialog_content = "I understand, My Lady.",
  ui_story_5084_50841400_25_dialog_content = "I choose... Dantes.",
  ui_story_5084_50841400_26_dialog_content = "From this point forward, I shall be known as Graves Dantes.",
  ui_story_5084_50841400_27_dialog_content = "(Dantes?! He's the forefather to Sikare Dantes?)",
  ui_story_5084_50841400_28_dialog_content = "Since you have chosen your fate, let us continue.",
  ui_story_5084_50841400_29_dialog_content = "Your clan has been and always will be a trusted ally to the Varakis. The Black Box will watch over your bloodline.",
  ui_story_5084_50841400_30_dialog_content = "Understood. I shall take my leave now.",
  ui_story_5084_50841400_31_dialog_content = "Phew, looks like it's over.",
  ui_story_5084_50841400_32_dialog_content = "We are done with the Advent of Truth here, but there is another one waiting for us back in Vortex.",
  ui_story_5084_50841400_33_dialog_content = "No, that means three Advent of Truth! I'm starting to miss Lenore...",
  ui_story_5084_50841400_34_dialog_content = "Hey, the candle is really going to go out this time.",
  ui_story_5084_50841400_35_dialog_content = "...",
  ui_story_5084_50841400_36_dialog_content = "(Victoria seems to be expecting Wilhelm the way she gazes into the distance...)",
  ui_story_5084_50841400_37_dialog_content = "Let's go.",
  ui_story_5084_50841400_38_dialog_content = "Will you be taking both bibles with you, Lady Victoria?",
  ui_story_5084_50841400_39_dialog_content = "They will go where they are supposed to go on our way back. Let's get ready.",
  ui_story_5084_50841400_40_dialog_content = "The candle's out! Hey, you're still holding the old bible.",
  ui_story_5084_50841400_41_dialog_content = "It led us here for me to meet its new version, so it is time I return it to the hand of destiny.",
  ui_story_5084_50841400_42_dialog_content = "Victoria?",
  ui_story_5084_50841400_43_dialog_content = "<color=#e8d9bb>In the returning darkness, a crack appeared in the torrent of time. A long, odd sliver could be glimpsed in the haze.</color>",
  ui_story_5084_50841400_44_dialog_content = "<color=#e8d9bb>Victoria let go of the bible that had been with her for many years and watched it swim in the torrent.</color>",
  ui_story_5084_50841400_45_dialog_content = "Where did it go?",
  ui_story_5084_50841400_46_dialog_content = "Gaze into the torrent, and you might see The Truth.",
  ui_story_5084_50841400_47_dialog_content = "Any of us is but sand in the river. Ultimately, we will return to the Lord of Truth.",
  ui_story_5084_50841400_48_dialog_content = "Go and fulfill your destiny.",
  ui_story_5084_50841400_49_dialog_content = "<color=#e8d9bb>The bible flowed \"downstream\" and departed the \"future strangers\".</color>",
  ui_story_5084_50841400_50_dialog_content = "<color=#e8d9bb>It drifted peacefully in the Pristine River as countless images appeared in the ripples of its course, showing the past and the future.</color>",
  ui_story_5084_50841400_51_dialog_content = "<color=#e8d9bb>Its pages flapped open on their own and conjured letters on the erstwhile blank sheets.</color>",
  ui_story_5084_50841400_52_dialog_content = "<color=#e8d9bb>Thus, destiny was written...</color>",
  ui_story_5084_50841400_53_dialog_content = "<color=#e8d9bb>The reflection of the bible was cast into the stories and the tome began to receive recognition. It was finally a part of the river.</color>",
  ui_story_5084_50841400_54_dialog_content = "<color=#e8d9bb>\"Wilhelm picked up the Bloody Bible that came from parts unknown. He felt the presence of revelations within and decided to take it to a sleeping Victoria.\"</color>",
  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>\"The young Victoria browsed the blank tome and heard the prophecy of The Truth for the first time.\"</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>The book continued flowing downstream. Time had neither beginning nor end in the river but an endless cycle.</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>\"Therefore, Victoria let go of the bible that has been with her for many years and watched it swim in the torrent.\"</color>",
  ui_story_5084_50841400_58_dialog_content = "All travelers have returned to their respective times. I should finish up my job too.",
  ui_story_5084_50841400_59_dialog_content = "Victoria of the Year 1918, you're still on the path to discovering The Truth. You were still lost and everything must have seemed confusing to you.",
  ui_story_5084_50841400_60_dialog_content = "That is all right. Time will lead you to it.",
  ui_story_5084_50841400_61_dialog_content = "You will embark on a long journey before attaining enlightenment.",
  ui_story_5084_50841400_62_dialog_content = "Then you will take them back to this very point and we shall meet again.",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>Wilhelm delivered the sleeping Victoria from Vortex to her and put the Bloody Bible in her hand.</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>He then laid inside the coffin in which he came and pondered his past.</color>",
  ui_story_5084_50841400_65_dialog_content = "When you, as a young child, met me for the first time, it was because your brother wished to entrust you to me, for he was about to die.",
  ui_story_5084_50841400_66_dialog_content = "So I could become the leader?",
  ui_story_5084_50841400_67_dialog_content = "Yes, and then care for Victoria.",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>Victoria stood silently by her parents, not comprehending the reason for their contentment even though they were dying.</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>But Wilhelm Varaki, who had endured countless humiliations, couldn't bear to lead the shattered Victoria down the fateful path of the vampires.</color>",
  ui_story_5084_50841400_70_dialog_content = "Stop wasting your breath. I won't do it.",
  ui_story_5084_50841400_71_dialog_content = "...",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>But on the day of the funeral, Wilhelm still donned the outfit of a disciple and watched his brother and sister-in-law leave Varaki Town in caskets.</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>Wilhelm lingered outside the tomb of the Varaki, listening to the heads of families' \"greetings\" for Victoria.</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>The forces of the storm and lightning that seemed intended to tear the world apart reflected Wilhelm's emotions.</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>He charged to the heart of the tomb just to put on the Ring of Varaki that could corrupt him in front of all...</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>Only to protect the girl who was about to embark on the quest for The Truth with him.</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>It hadn't been a happy relationship between them, but Wilhelm must compel Victoria to stop resisting the Order and to grow stronger.</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>All the while searching for any option to keep them safe.</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>Also about his own death...</color>",
  ui_story_5084_50841400_80_dialog_content = "Clavis...",
  ui_story_5084_50841400_81_dialog_content = "I know you'll understand from caring for Victoria.",
  ui_story_5084_50841400_82_dialog_content = "Victoria...",
  ui_story_5084_50841400_83_dialog_content = "Heh...",
  ui_story_5084_50841400_84_dialog_content = "(According to vampire traditions, death is perhaps a blessing.)",
  ui_story_5084_50841400_85_dialog_content = "(But this me does not feel the pain of other's betrayal anymore.)",
  ui_story_5084_50841400_86_dialog_content = "(I understand how difficult it is for you, but what will become of Victoria now?)",
  ui_story_5084_50841400_87_dialog_content = "(Have I passed every Truth I've learned on to her?)",
  ui_story_5084_50841400_88_dialog_content = "(Was she going to tell me she's on an unwavering path to The Truth before she left?)",
  ui_story_5084_50841400_89_dialog_content = "(...)",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>Wilhelm never stopped with questions for The Truth when his mind shifted to a clear river.</color>",
  ui_story_5084_50841400_91_dialog_content = "What's going on? Wasn't I in the church...? I should be dead right now.",
  ui_story_5084_50841400_92_dialog_content = "Where am I?",
  ui_story_5084_50841400_93_dialog_content = "The Realm of the Dead, or the Temple of the Lord of Truth?",
  ui_story_5084_50841400_94_dialog_content = "What is this river?",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>Wilhelm drifted endlessly without moving, but his mind took in all the information in the world.</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>A decade? A century? How long has it been...?</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>Eoria darkened and brightened again, as the conflict between Aurorians and Eclipsites waged on.</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>But he drifted through all that.</color>",
  ui_story_5084_50841400_99_dialog_content = "Is that me?",
  ui_story_5084_50841400_100_dialog_content = "That's not her desire but it is her destiny. Put this new Bloody Bible in the coffin for me. She'll find it useful.",
  ui_story_5084_50841400_101_dialog_content = "Yes, Mr. Wilhelm.",
  ui_story_5084_50841400_102_dialog_content = "And when that time comes...",
  ui_story_5084_50841400_103_dialog_content = "Why are you sad? You can just start a family and be done with it.",
  ui_story_5084_50841400_104_dialog_content = "Start a family and raise children? How boring.",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>Many versions of Wilhelm were scattered everywhere, yet stacked on top of each other. It was pure chaos until he saw presences other than himself.</color>",
  ui_story_5084_50841400_106_dialog_content = "I shall not take credit for it. This is a blessing from the Lord of Truth.",
  ui_story_5084_50841400_107_dialog_content = "What is this?",
  ui_story_5084_50841400_108_dialog_content = "The <color=#FFB400>Pristine River</color>, outside of time and space. The only difference from the outside world is that it flows.",
  ui_story_5084_50841400_109_dialog_content = "We won't be able to control our lives if this keeps up! Why did you bring us here?",
  ui_story_5084_50841400_110_dialog_content = "Victoria?!",
  ui_story_5084_50841400_111_dialog_content = "Heh, hahaha!",
  ui_story_5084_50841400_112_dialog_content = "I knew you could do it, Victoria Varaki.",
  ui_story_5084_50841400_113_dialog_content = "And Charon too.",
  ui_story_5084_50841400_114_dialog_content = "We did it as their elder, Clavis.",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>As the memories faded, Wilhelm got up only to realize he wasn't in his coffin—but watching and immersing in the ever-flowing Pristine River.</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>Everything he had interfered with would entangle him and take him to the Assertion of Truth.</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>Then...</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>The tome dropped by Victoria stopped drifting because it ran into a barrier—a \"dead\" lying in the river.</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>This betrayed corpse of Wilhelm, the man who the Door of Destiny called, awoke in the marvelous stream.</color>",
  ui_story_5084_50841400_120_dialog_content = "...?!",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>The befuddled Wilhelm managed to notice the Bloody Bible coming to a stop by his feet in the river.</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>As if answering a silent call, he flipped through the totally blank tome and started to see...</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>\"The Bloody Bible drifts and stops next to the dead Wilhelm's feet. The young vampire awakes due to a drop of blood in a ring debris.\"</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>\"The befuddled Wilhelm manages to notice the Bloody Bible coming to a stop by his feet in the river.\"</color>",
  ui_story_5084_50841400_125_dialog_content = "What?",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>\"Startled, Wilhelm stumbles backward into the river, soaking in the water he has disturbed and contaminating its causes and effects.\"</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>\"Seated in the river, Wilhelm notices he has something in his hand. As he picks it up in a shiver, he realizes it is...\"</color>",
  ui_story_5084_50841400_128_dialog_content = "The ancestral ring of Varaki?",
  ui_story_5084_50841400_129_dialog_content = "What does this all mean?",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>\"Having received the call, Wilhelm is destined to drift and lead others to The Truth.\"</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>\"When the time is right, the tomb of the Varaki will open for Victoria. Wilhelm, Servant of The Truth, shall be her guide.\"</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>\"Wilhelm then lays inside the coffin in which he came and ponders his past.\"</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>\"When he realizes his purpose has been fulfilled and Victoria is ready, will he finally rest in peace?\"</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>\"But when he touches the ring, a drop of Varaki blood inside it courses through his body. He falls into a slumber as the familiar feeling returns.\"</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>\"When Wilhelm wakes up again, he shall be guided to the crossroads of fate.\"</color>",
  ui_story_5084_50841400_136_dialog_content = "Where am I...",
  ui_story_5084_50841400_137_dialog_content = "Although Lady Victoria told me piety would show me the way...",
  ui_story_5084_50841400_138_dialog_content = "But I will sacrifice...",
  ui_story_5084_50841400_139_dialog_content = "I will...",
  ui_story_5084_50841400_140_dialog_content = "...",
  ui_story_5084_50841400_141_dialog_content = "... My lord?",
  ui_story_5084_50841400_142_dialog_content = "The great Lord of Truth!",
  ui_story_5084_50841400_143_dialog_content = "Did you just say... Lady Victoria?",
  ui_story_5084_50841400_144_dialog_content = "<color=#e8d9bb>\"Time has neither beginning nor end in the river but an endless cycle.\"</color>",
  ui_story_5084_50841400_145_dialog_content = "<color=#e8d9bb>\"Thus, Victoria lets go of the bible that has been with her for many years and watches it swim in the torrent.\"</color>",
  ui_story_5084_50841400_146_dialog_content = "You're back.",
  ui_story_5084_50841400_147_dialog_content = "Yes. The candle is gone.",
  ui_story_5084_50841400_148_dialog_content = "That kind of power belonged to Faria.",
  ui_story_5084_50841400_149_dialog_content = "Close, Faria.",
  ui_story_5084_50841400_150_dialog_content = "(I see... So the Starry Crypt was the tomb of the Varaki back then.)",
  ui_story_5084_50841400_151_dialog_content = "We meet again, \"Universal Key.\"",
  ui_story_5084_50841400_152_dialog_content = "Miss Victoria?",
  ui_story_5084_50841400_153_dialog_content = "Heh, please excuse my mumbling to myself.",
  ui_story_5084_50841400_154_dialog_content = "Sure.",
  ui_story_5084_50841400_155_dialog_content = "May?",
  ui_story_5084_50841400_156_dialog_content = "What are you doing here, Lenore?",
  ui_story_5084_50841400_157_dialog_content = "You weren't home after the bread was made, so I figured you came to see Sikare. I didn't expect to see Miss Victoria and everyone else here too.",
  ui_story_5084_50841400_158_dialog_content = "Wait, I think I heard food being mentioned...",
  ui_story_5084_50841400_159_dialog_content = "Pleasant bread and wine... all personally prepared by May for the Advent of Truth!",
  ui_story_5084_50841400_160_dialog_content = "I am hungry now that you said that.",
  ui_story_5084_50841400_161_dialog_content = "You will come to the celebration with us, won't you, Sikare?",
  ui_story_5084_50841400_162_dialog_content = "Yes. I will certainly answer Victoria's invitation.",
  ui_story_5084_50841400_163_dialog_content = "It's about time. The members of the Order should be assembling in town, Lady Victoria.",
  ui_story_5084_50841400_164_dialog_content = "Will everyone from the Order be there?",
  ui_story_5084_50841400_165_dialog_content = "You were reluctant when we invited you. Are you filled with anticipation now?",
  ui_story_5084_50841400_166_dialog_content = "I can't say I see my friends from the Order very often, but it is always good to be in their company.",
  ui_story_5084_50841400_167_dialog_content = "Welcome, everyone, to The True Order's triennial celebration.",
  ui_story_5084_50841400_168_dialog_content = "In the three years since, we are one step closer to understanding Eoria as well as the Lord of Truth.",
  ui_story_5084_50841400_169_dialog_content = "Other than the immortal Lord, we do not follow any fixed precepts, regardless of our background.",
  ui_story_5084_50841400_170_dialog_content = "Whether it be our unique individualities, escaping the shackles of the past, or fulfilling a certain purpose...",
  ui_story_5084_50841400_171_dialog_content = "Because of continuous transformation, we are shining brightly on the journey toward The Truth.",
  ui_story_5084_50841400_172_dialog_content = "The True Order you see now is on the path blessed by The Truth.",
  ui_story_5084_50841400_173_dialog_content = "I can assure you that those vampires outside Astra with close ties to the Order are ready.",
  ui_story_5084_50841400_174_dialog_content = "And I will lead all of you to witness the Lord of Truth's arrival.",
  ui_story_5084_50841400_175_dialog_content = "In the Darkover Crisis, the Bloody Bible revealed a huge revolution to come.",
  ui_story_5084_50841400_176_dialog_content = "The revolutionaries I was nurturing back then have grown into maturity.",
  ui_story_5084_50841400_177_dialog_content = "The lock shall appear in the Dark Zone. I shall bring the key to the destination and rebuild the kingdom with the Lord.",
  ui_story_5084_50841400_178_dialog_content = "It will be a treacherous journey through the Dark Zone. Once again, the True Order will guide Aurorians through the crisis as their ally.",
  ui_story_5084_50841400_179_dialog_content = "Now please enjoy the feast.",
  ui_story_5084_50841400_180_dialog_content = "It was He who honored me and granted the Nourishment of Truth to you.",
  ui_story_5084_50841400_181_dialog_content = "You are also welcome to exchange your personal enlightenment with others.",
  ui_story_5084_50841400_182_dialog_content = "May The Truth bless you.",
  ui_story_5084_50841400_183_dialog_content = "May The Truth bless you.",
  ui_story_5084_50841400_184_dialog_content = "You've been peeking at Faust for a while now, Pasolo. Is something wrong with him?",
  ui_story_5084_50841400_185_dialog_content = "Well, Mr. Faust, it's about the souls of my deceased parents. Miss Sikare thought perhaps you could offer me a new perspective...",
  ui_story_5084_50841400_186_dialog_content = "If it is a new perspective you want, try Nails. He has developed more so than anyone lately.",
  ui_story_5084_50841400_187_dialog_content = "<color=#e8d9bb>Rumble, rumble...</color>",
  ui_story_5084_50841400_188_dialog_content = "Help me stop the thing, PlayerName!",
  ui_story_5084_50841400_189_dialog_content = "Oh no, it's too fast... and it's rolling toward Nails!",
  ui_story_5084_50841400_190_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5084_50841400_191_dialog_content = "Sorry, Mr. Nails! Hunting Stone didn't hurt you, did it?",
  ui_story_5084_50841400_192_dialog_content = "No, Miss Pact. If you wish to make me feel pain, you can stab me with thorns here.",
  ui_story_5084_50841400_193_dialog_content = "Mr. Nails! Didn't you promise you wouldn't hurt yourself tonight? Did that have anything to do with your new outfit?",
  ui_story_5084_50841400_194_dialog_content = "Mr. Nails, Mr. Faust told me you could give me a new perspective on souls.",
  ui_story_5084_50841400_195_dialog_content = "Ah, perspective... My mentor indeed offered some to me.",
  ui_story_5084_50841400_196_dialog_content = "I believe the soul is the concentration of one's spirit. As long as the spirit remains, one is never truly gone.",
  ui_story_5084_50841400_197_dialog_content = "I see... Then, will I be able to see the deceased again?",
  ui_story_5084_50841400_198_dialog_content = "Maybe Victoria has the answer to that.",
  ui_story_5084_50841400_199_dialog_content = "Hey, it's been a long time and I can feel the holy aura hitting me.",
  ui_story_5084_50841400_200_dialog_content = "How do you do, Mr. Telamont.",
  ui_story_5084_50841400_201_dialog_content = "Did you pick up something in your time with Lady Victoria?",
  ui_story_5084_50841400_202_dialog_content = "It was an honor for me to meet an important mentor. It was he who led me to my transformation under the Lord.",
  ui_story_5084_50841400_203_dialog_content = "I didn't think the ascetics could ever come around. Is your mentor here now?",
  ui_story_5084_50841400_204_dialog_content = "I am ashamed to admit I do not know...",
  ui_story_5084_50841400_205_dialog_content = "Lady Victoria, Mr. Nails said, \"As long as the spirit remains, one is never truly gone.\"",
  ui_story_5084_50841400_206_dialog_content = "Does that mean my dead parents have been with me all this time?",
  ui_story_5084_50841400_207_dialog_content = "Aurorians were born from the light of faith. Their spiritual power came from a high river.",
  ui_story_5084_50841400_208_dialog_content = "You should pray some of your parents' spirits returned there.",
  ui_story_5084_50841400_209_dialog_content = "I should pray for them...",
  ui_story_5084_50841400_210_dialog_content = "Thank you for the answer, Lady Victoria. I will dwell on it some more...",
  ui_story_5084_50841400_211_dialog_content = "<color=#e8d9bb>Victoria was touched to see how strong the Order has become.</color>",
  ui_story_5084_50841400_212_dialog_content = "<color=#e8d9bb>It was the result of the past Wilhelm and her present self clearing the barriers for the young Victoria to move forward.</color>",
  ui_story_5084_50841400_213_dialog_content = "<color=#e8d9bb>The guidance they received could come from someone in the past or future, trying their best to convey their intent in the flow of time and space.</color>",
  ui_story_5084_50841400_214_dialog_content = "<color=#e8d9bb>Victoria saw countless travelers in the River of Fate, each one representing the courage to seek The Truth.</color>",
  ui_story_5084_50841400_215_dialog_content = "<color=#e8d9bb>It would all be seen by a certain someone drifting in the flow of time.</color>",
  ui_story_5084_50841400_216_dialog_content = "<color=#e8d9bb>The currents would alternate as written in the tome, but Victoria had no desire to turn the page that quickly.</color>",
  ui_story_5084_50841400_217_dialog_content = "Does that mean you believe in seclusion as much as I do?",
  ui_story_5084_50841400_218_dialog_content = "Though I can understand why they wouldn't attend any celebration, it's always that way with the recluses.",
  ui_story_5084_50841400_219_dialog_content = "Do the recluses have their own organization?",
  ui_story_5084_50841400_220_dialog_content = "Not exactly, but the sect is said to have been founded by a mysterious male disciple in Varaki Town around 1915.",
  ui_story_5084_50841400_221_dialog_content = "Has Lady Victoria never told you?",
  ui_story_5084_50841400_222_dialog_content = "Compared to your presence in Aurorian towns, I've only met a handful of self-proclaimed recluses out in the wild.",
  ui_story_5084_50841400_223_dialog_content = "What do you usually do?",
  ui_story_5084_50841400_224_dialog_content = "Seek empty spaces or explore hidden corners.",
  ui_story_5084_50841400_225_dialog_content = "Then what?",
  ui_story_5084_50841400_226_dialog_content = "Stay there and do nothing.",
  ui_story_5084_50841400_227_dialog_content = "This so-called seclusion sounds like not wanting to learn from books to me...",
  ui_story_5084_50841400_228_dialog_content = "That's probably because there wasn't any book a master recluse had not read.",
  ui_story_5084_50841400_229_dialog_content = "But why do I get the feeling that, in your case, you have the books but chose not to read them...",
  ui_story_5084_50841400_230_dialog_content = "He must be a great figure! May I ask for his name?",
  ui_story_5084_50841400_231_dialog_content = "No one knows his name, but I've seen him.",
  ui_story_5084_50841400_232_dialog_content = "Slender, with a certain air of traditional nobility...",
  ui_story_5084_50841400_233_dialog_content = "Because he often wears a black top hat, a reddish black cloak, and a black horse.",
  ui_story_5084_50841400_234_dialog_content = "...?",
  ui_story_5084_50841400_235_dialog_content = "He is inscrutable and travels a lot. Some claimed he was hoping for a chance to meet an old friend.",
  ui_story_5084_50841400_236_dialog_content = "Could that be my mentor?",
  ui_story_5084_50841400_237_dialog_content = "Who?",
  ui_story_5084_50841400_238_dialog_content = "The old friend he would like to meet...",
  ui_story_5084_50841400_239_dialog_content = "<color=#e8d9bb>\"When all things have ended, come find me here,\" that was what he said.</color>",
  ui_story_5084_50841400_240_dialog_content = "<color=#e8d9bb>Victoria was still by the window as she saw right through time and became fixated on the figures chasing after The Truth.</color>",
  ui_story_5084_50841400_241_dialog_content = "<color=#e8d9bb>Like the stars in the night sky, some of them were bright, some faint, but every one of them interpreted The Truth in their own way.</color>",
  ui_story_5084_50841400_242_dialog_content = "<color=#e8d9bb>Victoria understood that seeking Truth is akin to chasing faraway stars and demanded insight from the mind's eyes.</color>",
  ui_story_5084_50841400_243_dialog_content = "<color=#e8d9bb>But he was merely the guide leading them forward.</color>",
  ui_story_5084_50841400_244_dialog_content = "<color=#e8d9bb>Outside the window, he sighed. He has come to see every member of the True Order as his child.</color>",
  ui_story_5084_50841400_245_dialog_content = "<color=#e8d9bb>He knew regardless of how arduous the path was for them, Victoria would always provide light in the darkest hour.</color>",
  ui_story_5084_50841400_246_dialog_content = "<color=#e8d9bb>But only he knew the woman next to the window was a lonely seeker too.</color>",
  ui_story_5084_50841400_247_dialog_content = "<color=#e8d9bb>Victoria closed her eyes and let her heart echo through the night.</color>",
  ui_story_5084_50841400_248_dialog_content = "<color=#e8d9bb>She understood there are different passages to The Truth, whether it is lonely seclusion or a boisterous Order.</color>",
  ui_story_5084_50841400_249_dialog_content = "<color=#e8d9bb>\"The Truth is a never-ending quest,\" he muttered.</color>",
  ui_story_5084_50841400_250_dialog_content = "<color=#e8d9bb>\"And I shall watch over you and guide you in your journey.\"</color>"
}
return config
